window.KH_SURA(11, {"sura": "هود", "n": 11, "ayat": {"1": "الر كِتَابٌ أُحْكِمَتْ آيَاتُهُ ثُمَّ فُصِّلَتْ مِنْ لَدُنْ حَكِيمٍ خَبِيرٍ", "2": "أَلَّا تَعْبُدُوا إِلَّا اللَّهَ إِنَّنِي لَكُمْ مِنْهُ نَذِيرٌ وَبَشِيرٌ", "3": "وَأَنِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُمَتِّعْكُمْ مَتَاعًا حَسَنًا إِلَى أَجَلٍ مُسَمًّى وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ وَإِنْ تَوَلَّوْا فَإِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ كَبِيرٍ", "4": "إِلَى اللَّهِ مَرْجِعُكُمْ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "5": "أَلَا إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا مِنْهُ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ", "6": "وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا كُلٌّ فِي كِتَابٍ مُبِينٍ", "7": "وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَلَئِنْ قُلْتَ إِنَّكُمْ مَبْعُوثُونَ مِنْ بَعْدِ الْمَوْتِ لَيَقُولَنَّ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُبِينٌ", "8": "وَلَئِنْ أَخَّرْنَا عَنْهُمُ الْعَذَابَ إِلَى أُمَّةٍ مَعْدُودَةٍ لَيَقُولُنَّ مَا يَحْبِسُهُ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "9": "وَلَئِنْ أَذَقْنَا الْإِنْسَانَ مِنَّا رَحْمَةً ثُمَّ نَزَعْنَاهَا مِنْهُ إِنَّهُ لَيَئُوسٌ كَفُورٌ", "10": "وَلَئِنْ أَذَقْنَاهُ نَعْمَاءَ بَعْدَ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ السَّيِّئَاتُ عَنِّي إِنَّهُ لَفَرِحٌ فَخُورٌ", "11": "إِلَّا الَّذِينَ صَبَرُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", "12": "فَلَعَلَّكَ تَارِكٌ بَعْضَ مَا يُوحَى إِلَيْكَ وَضَائِقٌ بِهِ صَدْرُكَ أَنْ يَقُولُوا لَوْلَا أُنْزِلَ عَلَيْهِ كَنْزٌ أَوْ جَاءَ مَعَهُ مَلَكٌ إِنَّمَا أَنْتَ نَذِيرٌ وَاللَّهُ عَلَى كُلِّ شَيْءٍ وَكِيلٌ", "13": "أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ", "14": "فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّمَا أُنْزِلَ بِعِلْمِ اللَّهِ وَأَنْ لَا إِلَهَ إِلَّا هُوَ فَهَلْ أَنْتُمْ مُسْلِمُونَ", "15": "مَنْ كَانَ يُرِيدُ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَالَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ", "16": "أُولَئِكَ الَّذِينَ لَيْسَ لَهُمْ فِي الْآخِرَةِ إِلَّا النَّارُ وَحَبِطَ مَا صَنَعُوا فِيهَا وَبَاطِلٌ مَا كَانُوا يَعْمَلُونَ", "17": "أَفَمَنْ كَانَ عَلَى بَيِّنَةٍ مِنْ رَبِّهِ وَيَتْلُوهُ شَاهِدٌ مِنْهُ وَمِنْ قَبْلِهِ كِتَابُ مُوسَى إِمَامًا وَرَحْمَةً أُولَئِكَ يُؤْمِنُونَ بِهِ وَمَنْ يَكْفُرْ بِهِ مِنَ الْأَحْزَابِ فَالنَّارُ مَوْعِدُهُ فَلَا تَكُ فِي مِرْيَةٍ مِنْهُ إِنَّهُ الْحَقُّ مِنْ رَبِّكَ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ", "18": "وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أُولَئِكَ يُعْرَضُونَ عَلَى رَبِّهِمْ وَيَقُولُ الْأَشْهَادُ هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى رَبِّهِمْ أَلَا لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ", "19": "الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُمْ بِالْآخِرَةِ هُمْ كَافِرُونَ", "20": "أُولَئِكَ لَمْ يَكُونُوا مُعْجِزِينَ فِي الْأَرْضِ وَمَا كَانَ لَهُمْ مِنْ دُونِ اللَّهِ مِنْ أَوْلِيَاءَ يُضَاعَفُ لَهُمُ الْعَذَابُ مَا كَانُوا يَسْتَطِيعُونَ السَّمْعَ وَمَا كَانُوا يُبْصِرُونَ", "21": "أُولَئِكَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ وَضَلَّ عَنْهُمْ مَا كَانُوا يَفْتَرُونَ", "22": "لَا جَرَمَ أَنَّهُمْ فِي الْآخِرَةِ هُمُ الْأَخْسَرُونَ", "23": "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَأَخْبَتُوا إِلَى رَبِّهِمْ أُولَئِكَ أَصْحَابُ الْجَنَّةِ هُمْ فِيهَا خَالِدُونَ", "24": "مَثَلُ الْفَرِيقَيْنِ كَالْأَعْمَى وَالْأَصَمِّ وَالْبَصِيرِ وَالسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ", "25": "وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَى قَوْمِهِ إِنِّي لَكُمْ نَذِيرٌ مُبِينٌ", "26": "أَنْ لَا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ", "27": "فَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ مَا نَرَاكَ إِلَّا بَشَرًا مِثْلَنَا وَمَا نَرَاكَ اتَّبَعَكَ إِلَّا الَّذِينَ هُمْ أَرَاذِلُنَا بَادِيَ الرَّأْيِ وَمَا نَرَى لَكُمْ عَلَيْنَا مِنْ فَضْلٍ بَلْ نَظُنُّكُمْ كَاذِبِينَ", "28": "قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِنْ كُنْتُ عَلَى بَيِّنَةٍ مِنْ رَبِّي وَآتَانِي رَحْمَةً مِنْ عِنْدِهِ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنْتُمْ لَهَا كَارِهُونَ", "29": "وَيَاقَوْمِ لَا أَسْأَلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَمَا أَنَا بِطَارِدِ الَّذِينَ آمَنُوا إِنَّهُمْ مُلَاقُو رَبِّهِمْ وَلَكِنِّي أَرَاكُمْ قَوْمًا تَجْهَلُونَ", "30": "وَيَاقَوْمِ مَنْ يَنْصُرُنِي مِنَ اللَّهِ إِنْ طَرَدْتُهُمْ أَفَلَا تَذَكَّرُونَ", "31": "وَلَا أَقُولُ لَكُمْ عِنْدِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ إِنِّي مَلَكٌ وَلَا أَقُولُ لِلَّذِينَ تَزْدَرِي أَعْيُنُكُمْ لَنْ يُؤْتِيَهُمُ اللَّهُ خَيْرًا اللَّهُ أَعْلَمُ بِمَا فِي أَنْفُسِهِمْ إِنِّي إِذًا لَمِنَ الظَّالِمِينَ", "32": "قَالُوا يَانُوحُ قَدْ جَادَلْتَنَا فَأَكْثَرْتَ جِدَالَنَا فَأْتِنَا بِمَا تَعِدُنَا إِنْ كُنْتَ مِنَ الصَّادِقِينَ", "33": "قَالَ إِنَّمَا يَأْتِيكُمْ بِهِ اللَّهُ إِنْ شَاءَ وَمَا أَنْتُمْ بِمُعْجِزِينَ", "34": "وَلَا يَنْفَعُكُمْ نُصْحِي إِنْ أَرَدْتُ أَنْ أَنْصَحَ لَكُمْ إِنْ كَانَ اللَّهُ يُرِيدُ أَنْ يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ", "35": "أَمْ يَقُولُونَ افْتَرَاهُ قُلْ إِنِ افْتَرَيْتُهُ فَعَلَيَّ إِجْرَامِي وَأَنَا بَرِيءٌ مِمَّا تُجْرِمُونَ", "36": "وَأُوحِيَ إِلَى نُوحٍ أَنَّهُ لَنْ يُؤْمِنَ مِنْ قَوْمِكَ إِلَّا مَنْ قَدْ آمَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَفْعَلُونَ", "37": "وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُمْ مُغْرَقُونَ", "38": "وَيَصْنَعُ الْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِنْ قَوْمِهِ سَخِرُوا مِنْهُ قَالَ إِنْ تَسْخَرُوا مِنَّا فَإِنَّا نَسْخَرُ مِنْكُمْ كَمَا تَسْخَرُونَ", "39": "فَسَوْفَ تَعْلَمُونَ مَنْ يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُقِيمٌ", "40": "حَتَّى إِذَا جَاءَ أَمْرُنَا وَفَارَ التَّنُّورُ قُلْنَا احْمِلْ فِيهَا مِنْ كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَنْ سَبَقَ عَلَيْهِ الْقَوْلُ وَمَنْ آمَنَ وَمَا آمَنَ مَعَهُ إِلَّا قَلِيلٌ", "41": "وَقَالَ ارْكَبُوا فِيهَا بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسَاهَا إِنَّ رَبِّي لَغَفُورٌ رَحِيمٌ", "42": "وَهِيَ تَجْرِي بِهِمْ فِي مَوْجٍ كَالْجِبَالِ وَنَادَى نُوحٌ ابْنَهُ وَكَانَ فِي مَعْزِلٍ يَابُنَيَّ ارْكَبْ مَعَنَا وَلَا تَكُنْ مَعَ الْكَافِرِينَ", "43": "قَالَ سَآوِي إِلَى جَبَلٍ يَعْصِمُنِي مِنَ الْمَاءِ قَالَ لَا عَاصِمَ الْيَوْمَ مِنْ أَمْرِ اللَّهِ إِلَّا مَنْ رَحِمَ وَحَالَ بَيْنَهُمَا الْمَوْجُ فَكَانَ مِنَ الْمُغْرَقِينَ", "44": "وَقِيلَ يَاأَرْضُ ابْلَعِي مَاءَكِ وَيَاسَمَاءُ أَقْلِعِي وَغِيضَ الْمَاءُ وَقُضِيَ الْأَمْرُ وَاسْتَوَتْ عَلَى الْجُودِيِّ وَقِيلَ بُعْدًا لِلْقَوْمِ الظَّالِمِينَ", "45": "وَنَادَى نُوحٌ رَبَّهُ فَقَالَ رَبِّ إِنَّ ابْنِي مِنْ أَهْلِي وَإِنَّ وَعْدَكَ الْحَقُّ وَأَنْتَ أَحْكَمُ الْحَاكِمِينَ", "46": "قَالَ يَانُوحُ إِنَّهُ لَيْسَ مِنْ أَهْلِكَ إِنَّهُ عَمَلٌ غَيْرُ صَالِحٍ فَلَا تَسْأَلْنِ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنِّي أَعِظُكَ أَنْ تَكُونَ مِنَ الْجَاهِلِينَ", "47": "قَالَ رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِنَ الْخَاسِرِينَ", "48": "قِيلَ يَانُوحُ اهْبِطْ بِسَلَامٍ مِنَّا وَبَرَكَاتٍ عَلَيْكَ وَعَلَى أُمَمٍ مِمَّنْ مَعَكَ وَأُمَمٌ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُمْ مِنَّا عَذَابٌ أَلِيمٌ", "49": "تِلْكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهَا إِلَيْكَ مَا كُنْتَ تَعْلَمُهَا أَنْتَ وَلَا قَوْمُكَ مِنْ قَبْلِ هَذَا فَاصْبِرْ إِنَّ الْعَاقِبَةَ لِلْمُتَّقِينَ", "50": "وَإِلَى عَادٍ أَخَاهُمْ هُودًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ إِنْ أَنْتُمْ إِلَّا مُفْتَرُونَ", "51": "يَاقَوْمِ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِيَ إِلَّا عَلَى الَّذِي فَطَرَنِي أَفَلَا تَعْقِلُونَ", "52": "وَيَاقَوْمِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُرْسِلِ السَّمَاءَ عَلَيْكُمْ مِدْرَارًا وَيَزِدْكُمْ قُوَّةً إِلَى قُوَّتِكُمْ وَلَا تَتَوَلَّوْا مُجْرِمِينَ", "53": "قَالُوا يَاهُودُ مَا جِئْتَنَا بِبَيِّنَةٍ وَمَا نَحْنُ بِتَارِكِي آلِهَتِنَا عَنْ قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ", "54": "إِنْ نَقُولُ إِلَّا اعْتَرَاكَ بَعْضُ آلِهَتِنَا بِسُوءٍ قَالَ إِنِّي أُشْهِدُ اللَّهَ وَاشْهَدُوا أَنِّي بَرِيءٌ مِمَّا تُشْرِكُونَ", "55": "مِنْ دُونِهِ فَكِيدُونِي جَمِيعًا ثُمَّ لَا تُنْظِرُونِ", "56": "إِنِّي تَوَكَّلْتُ عَلَى اللَّهِ رَبِّي وَرَبِّكُمْ مَا مِنْ دَابَّةٍ إِلَّا هُوَ آخِذٌ بِنَاصِيَتِهَا إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ", "57": "فَإِنْ تَوَلَّوْا فَقَدْ أَبْلَغْتُكُمْ مَا أُرْسِلْتُ بِهِ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّي قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُ شَيْئًا إِنَّ رَبِّي عَلَى كُلِّ شَيْءٍ حَفِيظٌ", "58": "وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا هُودًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَنَجَّيْنَاهُمْ مِنْ عَذَابٍ غَلِيظٍ", "59": "وَتِلْكَ عَادٌ جَحَدُوا بِآيَاتِ رَبِّهِمْ وَعَصَوْا رُسُلَهُ وَاتَّبَعُوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ", "60": "وَأُتْبِعُوا فِي هَذِهِ الدُّنْيَا لَعْنَةً وَيَوْمَ الْقِيَامَةِ أَلَا إِنَّ عَادًا كَفَرُوا رَبَّهُمْ أَلَا بُعْدًا لِعَادٍ قَوْمِ هُودٍ", "61": "وَإِلَى ثَمُودَ أَخَاهُمْ صَالِحًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ هُوَ أَنْشَأَكُمْ مِنَ الْأَرْضِ وَاسْتَعْمَرَكُمْ فِيهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي قَرِيبٌ مُجِيبٌ", "62": "قَالُوا يَاصَالِحُ قَدْ كُنْتَ فِينَا مَرْجُوًّا قَبْلَ هَذَا أَتَنْهَانَا أَنْ نَعْبُدَ مَا يَعْبُدُ آبَاؤُنَا وَإِنَّنَا لَفِي شَكٍّ مِمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ", "63": "قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِنْ كُنْتُ عَلَى بَيِّنَةٍ مِنْ رَبِّي وَآتَانِي مِنْهُ رَحْمَةً فَمَنْ يَنْصُرُنِي مِنَ اللَّهِ إِنْ عَصَيْتُهُ فَمَا تَزِيدُونَنِي غَيْرَ تَخْسِيرٍ", "64": "وَيَاقَوْمِ هَذِهِ نَاقَةُ اللَّهِ لَكُمْ آيَةً فَذَرُوهَا تَأْكُلْ فِي أَرْضِ اللَّهِ وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ", "65": "فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا فِي دَارِكُمْ ثَلَاثَةَ أَيَّامٍ ذَلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ", "66": "فَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا صَالِحًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَمِنْ خِزْيِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ", "67": "وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ", "68": "كَأَنْ لَمْ يَغْنَوْا فِيهَا أَلَا إِنَّ ثَمُودَ كَفَرُوا رَبَّهُمْ أَلَا بُعْدًا لِثَمُودَ", "69": "وَلَقَدْ جَاءَتْ رُسُلُنَا إِبْرَاهِيمَ بِالْبُشْرَى قَالُوا سَلَامًا قَالَ سَلَامٌ فَمَا لَبِثَ أَنْ جَاءَ بِعِجْلٍ حَنِيذٍ", "70": "فَلَمَّا رَأَى أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةً قَالُوا لَا تَخَفْ إِنَّا أُرْسِلْنَا إِلَى قَوْمِ لُوطٍ", "71": "وَامْرَأَتُهُ قَائِمَةٌ فَضَحِكَتْ فَبَشَّرْنَاهَا بِإِسْحَاقَ وَمِنْ وَرَاءِ إِسْحَاقَ يَعْقُوبَ", "72": "قَالَتْ يَاوَيْلَتَا أَأَلِدُ وَأَنَا عَجُوزٌ وَهَذَا بَعْلِي شَيْخًا إِنَّ هَذَا لَشَيْءٌ عَجِيبٌ", "73": "قَالُوا أَتَعْجَبِينَ مِنْ أَمْرِ اللَّهِ رَحْمَتُ اللَّهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَجِيدٌ", "74": "فَلَمَّا ذَهَبَ عَنْ إِبْرَاهِيمَ الرَّوْعُ وَجَاءَتْهُ الْبُشْرَى يُجَادِلُنَا فِي قَوْمِ لُوطٍ", "75": "إِنَّ إِبْرَاهِيمَ لَحَلِيمٌ أَوَّاهٌ مُنِيبٌ", "76": "يَاإِبْرَاهِيمُ أَعْرِضْ عَنْ هَذَا إِنَّهُ قَدْ جَاءَ أَمْرُ رَبِّكَ وَإِنَّهُمْ آتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍ", "77": "وَلَمَّا جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ هَذَا يَوْمٌ عَصِيبٌ", "78": "وَجَاءَهُ قَوْمُهُ يُهْرَعُونَ إِلَيْهِ وَمِنْ قَبْلُ كَانُوا يَعْمَلُونَ السَّيِّئَاتِ قَالَ يَاقَوْمِ هَؤُلَاءِ بَنَاتِي هُنَّ أَطْهَرُ لَكُمْ فَاتَّقُوا اللَّهَ وَلَا تُخْزُونِ فِي ضَيْفِي أَلَيْسَ مِنْكُمْ رَجُلٌ رَشِيدٌ", "79": "قَالُوا لَقَدْ عَلِمْتَ مَا لَنَا فِي بَنَاتِكَ مِنْ حَقٍّ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ", "80": "قَالَ لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلَى رُكْنٍ شَدِيدٍ", "81": "قَالُوا يَالُوطُ إِنَّا رُسُلُ رَبِّكَ لَنْ يَصِلُوا إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِنَ اللَّيْلِ وَلَا يَلْتَفِتْ مِنْكُمْ أَحَدٌ إِلَّا امْرَأَتَكَ إِنَّهُ مُصِيبُهَا مَا أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ الصُّبْحُ أَلَيْسَ الصُّبْحُ بِقَرِيبٍ", "82": "فَلَمَّا جَاءَ أَمْرُنَا جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِنْ سِجِّيلٍ مَنْضُودٍ", "83": "مُسَوَّمَةً عِنْدَ رَبِّكَ وَمَا هِيَ مِنَ الظَّالِمِينَ بِبَعِيدٍ", "84": "وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُمْ مِنْ إِلَهٍ غَيْرُهُ وَلَا تَنْقُصُوا الْمِكْيَالَ وَالْمِيزَانَ إِنِّي أَرَاكُمْ بِخَيْرٍ وَإِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُحِيطٍ", "85": "وَيَاقَوْمِ أَوْفُوا الْمِكْيَالَ وَالْمِيزَانَ بِالْقِسْطِ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ", "86": "بَقِيَّتُ اللَّهِ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ وَمَا أَنَا عَلَيْكُمْ بِحَفِيظٍ", "87": "قَالُوا يَاشُعَيْبُ أَصَلَاتُكَ تَأْمُرُكَ أَنْ نَتْرُكَ مَا يَعْبُدُ آبَاؤُنَا أَوْ أَنْ نَفْعَلَ فِي أَمْوَالِنَا مَا نَشَاءُ إِنَّكَ لَأَنْتَ الْحَلِيمُ الرَّشِيدُ", "88": "قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِنْ كُنْتُ عَلَى بَيِّنَةٍ مِنْ رَبِّي وَرَزَقَنِي مِنْهُ رِزْقًا حَسَنًا وَمَا أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَى مَا أَنْهَاكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا الْإِصْلَاحَ مَا اسْتَطَعْتُ وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ", "89": "وَيَاقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِي أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَالِحٍ وَمَا قَوْمُ لُوطٍ مِنْكُمْ بِبَعِيدٍ", "90": "وَاسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ", "91": "قَالُوا يَاشُعَيْبُ مَا نَفْقَهُ كَثِيرًا مِمَّا تَقُولُ وَإِنَّا لَنَرَاكَ فِينَا ضَعِيفًا وَلَوْلَا رَهْطُكَ لَرَجَمْنَاكَ وَمَا أَنْتَ عَلَيْنَا بِعَزِيزٍ", "92": "قَالَ يَاقَوْمِ أَرَهْطِي أَعَزُّ عَلَيْكُمْ مِنَ اللَّهِ وَاتَّخَذْتُمُوهُ وَرَاءَكُمْ ظِهْرِيًّا إِنَّ رَبِّي بِمَا تَعْمَلُونَ مُحِيطٌ", "93": "وَيَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ سَوْفَ تَعْلَمُونَ مَنْ يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَمَنْ هُوَ كَاذِبٌ وَارْتَقِبُوا إِنِّي مَعَكُمْ رَقِيبٌ", "94": "وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ", "95": "كَأَنْ لَمْ يَغْنَوْا فِيهَا أَلَا بُعْدًا لِمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ", "96": "وَلَقَدْ أَرْسَلْنَا مُوسَى بِآيَاتِنَا وَسُلْطَانٍ مُبِينٍ", "97": "إِلَى فِرْعَوْنَ وَمَلَئِهِ فَاتَّبَعُوا أَمْرَ فِرْعَوْنَ وَمَا أَمْرُ فِرْعَوْنَ بِرَشِيدٍ", "98": "يَقْدُمُ قَوْمَهُ يَوْمَ الْقِيَامَةِ فَأَوْرَدَهُمُ النَّارَ وَبِئْسَ الْوِرْدُ الْمَوْرُودُ", "99": "وَأُتْبِعُوا فِي هَذِهِ لَعْنَةً وَيَوْمَ الْقِيَامَةِ بِئْسَ الرِّفْدُ الْمَرْفُودُ", "100": "ذَلِكَ مِنْ أَنْبَاءِ الْقُرَى نَقُصُّهُ عَلَيْكَ مِنْهَا قَائِمٌ وَحَصِيدٌ", "101": "وَمَا ظَلَمْنَاهُمْ وَلَكِنْ ظَلَمُوا أَنْفُسَهُمْ فَمَا أَغْنَتْ عَنْهُمْ آلِهَتُهُمُ الَّتِي يَدْعُونَ مِنْ دُونِ اللَّهِ مِنْ شَيْءٍ لَمَّا جَاءَ أَمْرُ رَبِّكَ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍ", "102": "وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ", "103": "إِنَّ فِي ذَلِكَ لَآيَةً لِمَنْ خَافَ عَذَابَ الْآخِرَةِ ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ وَذَلِكَ يَوْمٌ مَشْهُودٌ", "104": "وَمَا نُؤَخِّرُهُ إِلَّا لِأَجَلٍ مَعْدُودٍ", "105": "يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِ فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ", "106": "فَأَمَّا الَّذِينَ شَقُوا فَفِي النَّارِ لَهُمْ فِيهَا زَفِيرٌ وَشَهِيقٌ", "107": "خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ إِنَّ رَبَّكَ فَعَّالٌ لِمَا يُرِيدُ", "108": "وَأَمَّا الَّذِينَ سُعِدُوا فَفِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ عَطَاءً غَيْرَ مَجْذُوذٍ", "109": "فَلَا تَكُ فِي مِرْيَةٍ مِمَّا يَعْبُدُ هَؤُلَاءِ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ آبَاؤُهُمْ مِنْ قَبْلُ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنْقُوصٍ", "110": "وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ فَاخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ لَقُضِيَ بَيْنَهُمْ وَإِنَّهُمْ لَفِي شَكٍّ مِنْهُ مُرِيبٍ", "111": "وَإِنَّ كُلًّا لَمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَالَهُمْ إِنَّهُ بِمَا يَعْمَلُونَ خَبِيرٌ", "112": "فَاسْتَقِمْ كَمَا أُمِرْتَ وَمَنْ تَابَ مَعَكَ وَلَا تَطْغَوْا إِنَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", "113": "وَلَا تَرْكَنُوا إِلَى الَّذِينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُ وَمَا لَكُمْ مِنْ دُونِ اللَّهِ مِنْ أَوْلِيَاءَ ثُمَّ لَا تُنْصَرُونَ", "114": "وَأَقِمِ الصَّلَاةَ طَرَفَيِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ", "115": "وَاصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ", "116": "فَلَوْلَا كَانَ مِنَ الْقُرُونِ مِنْ قَبْلِكُمْ أُولُو بَقِيَّةٍ يَنْهَوْنَ عَنِ الْفَسَادِ فِي الْأَرْضِ إِلَّا قَلِيلًا مِمَّنْ أَنْجَيْنَا مِنْهُمْ وَاتَّبَعَ الَّذِينَ ظَلَمُوا مَا أُتْرِفُوا فِيهِ وَكَانُوا مُجْرِمِينَ", "117": "وَمَا كَانَ رَبُّكَ لِيُهْلِكَ الْقُرَى بِظُلْمٍ وَأَهْلُهَا مُصْلِحُونَ", "118": "وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً وَلَا يَزَالُونَ مُخْتَلِفِينَ", "119": "إِلَّا مَنْ رَحِمَ رَبُّكَ وَلِذَلِكَ خَلَقَهُمْ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ", "120": "وَكُلًّا نَقُصُّ عَلَيْكَ مِنْ أَنْبَاءِ الرُّسُلِ مَا نُثَبِّتُ بِهِ فُؤَادَكَ وَجَاءَكَ فِي هَذِهِ الْحَقُّ وَمَوْعِظَةٌ وَذِكْرَى لِلْمُؤْمِنِينَ", "121": "وَقُلْ لِلَّذِينَ لَا يُؤْمِنُونَ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنَّا عَامِلُونَ", "122": "وَانْتَظِرُوا إِنَّا مُنْتَظِرُونَ", "123": "وَلِلَّهِ غَيْبُ السَّمَاوَاتِ وَالْأَرْضِ وَإِلَيْهِ يُرْجَعُ الْأَمْرُ كُلُّهُ فَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُونَ"}, "units": [{"aya": 1, "title": "في تأويله", "tabari": {"page": "12/308", "sarih": 1, "tarjih": "وأولى القولين فى ذلك بالصواب قول من قال: معناه: أحكم الله آياته من الدخل والخلل والباطل، ثم فصلها بالأمر والنهي؛ وذلك أن إحكام الشيء إصلاحه وإتقانه، وإحكام آيات القرآن إحكامها من خلل يكون فيها، أو باطل يقدر ذو زيغ أن يطعن فيها من قبله . وأما تفصيل آياته، فإنه تمييز بعضها من بعض بالبيان عما فيها من حلال وحرام وأمر ونهي.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "تأويله: أحكمت آياته بالأمر والنهي، ثم فصلت بالثواب والعقاب", "taqdim": 0, "n_athar": 3, "qailun": [["الحسن فى", "تابعي"], ["الحسن", "تابعي"]], "athar": [35022]}, {"n": 2, "t": "معنى ذلك: ﴿أحكمت آياته﴾ من الباطل، ﴿ثم فصلت﴾، فبين منها الحلال والحرام", "taqdim": 0, "n_athar": 6, "qailun": [["قتادة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [35021, 35023, 35024, 35029, 35030]}]}, "mawaqif": [{"taliq": 3169, "mi": 1, "aya": 1, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 310", "qawl": "الثاني", "nass": "وأولى القولين في ذلك بالصواب قول من قال: معناه: أحكم الله آياته من الدخل، والخلل والباطل، ثم فصلها بالأمر والنهي. وذلك أن إحكام الشيء: إصلاحه وإتقانه، وإحكام آيات القرآن: إحكامها من خلل يكون فيها، أو باطل يقدر ذو زيغ أن يطعن فيها من قبله. وأما تفصيل آياته فإنه تمييز بعضها من بعض بالبيان عما فيها من حلال، وحرام، وأمر، ونهي", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3169, "mi": 1, "aya": 1, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وذلك نحو الذي قلنا فيه من القول", "qawaid": [], "tabi": ""}, {"taliq": 3169, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 537 بتصرف", "qawl": "", "nass": "{وأحكمت} معناه: أتقنت وأجيدت شبه ما تحكم من الأمور المتقنة الكاملة، وبهذه الصفة كان القرآن في الأزل، ثم فصل بتقطيعه وتبيين أحكامه وأوامره على محمد صلى الله عليه وسلم في أزمنة مختلفة، ف {ثم} على بابها، وهذه طريقة الإحكام والتفصيل، إذ الإحكام صفة ذاتية، والتفصيل إنما هو بحسب من يفصل له، والكتاب بأجمعه محكم ومفصل، والإحكام الذي هو ضد النسخ والتفصيل الذي هو خلاف الإجمال إنما يقالان مع ما ذكرناه باشتراك", "qawaid": [], "tabi": ""}, {"taliq": 3169, "mi": 1, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وهذا من التخصيص الذي هو صحيح المعنى، ولكن لا يقتضيه اللفظ", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["011_001_1.png"], "pages": [286], "n": 4, "rajih": [3], "daif": [], "match": false}, "mawsua": {"taliq": 3169, "masala": "تفسير قوله: {كتاب فصلت آياته ثم أحكمت}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أحكمت آياته بالأمر والنهي، ثم فصلت بالثواب والعقاب", "ashab": "", "athar": []}, {"n": 2, "t": "أحكمت آياته من الباطل، ثم فصلت فبين منها الحلال والحرام", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 3, "title": "الآية", "mawsua": {"taliq": 3173, "masala": "الآية", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يعود الضمير فيه على {ذي} أي: ثواب فضله وجزاءه", "ashab": "", "athar": []}, {"n": 2, "t": "أن يعود الضمير فيه على الله عز وجل، أي: يؤتي الله فضله كل ذي فضل وعمل صالح من المؤمنين، ونحو هذا المعنى ما وعد به تعالى من تضعيف الحسنة بعشر أمثالها، ومن التضعيف غير المحصور لمن شاء، وهذا التأويل تأوله ابن مسعود، وقال: ويل لمن غلبت آحاده عشراته", "ashab": "", "athar": []}, {"n": 3, "t": "أن يكون قول ابن مسعود موافقا للمعنى الأول", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3173, "mi": 1, "aya": 3, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 538 - 539", "qawl": "", "nass": "وقوله تعالى: {ويؤت كل ذي فضل فضله} أي: كل ذي إحسان بقوله، أو بفعله، أو قوته، أو بماله، أو غير ذلك، مما يمكن أن يتقرب به. و {فضله} يحتمل أن يعود الضمير فيه على {ذي} أي: ثواب فضله وجزاءه. ويحتمل أن يعود الضمير فيه على الله عز وجل، أي: يؤتي الله فضله كل ذي فضل وعمل صالح من المؤمنين، ونحو هذا المعنى ما وعد به تعالى من تضعيف الحسنة بعشر أمثالها، ومن التضعيف غير المحصور لمن شاء، وهذا التأويل تأوله ابن مسعود، وقال: ويل لمن غلبت آحاده عشراته. ويحتمل أن يكون قول ابن مسعود موافقا للمعنى الأول", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "تأويل: ﴿ألا إنهم يثنون صدورهم ليستخفوا منه ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون إنه علي﴾", "tabari": {"page": "12/317", "sarih": 0, "tarjih": "والصواب من القراءة في ذلك عندنا ما عليه قرأة الأمصار، وهو: ﴿ألا إنهم يثنون صدورهم﴾. على مثال \"يفعلون\"، و\"الصدور\" نصب بمعنى: يحنون صدورهم ويكنونها .", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "بل كانوا يفعلون ذلك جهلا منهم بالله، وظنا أن الله يخفى عليه ما تضمره صدورهم إذا فعلوا ذلك", "taqdim": 0, "n_athar": 7, "qailun": [["مجاهد", "تابعي"], ["الحسن", "تابعي"], ["أبى رزين", "تابعي"]], "athar": [35070, 35071, 35073, 35074, 35075, 35086, 35091]}, {"n": 2, "t": "إنما كانوا يفعلون ذلك لئلا يسمعوا كتاب الله تعالى", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [35076, 35087]}, {"n": 3, "t": "إنما هذا إخبار من الله نبيه ﷺ عن المنافقين الذين كانوا يضمرون له العداوة والبغضاء، ويبدون له المحبة والمودة، أنهم معه وعلى دينه. يقول جل ثناؤه: لا إنهم يطوون صدورهم على الكفر ليستخفوا من الله. ثم أخبر جل ثناؤه أنه لا يخفى عليه سرائرهم وعلانيتهم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "كانوا يفعلون ذلك إذا ناجى بعضهم بعضا", "taqdim": 0, "n_athar": 4, "qailun": [["ابن زيد", "تابع التابعين"], ["ابن عباس", "صحابي"]], "athar": [35059, 35060, 35061, 35062, 35063, 35064, 35067, 35068, 35069, 35081, 35082, 35083, 35084]}]}, "mawaqif": [{"taliq": 3178, "mi": 1, "aya": 5, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 322", "qawl": "الثاني", "nass": "وإنما قلنا ذلك أولى التأويلات بالآية لأن قوله: {ليستخفوا منه} بمعنى: ليستخفوا من الله، وأن الهاء في قوله: {منه} عائدة على اسم الله، ولم يجر لمحمد ذكر قبل فيجعل من ذكره صلى الله عليه وسلم وهي في سياق الخبر عن الله. فإذا كان ذلك كذلك كانت بأن تكون من ذكر الله أولى. وإذا صح أن ذلك كذلك كان معلوما أنهم لم يحدثوا أنفسهم أنهم يستخفون من الله إلا بجهلهم به، فلما أخبرهم -جل ثناؤه- أنه لا يخفى عليه سر أمورهم وعلانيتها على أي حال كانوا", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3178, "mi": 1, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 540", "qawl": "الأول", "nass": "و {صدورهم} منصوبة على هذا ب {يثنون}", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["011_002_1.png"], "pages": [286], "n": 5, "rajih": [2], "daif": [], "match": false}, "mawsua": {"taliq": 3178, "masala": "تفسير قوله تعالى: {ألا إنهم يثنون صدورهم ليستخفوا منه}، وفي السبب الذي من أجله فعلوا ذلك", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ذلك كان من فعل بعض المنافقين، كان إذا مر برسول الله صلى الله عليه وسلم غطى وجهه، وثنى ظهره", "ashab": "", "athar": []}, {"n": 2, "t": "كانوا يفعلون ذلك جهلا منهم بالله، وظنا أن الله يخفى عليه ما تضمره صدورهم إذا فعلوا ذلك", "ashab": "", "athar": []}, {"n": 3, "t": "إنما كانوا يفعلون ذلك لئلا يسمعوا كلام الله تعالى", "ashab": "", "athar": []}, {"n": 4, "t": "إخبار من الله نبيه صلى الله عليه وسلم عن المنافقين الذين كانوا يضمرون له العداوة والبغضاء، ويبدون له المحبة والمودة، وأنهم معه وعلى دينه", "ashab": "", "athar": []}, {"n": 5, "t": "كانوا يفعلون ذلك إذا ناجى بعضهم بعضا", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "معنى الآية", "mawsua": {"taliq": 3175, "masala": "معنى الآية", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن ذلك كان من الكفار حين يلقون رسول الله تطامنوا، وثنوا صدورهم كالمستتر، وردوا إليه ظهورهم، وغشوا وجوههم بثيابهم تباعدا منه وكراهة للقائه، وهم يظنون أن ذلك يخفى عليه وعلى الله عز وجل", "ashab": "", "athar": []}, {"n": 2, "t": "أن ذلك استعارة للغل والحقد الذي كانوا ينطوون عليه ويتكتمون عليه ظنا منهم أنه يخفى على الله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3175, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 321", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3175, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "نسبها", "kind": "نقل", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3175, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والصواب من القراءة في ذلك عندنا ما عليه قراء الأمصار، وهو: {ألا إنهم يثنون صدورهم} على مثال: يفعلون", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 3175, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 539 - 540", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3175, "mi": 1, "aya": 5, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "7/ 414", "qawl": "", "nass": "وقرأ ابن عباس: (ألآ إنهم تثنوني صدورهم)، برفع الصدور على الفاعلية، وهو قريب المعنى", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 6, "title": "تأويل: ﴿ويعلم مستقرها﴾", "tabari": {"page": "12/326", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ويعلم مستقرها﴾: حيث تستقر فيه، وذلك مأواها الذي تأوي إليه ليلا أو نهارا، ﴿ومستودعها﴾: الموضع الذي يودعها، إما بموتها فيه، أو دفنها", "taqdim": 1, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"]], "athar": [35094, 35102, 35103, 35104, 35105, 35106]}, {"n": 2, "t": "﴿مستقرها﴾ في الرحم، ﴿ومستودعها﴾ في الصلب", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [35094, 35095, 35102, 35103, 35104, 35105, 35106, 35116]}, {"n": 3, "t": "المستقر في الرحم، والمستودع حيث تموت", "taqdim": 0, "n_athar": 1, "qailun": [["عبد الله", "صحابي"]], "athar": [35094, 35098, 35099, 35100, 35101, 35102, 35103, 35104, 35105, 35106]}, {"n": 4, "t": "﴿مستقرها﴾ أيام حياتها، ﴿ومستودعها﴾ حيث تموت فيه", "taqdim": 0, "n_athar": 1, "qailun": [["الربيع بن أنس", "تابعي"]], "athar": [35122]}]}, "mawaqif": [{"taliq": 3180, "mi": 1, "aya": 6, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "4/ 544", "qawl": "الأول", "nass": "وهما على هذا ظرفان", "qawaid": [], "tabi": ""}, {"taliq": 3180, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 327", "qawl": "الأول", "nass": "لأن الله -جل ثناؤه- أخبر أن ما رزقت الدواب من رزق فمنه، فأولى أن يتبع ذلك أن يعلم مثواها ومستقرها دون الخبر عن علمه بما تضمنته الأصلاب والأرحام", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3180, "mi": 1, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "وقيل: المستقر: ما حصل موجودا من الحيوان، والمستودع: ما يوجد بعد", "qawaid": [], "tabi": ""}], "mushid": {"i": 3, "imgs": ["011_003_1.png"], "pages": [287], "n": 4, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3180, "masala": "معنى المستقر والمستودع", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "المستقر حيث تأوي (المأوى)، والمستودع حيث تموت (القبر)", "ashab": "", "athar": []}, {"n": 2, "t": "المستقر في الرحم، والمستودع في الصلب", "ashab": "", "athar": []}, {"n": 3, "t": "المستقر في الرحم، والمستودع حيث تموت", "ashab": "", "athar": []}, {"n": 4, "t": "المستقر أيام الدنيا، والمستودع حيث تموت", "ashab": "", "athar": []}, {"n": 5, "t": "المستقر: الذي قد مات فاستقر به عمله", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 7, "title": "تأويل: ﴿وهو الذي خلق السماوات والأرض في ستة أيام وكان عرشه على الماء ليبلوكم أيكم أحسن عملا ولئن ق﴾", "tabari": {"page": "12/328", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: الله الذي إليه مرجعكم أيها الناس جميعا، ﴿وهو الذي خلق السماوات والأرض في ستة أيام﴾. يقول: أفيعجز من خلق ذلك من غير شيء أن يعيدكم أحياء بعد أن يميتكم؟", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إن الله تعالى ذكره خلق السماوات والأرض وما فيهن في الأيام الستة، فاجترئ في هذا الموضع بذكر خلق السماوات والأرض من ذكر خلق ما فيهن", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 14, "title": "تأويل: ﴿فهل أنتم مسلمون﴾", "tabari": {"page": "12/346", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿فهل أنتم مسلمون﴾. يقول: فهل أنتم مذعنون لله بالطاعة، ومخلصون له العبادة بعد ثبوت الحجة عليكم؟", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿فإلم يستجيبوا لكم﴾. والخطاب في أول الكلام قد جرى لواحد، وذلك قوله: ﴿قل فأتوا﴾. ولم يقل: فإن لم يستجيبوا لك. على نحو ما قد بينا قبل من خطاب رئيس القوم وصاحب أمرهم، أن العرب تخرج خطابه أحيانا مخرج خطاب الجميع، إذا كان خطابه [خطابا لأتباعه] وجنده، وأحيانا مخرج خطاب الواحد، إذا كان في نفسه واحدا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "المعني بهذه الآية", "mawsua": {"taliq": 3193, "masala": "المعني بهذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها في الكفار", "ashab": "", "athar": []}, {"n": 2, "t": "أنها في أهل الرياء من أهل القبلة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3193, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "4/ 550", "qawl": "الأول", "nass": "فأما من ذهب إلى أنها في الكفرة فمعنى قوله: {يريد}: يقصد ويعتمد، أي: هي وجهه ومقصده لا مقصد له غيرها. فالمعنى: من كان يريد بأعماله الدنيا فقط إذ لا يعتقد آخرة فإن الله يجازيه على حسن أعماله في الدنيا بالنعم والحواس وغير ذلك، فمنهم مضيق عليه، ومنهم موسع له، ثم حكم عليهم بأنهم لا يحصل لهم يوم القيامة إلا النار، ولا تكون لهم حال سواها", "qawaid": [], "tabi": ""}, {"taliq": 3193, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "4/ 551", "qawl": "الأول", "nass": "فاستقام هذا المعنى على لفظ الآية، وهو عندي أرجح التأويلات بحسب تقدم ذكر الكفار والمنافقين في القرآن فإنما قصد بهذه الآية أولئك", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3193, "mi": 1, "aya": 15, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الثاني", "nass": "والآية -بحمد الله- لا إشكال فيها، والله سبحانه ذكر جزاء من يريد بعمله الحياة الدنيا وزينتها وهو النار، وأخبر بحبوط عمله وبطلانه، فاذا أحبط ما ينجو به وبطل لم يبق معه ما ينجيه، فإن كان معه إيمان لم يرد به الدنيا وزينتها، بل أراد الله به والدار الآخرة لم يدخل هذا الإيمان في العمل الذى حبط وبطل وأنجاه إيمانه من الخلود في النار، وإن دخلها بحبوط عمله الذى به النجاة المطلقة، والإيمان إيمانان: إيمان يمنع من دخول النار، وهو الإيمان الباعث على أن تكون الأعمال لله يبتغى بها وجهه وثوابه، وإيمان يمنع الخلود في النار، وإن كان مع المرائي شيء منه وإلا كان من أهل الخلود، فالآية لها حكم نظائرها من آيات الوعيد والله الموفق، وذلك قوله: {من كان يريد حرث الآخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب} [الشورى: 20]، ومنه قوله: {من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا (18) ومن أراد الآخرة وسعى لها سعيها وهو مؤمن فأولئك كان سعيهم", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن عطية", "r"]], "2": [["ابن القيم", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["السياق"]}, "rulesD": {}}}, {"aya": 17, "title": "في تأويل ذلك ﴿أفمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى إماما ورحمة أولئك يؤمنون به﴾", "tabari": {"page": "12/353", "sarih": 1, "tarjih": "وأولى هذه الأقوال التي ذكرناها بالصواب في تأويل قوله: ﴿ويتلوه شاهد منه﴾. قول من قال: هو جبريل؛ لدلالة قوله: ﴿ومن قبله كتاب موسى إماما ورحمة﴾. على صحة ذلك. وذلك أن نبي الله ﷺ لم يتل قبل القرآن كتاب موسى، فيكون ذلك دليلا على صحة قول من قال: عني به لسان محمد ﷺ، أو محمد نفسه، أو علي. على قول من قال: عني به علي. ولا يعلم أن أحدا كان تلا ذلك قبل القرآن أو جاء به ممن ذكر أهل التأويل أنه عني بقوله: ﴿ويتلوه شاهد منه﴾ غير جبريل ﵇.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "يعني بقوله: ﴿أفمن كان على بينة من ربه﴾ محمدا ﷺ", "taqdim": 0, "n_athar": 10, "qailun": [["محمد ابن الحنفية", ""], ["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": [35275, 35276, 35279, 35280, 35298, 35299, 35300]}, {"n": 2, "t": "يعني بقوله: ﴿ويتلوه شاهد منه﴾: محمد ﷺ", "taqdim": 0, "n_athar": 6, "qailun": [["الحسين بن علي", ""], ["ابن زيد", "تابع التابعين"], ["مجاهد", "تابعي"]], "athar": [35257, 35266, 35269, 35270, 35271, 35272, 35287]}, {"n": 3, "t": "هو علي بن أبي طالب", "taqdim": 0, "n_athar": 1, "qailun": [["له رجل", ""]], "athar": []}, {"n": 4, "t": "هو جبريل", "taqdim": 0, "n_athar": 11, "qailun": [["ابن عباس", "صحابي"], ["إبراهيم", "تابعي"], ["مجاهد", "تابعي"], ["أبي العالية", "تابعي"], ["أيوب", ""]], "athar": [35258, 35259, 35260, 35263, 35265, 35266, 35269, 35270, 35271, 35272, 35288, 35289, 35296]}, {"n": 5, "t": "هو ملك يحفظه", "taqdim": 0, "n_athar": 5, "qailun": [["مجاهد", "تابعي"]], "athar": [35266, 35269, 35270, 35271, 35272]}]}, "mawaqif": [], "mushid": {"i": 4, "imgs": ["011_004_1.png"], "pages": [287], "n": 4, "rajih": [3], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "المشار إليه ببقوله: {أفمن}", "mawsua": {"taliq": 3195, "masala": "المشار إليه ببقوله: {أفمن}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "محمد صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 2, "t": "المؤمنون. واختلف في المراد بالشاهد على أقوال: الأول: أنه القرآن. الثاني: القرآن ونظمه وإعجازه. الثالث: محمد صلى الله عليه وسلم. الرابع: لسان محمد صلى الله عليه وسلم. الخامس: جبريل عليه السلام. السادس: ملك يحفظه. السابع: الإنجيل", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3195, "mi": 1, "aya": 17, "alam": "ابن عطية", "fil": "نقله", "kind": "نقل", "ref": "4/ 553", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "البينة", "mawsua": {"taliq": 3195, "masala": "البينة", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه القرآن؛ أي: على جلية بسبب القرآن", "ashab": "", "athar": []}, {"n": 2, "t": "أنه محمد صلى الله عليه وسلم، أي: على جلية بسبب محمد صلى الله عليه وسلم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "4/ 552", "qawl": "", "nass": "ولنرتب الآن اطراد كل قول وما يحتمل. فإذا قلنا: إن قوله: {أفمن} يراد به: المؤمنون، فإن جعلت بعد ذلك البينة محمدا صلى الله عليه وسلم صح أن يترتب الشاهد: الإنجيل، ويكون {يتلوه} بمعنى: يقرؤه؛ لأن الإنجيل يقرأ شأن محمد صلى الله عليه وسلم. وأن يترتب: جبريل عليه السلام، ويكون {يتلوه} بمعنى: يتبعه، أي: في تبليغ الشرع والمعونة فيه. وأن يترتب: الملك، ويكون الضمير في {منه} عائدا على البينة التي قدرناها: محمدا صلى الله عليه وسلم. وأن يترتب: القرآن، ويكون {يتلوه} بمعنى: يتبعه، ويعود الضمير في {منه} على الرب. وإن جعلنا البينة: القرآن على أن {أفمن} هم المؤمنون صح أن يترتب الشاهد: محمد صلى الله عليه وسلم، وصح أن يترتب: الإنجيل، وصح أن يترتب: جبريل والملك، ويكون {يتلوه} بمعنى: يقرؤه، وصح أن يترتب الشاهد: الإعجاز، ويكون {يتلوه} بمعنى: يتبعه، ويعود الضمير في {منه} على القرآن. وإذا جعلنا {أفمن} للنبي صلى الله عليه وسلم كانت البينة القرآن، وترتب الشاهد: لسان محمد صلى الله عليه وسلم، وترتب: الإنجيل، وترتب: جب", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "3/ 526", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن جرير", "fil": "حكى", "kind": "نقل", "ref": "12/ 353 - 361", "qawl": "", "nass": "وأولى هذه الأقوال التي ذكرناها بالصواب في تأويل قوله: {ويتلوه شاهد منه} قول من قال: هو جبريل. لدلالة قوله: {ومن قبله كتاب موسى إماما ورحمة} على صحة ذلك، وذلك أن نبي الله صلى الله عليه وسلم لم يتل قبل القرآن كتاب موسى، فيكون ذلك دليلا على صحة قول من قال: عنى به لسان محمد صلى الله عليه وسلم، أو: محمد نفسه، أو علي. ولا يعلم أن أحدا كان تلا ذلك قبل القرآن أو جاء به ممن ذكر أهل التأويل أنه عنى بقوله: {ويتلوه شاهد منه} غير جبريل عليه السلام", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "4/ 554 - 555", "qawl": "", "nass": "أن يكون {أفمن} للمؤمنين، أو لهم وللنبي صلى الله عليه وسلم معهم؛ إذ قد تقدم ذكر {الذين ليس لهم في الآخرة إلا النار}، فعقب ذكرهم بذكر غيرهم. والبينة: القرآن وما تضمن. والشاهد: محمد صلى الله عليه وسلم، أو جبريل إذا دخل النبي في قوله: {أفمن}، أو الإنجيل. والضمير في {يتلوه} للبينة، وفي {منه} للرب تعالى. والضمير في {قبله} للبينة", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن تيمية", "fil": "وجه", "kind": "توجيه", "ref": "3/ 516 - 523", "qawl": "", "nass": "من", "qawaid": ["القرآن والنظائر", "اللغة", "السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "3/ 512 - 528", "qawl": "", "nass": "", "qawaid": ["القرآن والنظائر", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 553", "qawl": "بأن", "nass": "يضعفه قوله: {أولئك}؛ فإنا إذا جعلنا قوله: {أفمن} للنبي صلى الله عليه وسلم وحده لم نجد في الآية مذكورين يشار إليهم بذلك، ونحتاج في الآية إلى تجوز وتشبيه بقوله تعالى: {يا أيها النبي إذا طلقتم النساء} [الطلاق: 1]، وهو شبه ليس بالقوي", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3195, "mi": 2, "aya": 17, "alam": "ابن تيمية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 513", "qawl": "بأن الشاهد", "nass": "لأن كون شاهد الإنسان منه لا يقتضي أن يكون الشاهد صادقا، فإنه مثل شهادة الإنسان لنفسه، بخلاف ما إذا كان الشاهد من الله؛ فإن الله يكون هو الشاهد، وهذا كما قيل في قوله: {قل كفى بالله شهيدا بيني وبينكم ومن عنده علم الكتاب} [الرعد: 43]: إنه علي. فهذا ضعيف؛ لأن شهادة قريب له قد اتبعه على دينه ولم يهتد إلا به لا تكون برهانا للصدق، ولا حجة على الكفر، بخلاف شهادة من عنده علم الكتاب الأول؛ فإن هؤلاء شهادتهم برهان ورحمة … ومن قال: إنه جبريل، فجبريل لم يقل شيئا من تلقاء نفسه، بل هو الذي بلغ القرآن عن الله، وجبريل يشهد أن القرآن منزل من الله، وأنه حق، كما قال: {لكن الله يشهد بما أنزل إليك أنزله بعلمه والملآئكة يشهدون وكفى بالله شهيدا} [النساء: 166]. والذي قال هو جبريل قال: {يتلوه} أي: يقرؤه، كما قال: {فإذا قرأناه فاتبع قرآنه} [القيامة: 18]، أي: إذا قرأه جبريل فاتبع ما قرأه، وقال: {علمه شديد القوى} [النجم: 5]. ومن قال: الشاهد: لسانه، وجعل الضمير المذكور عائدا على القرآن، ولم يذكر لأنه جعل البينة هي ال", "qawaid": ["الدلالة العقلية", "سبب النزول وأحواله", "القرآن والنظائر"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"], ["ابن تيمية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن عطية": ["السياق"], "ابن تيمية": ["القرآن والنظائر", "الدلالة العقلية"]}, "rulesD": {"ابن عطية": ["اللغة"], "ابن تيمية": ["الدلالة العقلية", "سبب النزول وأحواله", "القرآن والنظائر"]}}}, {"aya": 19, "title": "معنى {يصدون}", "mawsua": {"taliq": 3197, "masala": "معنى {يصدون}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه يحتمل أن يقدر متعديا، على معنى: يصدون الناس ويمنعونهم من سبيل الله", "ashab": "", "athar": []}, {"n": 2, "t": "أنه يحتمل أن يقدر غير متعد، على معنى: يصدون هم، أي: يعرضون", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3197, "mi": 1, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 557", "qawl": "", "nass": "أنه يحتمل أن يقدر متعديا، على معنى: يصدون الناس ويمنعونهم من سبيل الله. الثاني: أنه يحتمل أن يقدر غير متعد، على معنى: يصدون هم، أي: يعرضون", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 19, "title": "معنى {ويبغونها عوجا}", "mawsua": {"taliq": 3198, "masala": "معنى {ويبغونها عوجا}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن المعنى: يطلبون لها، كما تقول: بغيتك خيرا أو شرا، أي: طلبت لك، و {عوجا} على هذا مفعول", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون المعنى: ويبغون السبيل على عوج، أي: فهم لا يهتدون أبدا، ف {عوجا} على هذا مصدر في موضع الحال", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3198, "mi": 1, "aya": 19, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 557", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3198, "mi": 1, "aya": 19, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 52", "qawl": "", "nass": "أن تضمن {يبغونها} إما معنى: يعوجونها، فيكون {عوجا} منصوبا على المصدر، ودل فعل البغي على طلب ذلك وابتغائه. وإما معنى: يسومونها ويؤولونها", "qawaid": [], "tabi": "ابن عطية"}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 20, "title": "تأويل: ﴿ما كانوا يستطيعون السمع وما كانوا يبصرون﴾", "tabari": {"page": "12/370", "sarih": 0, "tarjih": "والصواب من القول في ذلك عندنا ما قاله ابن عباس وقتادة، من أن الله وصفهم، تعالى ذكره، بأنهم لا يستطيعون أن يسمعوا الحق سماع منتفع، ولا يبصرونه إبصار مهتد؛ لاشتغالهم بالكفر الذي كانوا عليه مقيمين، عن استعمال جوارحهم في طاعة الله، وقد كانت لهم أسماع وأبصار.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿ما كانوا يستطيعون السمع وما كانوا يبصرون﴾ فإنه اختلف في تأويله.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "ذلك وصف ، وصف الله به هؤلاء المشركين، أنه قد ختم على سمعهم وأبصارهم، وأنهم لا يسمعون الحق، ولا يبصرون حجج الله، سماع منتفع، ولا إبصار مهتد", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [35328, 35329, 35332, 35333, 35334]}, {"n": 3, "t": "إنما عنى بقوله: ﴿وما كان لهم من دون الله من أولياء﴾ آلهة الذين يصدون عن سبيل الله. وقالوا: معنى الكلام: أولئك وآلهتهم لم يكونوا معجزين في الأرض، ﴿يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون﴾، يعني الآلهة، أنها لم يكن لها سمع ولا بصر. وهذا قول روي عن ابن عباس من وجه كرهت ذكره لضعف سنده", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "معنى ذلك: يضاعف لهم العذاب بما كانوا يستطيعون السمع ولا يسمعونه، وبما كانوا يبصرون ولا يتأملون حجج الله بأعينهم فيعتبروا بها. قالوا: والباء كان ينبغي لها أن تدخل؛ لأنه قد قال: ﴿ولهم عذاب أليم بما كانوا يكذبون﴾ [البقرة: ١٠]. بكذبهم، في غير موضع من التنزيل، أدخلت فيه الباء، وسقوطها جائز في الكلام، كقولك في الكلام: [لأجزينك بما عملت، وما عملت] . وهذا قول قاله بعض أهل العربية", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3200, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 557 - 558", "qawl": "", "nass": "وقوله: {ما كانوا يستطيعون السمع وما كانوا يبصرون} يحتمل خمسة أوجه: أحدها: أن يصف هؤلاء الكفار بهذه الصفة، على معنى: أن الله ختم عليهم بذلك، فهم لا يسمعون سماعا ينتفعون به، ولا يبصرون كذلك. والثاني: أن يكون وصفهم بذلك من أجل بغضتهم في النبي صلى الله عليه وسلم، فهم لا يستطيعون أن يحملوا أنفسهم على السمع منه والنظر إليه. والثالث: أن يكون وصف بذلك الأصنام والآلهة التي نفى عنها أن تكون أولياء. والرابع: أن يكون التقدير: يضاعف لهم العذاب بما كانوا، بحذف الجار. والخامس: يضاعف لهم مدة استطاعتهم السمع والبصر، وقد أعلمت الشريعة أنهم لا يموتون فيها أبدا؛ فالعذاب إذن متماد أبدا", "qawaid": [], "tabi": ""}, {"taliq": 3200, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "", "qawl": "الرابع", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3200, "mi": 0, "aya": 20, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 372", "qawl": "الأول", "nass": "والصواب من القول في ذلك عندنا ما قاله ابن عباس وقتادة، من أن الله وصفهم -تعالى ذكره- بأنهم لا يستطيعون أن يسمعوا الحق سماع منتفع، ولا يبصرونه إبصار مهتد؛ لاشتغالهم بالكفر الذي كانوا عليه مقيمين عن استعمال جوارحهم في طاعة الله، وقد كانت لهم أسماع وأبصار", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3200, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "نسب", "kind": "نقل", "ref": "", "qawl": "الرابع", "nass": "وهذا قول فيه تحامل", "qawaid": [], "tabi": ""}, {"taliq": 3200, "mi": 0, "aya": 20, "alam": "ابن تيمية", "fil": "ذكر", "kind": "نقل", "ref": "3/ 538", "qawl": "الثاني", "nass": "", "qawaid": [], "tabi": ""}], "mushid": {"i": 5, "imgs": ["011_005_1.png", "011_005_2.png"], "pages": [287, 288], "n": 2, "rajih": [1], "daif": [2], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 20, "title": "قوله تعالى: {وما كان لهم من دون الله من أولياء}", "mawsua": {"taliq": 3199, "masala": "قوله تعالى: {وما كان لهم من دون الله من أولياء}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه نفى أن يكون لهم ولي أو ناصر كائنا من كان", "ashab": "", "athar": []}, {"n": 2, "t": "أن يقصد وصف الأصنام والآلهة بأنهم لم يكونوا أولياء حقيقة، وإن كانوا هم يعتقدون أنهم أولياء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3199, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 557", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 23, "title": "في معنى الإخبات", "tabari": {"page": "12/374", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك: وأنابوا إلى ربهم", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"]], "athar": [35342, 35343, 35345, 35346, 35348]}, {"n": 2, "t": "معنى ذلك: وخافوا", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [35342, 35343, 35348]}, {"n": 3, "t": "معناه: اطمأنوا", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [35344]}, {"n": 4, "t": "معنى ذلك: خشعوا", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [35345, 35346]}]}, "mawaqif": [{"taliq": 3202, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "12/ 375", "qawl": "", "nass": "وهذه الأقوال متقاربة المعاني، وإن اختلفت ألفاظها؛ لأن الإنابة إلى الله من خوف الله، ومن الخشوع والتواضع لله بالطاعة، والطمأنينة إليه من الخشوع له، غير أن نفس الإخبات عند العرب: الخشوع والتواضع", "qawaid": [], "tabi": ""}, {"taliq": 3202, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 560", "qawl": "", "nass": "وهذه الأقوال بعضها قريب من بعض، وأصل اللفظ من الخبت، وهو: البراح القفر المستوي من الأرض، فكأن المخبت في القفر قد انكشف واستسلم وبقي دون منعة، فشبه المتذلل الخاشع بذلك، وقيل: إنما اشتق منه لاستوائه وطمأنينته", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3202, "mi": 0, "aya": 23, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 53", "qawl": "", "nass": "وهذه الأقوال تدور على معنيين: التواضع، والسكون إلى الله عز وجل، ولذلك عدي بإلى تضمينا لمعنى الطمأنينة والإنابة والسكون إلى الله تعالى", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["011_006_1.png"], "pages": [288], "n": 4, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 40, "title": "في معنى ذلك ﴿وفار التنور﴾", "tabari": {"page": "12/401", "sarih": 1, "tarjih": "وأولى هذه الأقوال عندنا بتأويل قوله: ﴿التنور﴾. قول من قال: هو التنور الذي يخبز فيه؛ لأن ذلك هو المعروف من كلام العرب، وكلام الله لا يوجه إلا إلى الأغلب الأشهر من معانيه عند العرب، إلا أن تقوم حجة على شيء منه بخلاف ذلك، فيسلم لها. وذلك أنه جل ثناؤه إنما خاطبهم بما خاطبهم به، لإفهامهم معنى ما خاطبهم به. قلنا لنوح، حين جاء عذابنا قومه الذي وعدنا نوحا أن نعذبهم به، وفار التنور الذي جعلنا فورانه بالماء آية مجيء عذابنا، بيننا وبينه، لهلاك قومه: ﴿احمل فيها﴾. يعني في الفلك، ﴿من كل زوجين اثنين﴾. يقول: من كل ذكر وأنثى اثنين .", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: انبجس الماء من وجه الأرض، وفار التنور، وهو وجه الأرض", "taqdim": 0, "n_athar": 4, "qailun": [["ابن عباس", "صحابي"], ["عكرمة", "تابعي"]], "athar": [35474, 35475, 35476, 35477, 35478, 35479, 35519, 35520, 35537, 35538, 35539]}, {"n": 2, "t": "هو تنوير الصبح. من قولهم: نور الصبح تنويرا", "taqdim": 0, "n_athar": 5, "qailun": [["علي", "صحابي"]], "athar": [35469, 35471, 35472, 35473, 35536]}, {"n": 3, "t": "[معنى ذلك] : وفار أعلى الأرض وأشرف مكان فيها بالماء. وقال: التنور أشرف الأرض", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [35497, 35509, 35515, 35526]}, {"n": 4, "t": "هو التنور الذي يختبر فيه", "taqdim": 0, "n_athar": 10, "qailun": [["ابن عباس", "صحابي"], ["الحسن", "تابعي"], ["مجاهد", "تابعي"]], "athar": [35474, 35475, 35476, 35477, 35478, 35479, 35483, 35485, 35486, 35487, 35494, 35495, 35504, 35505, 35508, 35519, 35520, 35521, 35537, 35538, 35539, 35543, 35544]}, {"n": 5, "t": "الزوجان في كلام العرب: الاثنان. قال: ويقال: عليه زوجا نعال . إذا كانت عليه نعلان، ولا يقال: عليه زوج نعال. وكذلك: عنده زوجا حمام، وعليه زوجا قيود. وقال: ألا تسمع إلى قوله: ﴿وأنه خلق الزوجين الذكر والأنثى﴾ [النجم: ٤٥]. فإنما هما اثنان", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 6, "t": "﴿قلنا احمل فيها من كل زوجين اثنين﴾. قال: فجعل الزوجين، الضربين؛ الذكور والإناث. قال: وزعم يونس أن قول الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 7, "t": "الزوج اللون. قال: وكل ضرب يدعى لونا. واستشهد ببيت الأعشى في ذلك :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3216, "mi": 1, "aya": 40, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 406", "qawl": "الثالث", "nass": "وأولى هذه الأقوال عندنا بتأويل قوله: {التنور} قول من قال: هو التنور الذي يخبز فيه؛ لأن ذلك هو المعروف من كلام العرب، وكلام الله لا يوجه إلا إلى الأغلب الأشهر من معانيه عند العرب، إلا أن تقوم حجة على شيء منه بخلاف ذلك فيسلم لها، وذلك أنه -جل ثناؤه- إنما خاطبهم بما خاطبهم به لإفهامهم معنى ما خاطبهم به", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3216, "mi": 1, "aya": 40, "alam": "ابن كثير", "fil": "ووافقه", "kind": "موافقة", "ref": "7/ 436", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3216, "mi": 1, "aya": 40, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 575", "qawl": "الرابع", "nass": "… إلا أن التصريف يضعفه، وكان يلزم أن يكون: التنوير", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3216, "mi": 1, "aya": 40, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "", "qawl": "", "nass": "وقال النقاش: اسم المستوقد التنور بكل لغة، وذكر نحو ذلك ابن قتيبة في الأدب عن ابن عباس، وهذا بعيد", "qawaid": [], "tabi": ""}, {"taliq": 3216, "mi": 1, "aya": 40, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "7/ 436", "qawl": "", "nass": "وقال مجاهد والشعبي: كان هذا التنور بالكوفة. وعن ابن عباس: عين بالهند. وعن قتادة: عين بالجزيرة يقال لها: عين الوردة. وهذه أقوال غريبة", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["011_007_1.png"], "pages": [288], "n": 5, "rajih": [4], "daif": [], "match": false}, "mawsua": {"taliq": 3216, "masala": "التنور", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه وجه الأرض", "ashab": "", "athar": []}, {"n": 2, "t": "أنه أعلى الأرض وأشرفها", "ashab": "", "athar": []}, {"n": 3, "t": "أنه التنور الذي يخبز فيه", "ashab": "", "athar": []}, {"n": 4, "t": "أنه تنوير الصبح", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"], ["ابن كثير", "r"]], "4": [["ابن عطية", "d"]]}, "t": {"4": [["ابن جرير", "r"], ["ابن كثير", "r"]], "2": [["ابن عطية", "d"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {"ابن عطية": ["اللغة"]}}}, {"aya": 40, "title": "تأويل: ﴿وأهلك إلا من سبق عليه القول﴾", "tabari": {"page": "12/410", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وأهلك إلا من سبق عليه القول﴾. قال: العذاب، هي امرأته كانت من الغابرين في العذاب .", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل هو ابنه الذي غرق", "taqdim": 0, "n_athar": 1, "qailun": [["الضحاك", "تابعي"]], "athar": [35488, 35489, 35506, 35514, 35545]}]}, "mawaqif": [{"taliq": 3219, "mi": 0, "aya": 41, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "12/ 414", "qawl": "عنترة", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3219, "mi": 0, "aya": 41, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والقراءة التي نختارها في ذلك قراءة من قرأ: {بسم الله مجراها} بفتح الميم {ومرساها} بضم الميم، بمعنى: بسم الله حين تجري وحين ترسي. وإنما اخترت الفتح في ميم {مجراها} لقرب ذلك من قوله: {وهي تجري بهم في موج كالجبال}، ولم يقل: تجرى بهم. ومن قرأ: «بسم الله مجراها", "qawaid": ["السياق", "القراءة ورسم المصحف"], "tabi": ""}], "mushid": {"i": 8, "imgs": ["011_008_1.png"], "pages": [288], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["السياق", "القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 40, "title": "في عدد الذين كانوا آمنوا معه، فحملهم معه في الفلك", "tabari": {"page": "12/410", "sarih": 1, "tarjih": "والصواب من القول في ذلك، أن يقال كما قال الله: ﴿وما آمن معه إلا قليل﴾، يصفهم بأنهم كانوا قليلا، ولم يحد عددهم بمقدار ولا خبر عن رسول الله ﷺ صحيح. فلا ينبغي أن يتجاوز في ذلك حد الله، إذ لم يكن لمبلغ عدد ذلك حد من كتاب الله، أو أثر عن رسول الله ﷺ.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "كانوا ثمانية أنفس", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["الحكم", "تابعي"], ["ابن جريج", "تابع التابعين"]], "athar": [35497, 35509, 35515, 35518, 35523, 35525, 35526, 35533]}, {"n": 2, "t": "بل كانوا سبعة أنفس", "taqdim": 0, "n_athar": 1, "qailun": [["الأعمش", "تابع التابعين"]], "athar": [35530]}, {"n": 3, "t": "كانوا عشرة سوى نسائهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن إسحاق", "تابع التابعين"]], "athar": [35534]}, {"n": 4, "t": "بل كانوا ثمانين نفسا", "taqdim": 0, "n_athar": 3, "qailun": [["ابن جريج", "تابع التابعين"], ["الله", ""]], "athar": [35518, 35533]}]}, "mawaqif": [{"taliq": 3218, "mi": 1, "aya": 40, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 412", "qawl": "منها مستندا", "nass": "والصواب من القول في ذلك أن يقال كما قال الله: {وما آمن معه إلا قليل}، يصفهم بأنهم كانوا قليلا، ولم يحدد عددهم بمقدار، ولا خبر عن رسول الله صلى الله عليه وسلم صحيح، فلا ينبغي أن يتجاوز في ذلك حد الله، إذ لم يكن لمبلغ عدد ذلك حد من كتاب الله أو أثر عن رسول الله صلى الله عليه وسلم", "qawaid": ["عدم الدليل على غيره"], "tabi": ""}], "mushid": {"i": 9, "imgs": ["011_009_1.png", "011_009_2.png"], "pages": [288, 289], "n": 4, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3218, "masala": "تحديد عدد الذين كانوا مع نوح عليه السلام", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": []}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 42, "title": "قوله: {ولا تكن مع الكافرين}", "mawsua": {"taliq": 3223, "masala": "قوله: {ولا تكن مع الكافرين}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون نهيا محضا مع علمه أنه كافر", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون خفي عليه كفره فناداه ألا يبقى -وهو مؤمن- مع الكفرة فيهلك بهلاكهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3223, "mi": 1, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 582", "qawl": "", "nass": "وقوله: {ولا تكن مع الكافرين} يحتمل أن يكون نهيا محضا مع علمه أنه كافر، ويحتمل أن يكون خفي عليه كفره فناداه ألا يبقى -وهو مؤمن- مع الكفرة فيهلك بهلاكهم", "qawaid": [], "tabi": ""}, {"taliq": 3223, "mi": 1, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 587", "qawl": "", "nass": "هذه الآية تقتضي أن نوحا عليه السلام ظن أن ابنه مؤمن", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 43, "title": "في موضع \"من\" في هذا الموضع ﴿لا عاصم اليوم من أمر الله إلا من رحم﴾", "tabari": {"page": "12/417", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو في موضع نصب؛ لأن المعصوم بخلاف العاصم، والمرحوم معصوم. قال: كأن نصبه بمنزلة قوله: ﴿ما لهم به من علم إلا اتباع الظن﴾ [النساء: ١٥٧]. قال: ومن استجاز \"اتباع الظن\"، والرفع في قوله :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿لا عاصم اليوم من أمر الله إلا من رحم﴾، على: لكن من رحم. ويجوز أن يكون على: لا ذا عصمة. أي: معصوم. ويكون ﴿إلا من رحم﴾ رفعا، بدلا من العاصم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 44, "title": "قوله: {وقيل بعدا}", "mawsua": {"taliq": 3226, "masala": "قوله: {وقيل بعدا}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون من كلام الله تعالى معطوفا على {وقيل} الأولى من قوله: {وقيل يا أرض}", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون من كلام نوح عليه السلام والمؤمنين معه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3226, "mi": 1, "aya": 44, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 586", "qawl": "", "nass": "والأول أظهر وأبلغ", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 46, "title": "في معنى قوله: ﴿ليس من أهلك﴾", "tabari": {"page": "12/425", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب، قول من قال: تأويل ذلك: إنه ليس من أهلك الذين وعدتك أن أنجيهم، لأنه كان لدينك مخالفا وبي كافرا، وكان ابنه لأن الله تعالى ذكره قد أخبر نبيه محمدا ﷺ أنه ابنه، فقال: ﴿ونادى نوح ابنه﴾. وغير جائز أن يخبر أنه ابنه، فيكون بخلاف ما أخبر. وليس في قوله: ﴿إنه ليس من أهلك﴾ دلالة على أنه ليس بابنه، إذ كان قوله: ﴿إنه ليس من أهلك﴾ محتملا من المعنى ما ذكرنا، ومحتملا أنه ليس من أهل دينك، ثم يحذف الدين، فيقال: إنه ليس من أهلك، كما قيل: ﴿واسأل القرية التي كنا فيها﴾ [يوسف: ٨٢].", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: ليس من ولدك، هو من غيرك. وقالوا: كان ذلك من حنث", "taqdim": 0, "n_athar": 13, "qailun": [["الحسن", "تابعي"], ["أبي جعفر", "تابعي"], ["قتادة", "تابعي"], ["عند ذلك", ""], ["مجاهد", "تابعي"]], "athar": [35655, 35663, 35665, 35666, 35672, 35673, 35677, 35678, 35690, 35693, 35694, 35695, 35696, 35699, 35700]}, {"n": 2, "t": "معنى ذلك: ليس من أهلك الذين وعدتك أن أنجيهم", "taqdim": 0, "n_athar": 19, "qailun": [["ابن عباس", "صحابي"], ["الضحاك", "تابعي"], ["قتادة", "تابعي"], ["قول الله تعالى", ""], ["سعيد بن جبير", "تابعي"], ["قوله", ""], ["عكرمة", "تابعي"], ["مجاهد وعكرمة", "تابعي"], ["بزيع", ""], ["ميمون وثابت بن الحجاج", ""]], "athar": [35650, 35653, 35656, 35657, 35662, 35667, 35668, 35669, 35685, 35686, 35687, 35688, 35691, 35694, 35695, 35696]}]}, "mawaqif": [{"taliq": 3232, "mi": 1, "aya": 46, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 433", "qawl": "الثاني", "nass": "وأولى القولين في ذلك بالصواب قول من قال: تأويل ذلك: إنه ليس من أهلك الذين وعدتك أن أنجيهم؛ لأنه كان لدينك مخالفا، وبي كافرا. وكان ابنه؛ لأن الله -تعالى ذكره- قد أخبر نبيه محمدا صلى الله عليه وسلم أنه ابنه، فقال: {ونادى نوح ابنه}، وغير جائز أن يخبر أنه ابنه فيكون بخلاف ما أخبر. وليس في قوله: {إنه ليس من أهلك} دلالة على أنه ليس بابنه، إذ كان قوله: {ليس من أهلك} محتملا من المعنى ما ذكرنا، ومحتملا أنه ليس من أهل دينك، ثم يحذف «الدين", "qawaid": ["القرآن والنظائر", "القرآن والنظائر"], "tabi": ""}, {"taliq": 3232, "mi": 1, "aya": 46, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "3/ 541", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3232, "mi": 1, "aya": 46, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "7/ 444", "qawl": "", "nass": "وقال ابن عباس وغير واحد من السلف: ما زنت امرأة نبي قط. قال: وقوله: {إنه ليس من أهلك} أي: الذين وعدتك نجاتهم. وقول ابن عباس في هذا هو الحق الذي لا محيد عنه، فإن الله سبحانه أغير من أن يمكن امرأة نبي من الفاحشة، ولهذا غضب الله على الذين رموا أم المؤمنين عائشة بنت الصديق زوج النبي صلى الله عليه وسلم، وأنكر على المؤمنين الذين تكلموا بهذا وأشاعوه", "qawaid": ["أقوال السلف", "الدلالة العقلية", "السنة"], "tabi": "ابن تيمية"}, {"taliq": 3232, "mi": 1, "aya": 46, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "3/ 577 - 578 بتصرف", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3232, "mi": 1, "aya": 46, "alam": "ابن عطية", "fil": "ذكرها", "kind": "نقل", "ref": "", "qawl": "", "nass": ". وعلق على هذا القول، فقال: «ويقوي هذا التأويل أن في مصحف ابن مسعود: (إنه عمل غير صالح أن تسألني ما ليس لك به علم", "qawaid": ["القرآن والنظائر"], "tabi": ""}], "mushid": {"i": 10, "imgs": ["011_010_1.png"], "pages": [289], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 3232, "masala": "تفسير قوله: {إنه ليس من أهلك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه لم يكن من ولده، بل من ولد غيره", "ashab": "", "athar": []}, {"n": 2, "t": "أن معنى الآية: ليس من أهلك الذين وعدتك أن أنجيهم", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن تيمية", "r"], ["ابن كثير", "r"]]}, "t": {"2": [["ابن جرير", "r"], ["ابن تيمية", "r"], ["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["القرآن والنظائر"], "ابن كثير": ["أقوال السلف", "الدلالة العقلية", "السنة"]}, "rulesD": {}}}, {"aya": 46, "title": "تأويل: ﴿إنه عمل غير صالح﴾", "tabari": {"page": "12/434", "sarih": 0, "tarjih": "والصواب من القراءة في ذلك عندنا ما عليه قرأة الأمصار؛ وذلك رفع ﴿عمل﴾ بالتنوين، ورفع ﴿غير﴾، بمعنى: إن سؤالك إياي ما تسألنيه في ابنك - المخالف دينك، الموالي أهل الشرك بي؛ من النجاة من الهلاك، وقد مضت إجابتي إياك في دعائك: ﴿لا تذر على الأرض من الكافرين ديارا﴾ [نوح: ٢٦]، ما قد مضى، من غير استثناء أحد منهم - عمل غير صالح؛ لأنه مسألة منك إلي أن لا أفعل ما قد تقدم مني القول بأني أفعله في إجابتي مسألتك إياي فعله. فذلك هو العمل غير الصالح.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "وأما قوله: ﴿إنه عمل غير صالح﴾. فإن القرأة اختلفت في قراءته؛ فقرأته عامة قرأة الأمصار: ﴿إنه عمل غير صالح﴾ بتنوين ﴿عمل﴾، ورفع ﴿غير﴾ ؛ واختلف الذين قرءوا ذلك كذلك في تأويله؛ فقال بعضهم: معناه: إن مسألتك إياي هذه عمل غير صالح.", "taqdim": 1, "n_athar": 4, "qailun": [["إبراهيم", "تابعي"], ["قتادة", "تابعي"], ["ابن عباس", "صحابي"], ["مجاهد", "تابعي"]], "athar": [35650, 35653, 35656, 35657, 35663, 35665, 35666, 35685, 35686, 35687, 35689, 35690, 35694, 35695, 35696, 35699]}, {"n": 2, "t": "بل معناه: إن الذي ذكرت أنه ابنك، فسألتني أن أنجيه، عمل غير صالح؛ أي: إنه لغير رشدة. وقالوا: الهاء في قوله: ﴿إنه﴾ عائدة على الابن", "taqdim": 0, "n_athar": 2, "qailun": [["الحسن", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [35650, 35653, 35656, 35657, 35672, 35673, 35685, 35686, 35687, 35693, 35700]}]}, "mawaqif": [{"taliq": 3229, "mi": 0, "aya": 46, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 435 - 436", "qawl": "", "nass": "ولا نعلم هذه القراءة قرأ بها أحد من قراء الأمصار إلا بعض المتأخرين، واعتل في ذلك بخبر روي عن رسول الله صلى الله عليه وسلم أنه قرأ ذلك كذلك غير صحيح السند، وذلك حديث روي عن شهر بن حوشب؛ فمرة يقول: عن أم سلمة، ومرة يقول: عن أسماء بنت يزيد، ولا نعلم لبنت يزيد، ولا نعلم لشهر سماعا يصح عن أم سلمة", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 3229, "mi": 0, "aya": 46, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والصواب من القراءة في ذلك عندنا ما عليه قراء الأمصار، وذلك رفع {عمل} بالتنوين، ورفع {غير}، يعني: إن سؤالك إياي ما تسألنيه في ابنك المخالف دينك الموالي أهل الشرك بي من النجاة من الهلاك، وقد مضت إجابتي إياك في دعائك: {لا تذر على الأرض من الكافرين ديارا} [نوح: 26] ما قد مضى من غير استثناء أحد منهم؛ عمل غير صالح؛ لأنه مسألة منك إلي أن لا أفعل ما قد تقدم مني القول بأني أفعله في إجابتي مسألتك إياي فعله، فذلك هو العمل غير الصالح", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}], "mushid": {"i": 11, "imgs": ["011_011_1.png"], "pages": [289], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 57, "title": "الآية", "mawsua": {"taliq": 3237, "masala": "الآية", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "ولا تضرونه بذهابكم وهلاككم شيئا، أي: لا ينتقص ملكه، ولا يختل أمره، وعلى هذا المعنى قرأ ابن مسعود: (ولا تنقصونه شيئا", "ashab": "", "athar": []}, {"n": 2, "t": "{ولا تضرونه} أي ولا تقدرون إذا أهلككم على إضراره بشيء، ولا على الانتصار منه، ولا تقابلون فعله بكم بشيء يضره\"", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3237, "mi": 1, "aya": 57, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 597", "qawl": "", "nass": "وقوله: {ولا تضرونه شيئا} يحتمل من المعنى وجهين: أحدهما: ولا تضرونه بذهابكم وهلاككم شيئا، أي: لا ينتقص ملكه، ولا يختل أمره، وعلى هذا المعنى قرأ ابن مسعود: (ولا تنقصونه شيئا", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 58, "title": "قوله: {ونجيناهم من عذاب غليظ}", "mawsua": {"taliq": 3238, "masala": "قوله: {ونجيناهم من عذاب غليظ}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: عذاب الآخرة", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: وكانت النجاة المتقدمة من عذاب غليظ، يريد: الريح؛ فيكون المقصود على هذا تعديد النعمة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3238, "mi": 1, "aya": 58, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 597", "qawl": "", "nass": "وقوله: {ونجيناهم من عذاب غليظ} يحتمل أن يريد: عذاب الآخرة. ويحتمل أن يريد: وكانت النجاة المتقدمة من عذاب غليظ، يريد: الريح؛ فيكون المقصود على هذا تعديد النعمة", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 66, "title": "قوله: {برحمة منا}", "mawsua": {"taliq": 3245, "masala": "قوله: {برحمة منا}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يقصد: أن التنجية إنما كانت بمجرد الرحمة", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون وصف حال فقط، أخبر أنه رحمهم في حال التنجية. ثم قال: «وقوله: {منا} الظاهر أنه متعلق برحمة، ويحتمل أن يتعلق بقوله: {نجينا}", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3245, "mi": 0, "aya": 66, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 603", "qawl": "", "nass": "وقوله: {منا} الظاهر أنه متعلق برحمة، ويحتمل أن يتعلق بقوله: {نجينا}", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 69, "title": "في تلك البشارة التي أتوه بها", "tabari": {"page": "12/466", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندي أنهما قراءتان متقاربتا المعنى؛ لأن السلم قد يكون بمعنى السلام على ما وصفت، والسلام بمعنى السلم؛ لأن التسليم لا يكاد يكون إلا بين أهل السلم دون الأعداء، فإذا ذكر تسليم من قوم على قوم، ورد الآخرين عليهم، دل ذلك على مسالمة بعضهم بعضا. وهما مع ذلك قراءتان قد قرأ بكل واحدة أهل قدوة في القراءة، فبأيتهما قرأ القارئ فمصيب الصواب.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هي البشارة بإسحاق", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "هي البشارة بهلاك قوم لوط", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3247, "mi": 0, "aya": 69, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 467 - 470", "qawl": "", "nass": "كل شيء شوي في الأرض إذا خددت له فيها فدفنته وغممته فهو الحنيذ والمحنوذ", "qawaid": [], "tabi": ""}], "mushid": {"i": 12, "imgs": ["011_012_1.png"], "pages": [289], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 69, "title": "تأويل: ﴿فما لبث أن جاء بعجل حنيذ﴾", "tabari": {"page": "12/468", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿فما لبث أن جاء بعجل حنيذ﴾. [يقول: فما بطأ إبراهيم إذ تضيفته رسل الله أن جاءهم بعجل حنيذ] . وأصله محنوذ، صرف من مفعول إلى فعيل.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "كل [شيء شوى] في الأرض، إذا خددت له فيها فدفنته وغممته فهو الحنيذ والمحنوذ. قال: والخيل تحنذ إذا ألقيت عليها الجلال بعضها على بعض لتعرق. قال: ويقال: إذا سقيته فأحنذ. يعني: أخفس، يريد: أقل الماء وأكثر النبيذ", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 71, "title": "في معنى قوله: ﴿فضحكت﴾. وفي السبب الذي من أجله ضحكت", "tabari": {"page": "12/473", "sarih": 1, "tarjih": "وأولى الأقوال التي ذكرت في ذلك بالصواب قول من قال: معنى قوله: ﴿فضحكت﴾: فعجبت من غفلة قوم لوط عما أظلهم من عذاب الله، وغفلتهم عنه.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "ضحكت الضحك المعروف؛ تعجبا من أنها وزوجها إبراهيم يخدمان ضيفانهم بأنفسهما، تكرمة لهم، وهم عن طعامهم ممسكون لا يأكلون", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [35899, 35910]}, {"n": 2, "t": "بل ضحكت من أن قوم لوط في غفلة وقد جاءت رسل الله بإهلاكهم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [35898, 35909]}, {"n": 3, "t": "بل ضحكت ظنا منها بهم أنهم يريدون عمل قوم لوط", "taqdim": 0, "n_athar": 1, "qailun": [["محمد بن قيس", ""]], "athar": [35900]}, {"n": 4, "t": "بل ضحكت لما رأت بزوجها إبراهيم من الروع", "taqdim": 0, "n_athar": 1, "qailun": [["الكلبي", "تابع التابعين"]], "athar": [35901, 35911]}, {"n": 5, "t": "بل ضحكت حين بشرت بإسحاق؛ تعجبا من أن يكون لها ولد على كبر سنها وسن زوجها", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 6, "t": "بل معنى قوله: ﴿فضحكت﴾. في هذا الموضع: حاضت", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [35889, 35896]}, {"n": 7, "t": "بل ضحكت سرورا بالأمن منهم، لما قالوا لإبراهيم: ﴿لا تخف﴾. وذلك أنه قد كان خافهم، وخافتهم هي أيضا، كما خافهم إبراهيم، فلما أمنت ضحكت، فأتبعوها البشارة بإسحاق", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3250, "mi": 1, "aya": 71, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 609", "qawl": "الثاني", "nass": "وهذا قول ضعيف قليل التمكن", "qawaid": [], "tabi": ""}, {"taliq": 3250, "mi": 1, "aya": 71, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 478", "qawl": "الثاني", "nass": "لأنه ذكر عقيب قولهم لإبراهيم: {لا تخف إنا أرسلنا إلى قوم لوط}، فإذا كان ذلك كذلك، وكان لا وجه للضحك والتعجب من قولهم لإبراهيم عليه السلام: {لا تخف}؛ كان الضحك والتعجب إنما هو من أمر قوم لوط عليه السلام", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3250, "mi": 1, "aya": 71, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 610", "qawl": "الثالث", "nass": "وهذا قول خطأ، لا ينبغي أن يلتفت إليه، وقد حكاه الطبري، وإنما ذكرته لمعنى التنبيه على فساده", "qawaid": [], "tabi": ""}, {"taliq": 3250, "mi": 1, "aya": 71, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "7/ 452", "qawl": "الثالث", "nass": "ضعيفان جدا، وإن كان ابن جرير قد رواهما بسنده إليهما، فلا يلتفت إلى ذلك", "qawaid": ["السياق"], "tabi": ""}], "mushid": {"i": 13, "imgs": ["011_013_1.png", "011_013_2.png", "011_013_3.png"], "pages": [289, 290], "n": 9, "rajih": [4], "daif": [], "match": false}, "mawsua": {"taliq": 3250, "masala": "معنى الضحك", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الضحك المعروف", "ashab": "", "athar": []}, {"n": 2, "t": "الحيض", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن عطية", "d"], ["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق", "الدلالة العقلية"]}, "rulesD": {"ابن كثير": ["السياق"]}}}, {"aya": 71, "title": "معنى {قائمة}", "mawsua": {"taliq": 3249, "masala": "معنى {قائمة}", "sigha": "زاد قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن: معناه: قائمة خلف ستر تسمع محاورة إبراهيم مع أضيافه", "ashab": "", "athar": []}, {"n": 2, "t": "أن معناه: قائمة في صلاة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3249, "mi": 1, "aya": 71, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 609", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 73, "title": "قوله: {من أمر الله}", "mawsua": {"taliq": 3252, "masala": "قوله: {من أمر الله}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد واحد الأمور، أي: من الولادة في هذه السن", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: مصدر أمر، أي: مما أمر الله في هذه النازلة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3252, "mi": 0, "aya": 73, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 613", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 74, "title": "{البشرى}", "mawsua": {"taliq": 3253, "masala": "{البشرى}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "البشرى بالولد", "ashab": "", "athar": []}, {"n": 2, "t": "البشرى بأن المراد غيره", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3253, "mi": 1, "aya": 74, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 615", "qawl": "", "nass": "والأول أبين", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 80, "title": "تأويل: ﴿قال لو أن لي بكم قوة أو آوي إلى ركن شديد﴾", "tabari": {"page": "12/513", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول ﷿: قال لوط لقومه حين أبوا إلا المضي لما قد جاءوا له من طلب الفاحشة، ويئس من أن يستجيبوا له إلى شيء مما عرض عليهم: ﴿لو أن لي بكم قوة﴾ بأنصار تنصرني عليكم، وأعوان تعينني، ﴿أو آوي إلى ركن شديد﴾. يقول: أو أنضم إلى عشيرة مانعة تمنعني منكم، لحلت بينكم وبين ما جئتم تريدونه مني في أضيافي. وحذف جواب لو لدلالة الكلام عليه، وأن معناه مفهوم.", "taqdim": 1, "n_athar": 18, "qailun": [["السدي", "تابعي"], ["قتادة", "تابعي"], ["الحسن", "تابعي"], ["ابن جريج", "تابع التابعين"], ["ابن إسحاق", "تابع التابعين"], ["أبي هريرة", "صحابي"], ["ابن شهاب الزهري", "تابع التابعين"]], "athar": [36054, 36055, 36060, 36061, 36062, 36064, 36065, 36067, 36068, 36070, 36072]}, {"n": 2, "t": "إن لوطا لما قال [هذا القول] ، وجدت الرسل عليه لذلك", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 14, "imgs": ["011_014_1.png"], "pages": [290], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 81, "title": "قراءة قوله تعالى: {إلا امرأتك}", "mawsua": {"taliq": 3263, "masala": "قراءة قوله تعالى: {إلا امرأتك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{إلا امرأتك} بالنصب", "ashab": "", "athar": []}, {"n": 2, "t": "إلا امرأتك» بالرفع", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3263, "mi": 0, "aya": 81, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "12/ 525", "qawl": "", "nass": "وهذا يدل على صحة القراءة في المرأة بالنصب", "qawaid": [], "tabi": ""}, {"taliq": 3263, "mi": 1, "aya": 81, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "12/ 514 - 515", "qawl": "", "nass": "فأسر بأهلك إلا امرأتك، وعلى أن لوطا أمر أن يسري بأهله سوى زوجته، فإنه نهي أن يسري بها، وأمر بتخليفها مع قومها", "qawaid": [], "tabi": ""}, {"taliq": 3263, "mi": 1, "aya": 81, "alam": "ابن القيم", "fil": "وجه", "kind": "توجيه", "ref": "2/ 60", "qawl": "", "nass": "الاستثناء منقطع في قراءة الرفع، ويكون «امرأتك", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 82, "title": "تأويل: ﴿فلما جاء أمرنا جعلنا عاليها سافلها وأمطرنا عليها حجارة من سجيل منضود مسومة عند ربك وما هي ﴾", "tabari": {"page": "12/528", "sarih": 0, "tarjih": "والصواب من القول فى ذلك عندنا ما قاله المفسرون، وهو أنها من طين، وبذلك وصفها الله ﷿ في كتابه في موضع آخر، وذلك قوله: ﴿لنرسل عليهم حجارة من طين (٣٣) مسومة عند ربك للمسرفين﴾ [الذاريات: ٣٣، ٣٤].", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: فلما جاء أمرنا بالعذاب، وقضاؤنا فيهم بالهلاك، ﴿جعلنا عاليها﴾. [يعنى: عالى] القرية سافلها، ﴿وأمطرنا عليها﴾. يقول: وأرسلنا عليها ﴿حجارة من سجيل منضود﴾.", "taqdim": 1, "n_athar": 10, "qailun": [["مجاهد", "تابعي"], ["سعيد بن جبير", "تابعي"], ["قتادة", "تابعي"], ["قتادة وعكرمة", "تابعي"], ["السدي", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [36108, 36109, 36111, 36115, 36116, 36117, 36118, 36119, 36121, 36122, 36123, 36125, 36126, 36127, 36130, 36131, 36134, 36142, 36143, 36145, 36146]}, {"n": 2, "t": "هو \"فعيل\"، من قول القائل: أسجلته: أرسلته، فكأنه من ذلك. أي: مرسلة عليهم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "هو من سجلت له سجلا. من العطاء، فكأنه قيل: منحوا ذلك البلاء فأعطوه. وقالوا: أسجله: أهمله", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "بل هو من السجل؛ لأنه كان فيها علم كالكتاب", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 5, "t": "بل هو طين يطبح كما يطبخ الآجر، وينشد بيت الفضل بن عباس :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3265, "mi": 1, "aya": 82, "alam": "ابن جرير", "fil": "نقل", "kind": "نقل", "ref": "", "qawl": "القائل", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3265, "mi": 1, "aya": 82, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 528", "qawl": "الأول", "nass": "والصواب من القول في ذلك عندنا ما قاله المفسرون، وهو أنها من طين، وبذلك وصفها الله عز وجل في كتابه في موضع آخر، وذلك قوله: {لنرسل عليهم حجارة من طين * مسومة عند ربك للمسرفين} [الذاريات: 33 - 34]", "qawaid": [], "tabi": ""}, {"taliq": 3265, "mi": 1, "aya": 82, "alam": "ابن عطية", "fil": "رجحه", "kind": "ترجيح", "ref": "4/ 627", "qawl": "الحسن", "nass": "وهذا قول يشبه، وهو الصواب الذي عليه الجمهور", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 3265, "mi": 1, "aya": 82, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 626", "qawl": "الثاني", "nass": "وهذا ضعيف، ويرده وصفه ب {منضود}", "qawaid": ["القرآن والنظائر"], "tabi": ""}], "mawsua": {"taliq": 3265, "masala": "معنى: {سجيل}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها لفظة غير عربية استعملها العرب، ومعناها: طين", "ashab": "", "athar": []}, {"n": 2, "t": "أنها اسم السماء الدنيا", "ashab": "", "athar": []}, {"n": 3, "t": "أنها من الحجارة الصلب الشديد", "ashab": "", "athar": []}, {"n": 4, "t": "أنها من قول القائل: أسجلته: أرسلته، أي: مرسلة عليهم", "ashab": "", "athar": []}, {"n": 5, "t": "أنها من سجلت له سجلا من العطاء، أي: منحوا ذلك البلاء فأعطوه", "ashab": "", "athar": []}, {"n": 6, "t": "أنها من السجل؛ لأنه كان فيها علم كالكتاب", "ashab": "", "athar": []}, {"n": 7, "t": "طين يطبخ كما يطبخ الآجر", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]], "2": [["ابن عطية", "d"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {"ابن عطية": ["القرآن والنظائر"]}}}, {"aya": 82, "title": "تأويل: ﴿منضود﴾", "tabari": {"page": "12/529", "sarih": 0, "tarjih": "والصواب من القول فى ذلك ما قاله الربيع بن أنس، وذلك أن قوله: ﴿منضود﴾. من نعت: ﴿سجيل﴾. لا من نعت الحجارة، وإنما أمطر القوم حجارة من طين، صفة ذلك الطين، أنه نضد بعضه إلى بعض، فصير حجارة، ولم يمطروا الطين، فيكون موصوفا بأنه تتابع على القوم بمجيئه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "وأما قوله: ﴿منضود﴾. فإن قتادة وعكرمة يقولان فيه ما حدثنا محمد بن عبد الأعلى، قال: ثنا محمد بن ثور، عن معمر، عن قتادة وعكرمة: ﴿منضود﴾. يقول: مصفوفة .", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "منضود: يتبع بعضه بعضا عليهم. قال: فذلك نضده", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3266, "mi": 1, "aya": 82, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 530", "qawl": "الثالث", "nass": "قوله: {منضود} من نعت {سجيل}، لا من نعت الحجارة، وإنما أمطر القوم حجارة من طين، صفة ذلك الطين أنه نضد بعضه إلى بعض، فصير حجارة، ولم يمطروا الطين، فيكون موصوفا بأنه تتابع على القوم بمجيئه. وإنما كان جائزا أن يكون على ما تأوله هذا المتأول لو كان التنزيل بالنصب منضودة، فيكون من نعت الحجارة حينئذ", "qawaid": ["اللغة"], "tabi": ""}], "mushid": {"i": 16, "imgs": ["011_016_1.png"], "pages": [290], "n": 3, "rajih": [2], "daif": [], "match": false}, "mawsua": {"taliq": 3266, "masala": "معنى: {منضود}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "يتبع بعضه بعضا", "ashab": "", "athar": []}, {"n": 2, "t": "مصفوف", "ashab": "", "athar": []}, {"n": 3, "t": "نضد بعضه على بعض", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 83, "title": "المراد ب {الظالمين}", "mawsua": {"taliq": 3267, "masala": "المراد ب {الظالمين}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المراد به: كفار قريش", "ashab": "", "athar": []}, {"n": 2, "t": "أنه عام في كل ظالم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3267, "mi": 1, "aya": 83, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "4/ 628", "qawl": "الثاني", "nass": "وهذا هو الأصح؛ لأنه روي عن النبي صلى الله عليه وسلم أنه قال: «سيكون في أمتي خسف، ومسخ، وقذف بالحجارة", "qawaid": ["السنة"], "tabi": ""}], "tags": {"m": {"2": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["السنة"]}, "rulesD": {}}}, {"aya": 84, "title": "تأويل: ﴿إني أراكم بخير﴾", "tabari": {"page": "12/539", "sarih": 0, "tarjih": "وأولى الأقوال فى ذلك بالصواب: ما أخبر الله عن شعيب أنه قال لقومه، وذلك قوله لهم: ﴿إني أراكم بخير﴾. يعنى: بخير الدنيا، وقد يدخل في خير الدنيا المال وزينة الحياة الدنيا، ورخص السعر، ولا دلالة على أنه عنى بقيله ذلك بعض خيرات الدنيا دون بعض، فذلك على كل معانى خيرات الدنيا التي ذكر أهل العلم أنهم كانوا أوتوها، وإنما قال ذلك شعيب؛ لأن قومه كانوا في سعة من عيشهم، ورخص من أسعارهم، كثيرة أموالهم، فقال لهم: لا تنقصوا الناس حقوقهم فى مكاييلكم وموازينكم، فقد وسع الله عليكم ورزقكم، ﴿وإني أخاف عليكم﴾ بمخالفتكم أمر الله وبخسكم الناس أموالهم في مكاييلكم وموازينكم، ﴿عذاب يوم محيط﴾. يقول: أن ينزل بكم عذاب يوم محيط بكم عذابه، فجعل \"المحيط\" نعتا لليوم، وهو [من نعت العذاب] ؛ إذ كان مفهوما معناه، وكان العذاب في اليوم، فصار كقولهم: بعض جبتك متخرقة .", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿إني أراكم بخير﴾. قال: رخص السعر.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "عنى بذلك: إني أرى لكم مالا وزينة من زين الدنيا", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [36191, 36192, 36194]}]}, "mawaqif": [{"taliq": 3270, "mi": 1, "aya": 84, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 539 - 540", "qawl": "العموم", "nass": "وأولى الأقوال في ذلك بالصواب: ما أخبر الله عن شعيب عليه السلام أنه قال لقومه، وذلك قوله: {إني أراكم بخير} يعني: بخير الدنيا. وقد يدخل في خير الدنيا: المال، وزينة الحياة الدنيا، ورخص السعر، ولا دلالة على أنه عنى بقيله ذلك بعض خيرات الدنيا دون بعض، فذلك على كل معاني خيرات الدنيا التي ذكر أهل العلم أنهم كانوا أوتوها", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 3270, "mi": 1, "aya": 84, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "4/ 629", "qawl": "الأول", "nass": "وينظر هذا التأويل إلى قول النبي صلى الله عليه وسلم: «ما نقص قوم المكيال والميزان إلا ارتفع عنهم الرزق»", "qawaid": [], "tabi": ""}], "mushid": {"i": 17, "imgs": ["011_017_1.png"], "pages": [291], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3270, "masala": "المراد ب «الخير» في قوله تعالى: {إني أراكم بخير}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن ذلك الخير هو رخص الأسعار", "ashab": "", "athar": []}, {"n": 2, "t": "أنه المال، وزينة الدنيا", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 86, "title": "تأويل: ﴿بقيت الله خير لكم إن كنتم مؤمنين وما أنا عليكم بحفيظ﴾", "tabari": {"page": "12/543", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك: حظكم من ربكم خير لكم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [36213]}, {"n": 2, "t": "معناه: رزق الله خير لكم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [36209, 36210]}]}, "mawaqif": [{"taliq": 3272, "mi": 1, "aya": 86, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 541", "qawl": "الأول", "nass": "لأن الله -تعالى ذكره- إنما تقدم إليهم بالنهي عن بخس الناس أشياءهم في المكيال والميزان، وإلى ترك التطفيف في الكيل والبخس في الميزان دعاهم شعيب، فتعقيب ذلك بالخبر عما لهم من الحظ في الوفاء في الدنيا والآخرة أولى، مع أن قوله: {بقيت} إنما هي مصدر من قول القائل: بقيت بقية من كذا، فلا وجه لتوجيه معنى ذلك إلا إلى: بقية الله التي أبقاها لكم مما لكم بعد وفائكم الناس حقوقهم خير لكم من بقيتكم من الحرام الذي يبقى لكم من ظلمكم الناس ببخسكم إياهم في الكيل والوزن", "qawaid": ["السياق", "اللغة"], "tabi": ""}, {"taliq": 3272, "mi": 1, "aya": 86, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "4/ 630", "qawl": "الأول", "nass": "وهذا تفسير يليق بلفظ الآية", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "mushid": {"i": 18, "imgs": ["011_018_1.png"], "pages": [291], "n": 4, "rajih": [1], "daif": [], "match": false}, "mawsua": {"taliq": 3272, "masala": "معنى: {بقيت الله خير لكم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "ما أبقى الله لكم من الحلال بعد إيفاء الكيل والوزن خير من البخس", "ashab": "", "athar": []}, {"n": 2, "t": "طاعة الله خير لكم", "ashab": "", "athar": []}, {"n": 3, "t": "حظكم من ربكم خير لكم", "ashab": "", "athar": []}, {"n": 4, "t": "رزق الله خير لكم", "ashab": "", "athar": []}, {"n": 5, "t": "رحمة الله خير لكم", "ashab": "", "athar": []}, {"n": 6, "t": "ثواب الله في الآخرة خير لكم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق", "اللغة"]}, "rulesD": {}}}, {"aya": 87, "title": "معنى: {أصلاتك}", "mawsua": {"taliq": 3273, "masala": "معنى: {أصلاتك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الصلوات المعروفة", "ashab": "", "athar": []}, {"n": 2, "t": "قراءتك", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3273, "mi": 1, "aya": 87, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "5/ 5", "qawl": "", "nass": "وأقرب هذه الأقوال الأول، والرابع", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 87, "title": "معنى: {أصلاتك}", "mawsua": {"taliq": 3273, "masala": "معنى: {أصلاتك}", "sigha": "زاد قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أمساجدك", "ashab": "", "athar": []}, {"n": 2, "t": "أدعواتك", "ashab": "", "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 91, "title": "معنى: {لرجمناك}", "mawsua": {"taliq": 3280, "masala": "معنى: {لرجمناك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "لرجمناك بالحجارة", "ashab": "", "athar": []}, {"n": 2, "t": "لرجمناك بالسب", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3280, "mi": 1, "aya": 91, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 9", "qawl": "الأول", "nass": "وهذا أيضا تستعمله العرب، ومنه قوله تعالى: {لأرجمنك واهجرني مليا} [مريم: 46]", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "tags": {"m": {"1": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 92, "title": "تأويل: ﴿واتخذتموه وراءكم ظهريا﴾", "tabari": {"page": "12/557", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿واتخذتموه وراءكم ظهريا﴾. قال: الظهري: الفضل. مثل الحمال يخرج معه بإبل ظهارية فضل، لا يحمل عليها شيئا، إلا أن يحتاج إليها. قال: فيقول: إنما ربكم عندكم مثل هذا إن احتجتم إليه، وإن لم تحتاجوا إليه فليس بشيء .", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك: واتخذتم ما جاء به شعيب وراءكم ظهريا، فالهاء التى فى قوله: ﴿واتخذتموه﴾. على هذا القول ، من ذكر ما جاء به شعيب ﵇", "taqdim": 0, "n_athar": 5, "qailun": [["مجاهد", "تابعي"]], "athar": [36302, 36303]}]}, "mawaqif": [{"taliq": 3281, "mi": 1, "aya": 92, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 10", "qawl": "الأول", "nass": "وهو عندي على حذف مضاف ولا بد", "qawaid": [], "tabi": ""}, {"taliq": 3281, "mi": 1, "aya": 92, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 555", "qawl": "الأول", "nass": "لقرب قوله: {واتخذتموه وراءكم ظهريا} من قوله: {أرهطي أعز عليكم من الله}، فكانت الهاء في قوله: {واتخذتموه} بأن تكون من ذكر الله لقرب جوارها منه أشبه وأولى", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3281, "mi": 1, "aya": 92, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 9", "qawl": "", "nass": "أترون رهطي أعز عليكم من الله وأنتم تتخذون الله سند ظهوركم وعماد آمالكم", "qawaid": [], "tabi": ""}], "mushid": {"i": 19, "imgs": ["011_019_1.png"], "pages": [291], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3281, "masala": "هاء الكناية من قوله تعالى: {واتخذتموه وراءكم ظهريا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها ترجع إلى الله تعالى، والمعنى: رميتم بأمر الله وراء ظهوركم", "ashab": "", "athar": []}, {"n": 2, "t": "أنها كناية عما جاء به شعيب عليه السلام", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 92, "title": "هاء الكناية من قوله تعالى: {واتخذتموه وراءكم ظهريا}", "mawsua": {"taliq": 3281, "masala": "هاء الكناية من قوله تعالى: {واتخذتموه وراءكم ظهريا}", "sigha": "ذكر وجهين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "إما بأن يطرح", "ashab": "", "athar": []}, {"n": 2, "t": "إما بأن يسند إليه ويلجأ. وزاد قولا آخر عن فرقة: أن المعنى: «أترون رهطي أعز عليكم من الله وأنتم تتخذون الله سند ظهوركم وعماد آمالكم", "ashab": "", "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 100, "title": "معنى {القرى}", "mawsua": {"taliq": 3282, "masala": "معنى {القرى}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يراد بها: القرى التي ذكرت في الآيات المتقدمة خاصة", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: القرى عامة. ثم وجه الاحتمال الثاني بقوله: «أي: هذه الأنباء المقصوصة عليك هي عوائد المدن إذا كفرت. فيدخل على هذا التأويل فيها المدن المعاصرة، ويجيء قوله تعالى: {منها قائم وحصيد}: منها عامر وداثر", "ashab": "ابن عباس»", "athar": []}]}, "mawaqif": [{"taliq": 3282, "mi": 1, "aya": 100, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 14", "qawl": "الثاني", "nass": "أي: هذه الأنباء المقصوصة عليك هي عوائد المدن إذا كفرت. فيدخل على هذا التأويل فيها المدن المعاصرة، ويجيء قوله تعالى: {منها قائم وحصيد}: منها عامر وداثر. وهذا قول ابن عباس", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 105, "title": "تأويل: ﴿يوم يأت لا تكلم نفس إلا بإذنه فمنهم شقي وسعيد فأما الذين شقوا ففي النار لهم فيها زفير وشهي﴾", "tabari": {"page": "12/576", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول ﷿: يوم يأتى يوم القيامة أيها الناس، وتقوم الساعة، لا تتكلم نفس إلا بإذن ربها.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿لا تكلم﴾. وإنما هو: لا تتكلم. فحذفت إحدى التاءين؛ اجتزاء بدلالة الباقية منهما عليها", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 107, "title": "في معنى ذلك ﴿خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك إن ربك فعال لما يريد﴾", "tabari": {"page": "12/579", "sarih": 1, "tarjih": "وأولى هذه الأقوال في تأويل هذه الآية بالصواب القول الذي ذكرناه عن قتادة والضحاك، من أن ذلك استثناء فى أهل التوحيد من أهل الكبائر أنه مدخلهم النار، فتاركهم فيها أبدا، إلا ما شاء من تركهم فيها أقل من ذلك، ثم يخرجهم منها فيدخلهم الجنة. كما قد بينا في غير هذا الموضع بما أغنى عن إعادته في هذا الموضع .", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هذا استثناء استثناه الله في أهل التوحيد [أنه يخرجهم] من النار إذا شاء بعد أن أدخلهم النار", "taqdim": 0, "n_athar": 6, "qailun": [["قتادة", "تابعي"], ["أبي سنان فى", ""], ["الضحاك بن مزاحم", "تابعي"], ["خالد بن معدان", "تابعي"]], "athar": [36422, 36436, 36437, 36442, 36443]}, {"n": 2, "t": "الاستثناء فى هذه الآية فى أهل التوحيد. إلا أنهم قالوا: معنى قوله: ﴿إلا ما شاء ربك﴾. إلا أن يشاء ربك أن يتجاوز عنهم فلا يدخلهم النار. ووجهوا الاستثناء إلى أنه من قوله: ﴿فأما الذين شقوا ففي النار﴾ - ﴿إلا ما شاء ربك﴾ لا من الخلود", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 3, "t": "عنى بذلك أهل النار، وكل من دخلها", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["الشعبي", "تابعي"]], "athar": [36418, 36419, 36420, 36433, 36434, 36438]}, {"n": 4, "t": "أخبرنا الله بمشيئته لأهل الجنة، فعرفنا معنى ثنياه بقوله: ﴿عطاء غير مجذوذ﴾. أنها فى الزيادة على مقدار مدة السماوات والأرض. قالوا: ولم يخبرنا بمشيئته فى أهل النار، وجائز أن تكون مشيئته فى الزيادة، وجائز أن تكون في النقصان", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [36427, 36449]}]}, "mawaqif": [{"taliq": 3285, "mi": 1, "aya": 107, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 20 بتصرف", "qawl": "الأول", "nass": "فيجيء قوله: {إلا ما شاء ربك} أي: لقوم ما … وعلى هذا فيكون قوله: {فأما الذين شقوا} عاما في الكفرة والعصاة، ويكون الاستثناء من {خالدين}", "qawaid": [], "tabi": ""}, {"taliq": 3285, "mi": 1, "aya": 107, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "12/ 581", "qawl": "الثاني", "nass": "ووجهوا الاستثناء أنه من قوله: {فأما الذين شقوا في النار} - {إلا ما شاء ربك} لا من الخلود", "qawaid": [], "tabi": ""}, {"taliq": 3285, "mi": 1, "aya": 107, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 583", "qawl": "الأول", "nass": "لأن الله عز وجل أوعد أهل الشرك به الخلود في النار، وتظاهرت بذلك الأخبار عن رسول الله صلى الله عليه وسلم، فغير جائز أن يكون استثناء في أهل الشرك، وأن الأخبار قد تواترت عن رسول الله صلى الله عليه وسلم أن الله يدخل قوما من أهل الإيمان به بذنوب أصابوها النار، ثم يخرجهم منها فيدخلهم الجنة، فغير جائز أن يكون ذلك استثناء في أهل التوحيد قبل دخولها، مع صحة الأخبار عن رسول الله صلى الله عليه وسلم بما ذكرنا، وأنا إن جعلناه استثناء في ذلك، كنا قد دخلنا في قول من يقول: لا يدخل الجنة فاسق، ولا النار مؤمن. وذلك خلاف مذاهب أهل العلم، وما جاءت به الأخبار عن رسول الله صلى الله عليه وسلم", "qawaid": ["القرآن والنظائر", "السنة", "الدلالة العقلية"], "tabi": ""}, {"taliq": 3285, "mi": 1, "aya": 107, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "", "qawl": "", "nass": "فهم -على هذا- يخلدون حتى يصير أمرهم إلى هذا … والذي روي ونقل عن ابن مسعود وغيره إنما هو الدرك الأعلى المختص بعصاة المؤمنين، وهو الذي يسمي جهنم، وسمي الكل به تجوزا", "qawaid": [], "tabi": ""}, {"taliq": 3285, "mi": 1, "aya": 107, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "", "qawl": "", "nass": "فهو على نحو قوله: {لتدخلن المسجد الحرام إن شاء الله آمنين} [الفتح: 27] استثناء في واجب، وهذا الاستثناء في حكم الشرط، كأنه قال: إن شاء الله. فليس يحتاج إلى أن يوصف بمتصل ولا بمنقطع", "qawaid": [], "tabi": ""}, {"taliq": 3285, "mi": 1, "aya": 107, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "7/ 473", "qawl": "", "nass": "وهذا الذي عليه كثير من العلماء قديما وحديثا في تفسير هذه الآية الكريمة", "qawaid": [], "tabi": ""}], "mushid": {"i": 20, "imgs": ["011_020_1.png", "011_020_2.png"], "pages": [291, 292], "n": 4, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3285, "masala": "معنى الاستثناء في قوله تعالى: {إلا ما شاء ربك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه استثناء استثناه الله في أهل التوحيد؛ أنه يخرجهم من النار إذا شاء بعد أن أدخلهم فيها", "ashab": "", "athar": []}, {"n": 2, "t": "أنه استثناء في أهل التوحيد أن يتجاوز عنهم فلا يدخلهم النار", "ashab": "", "athar": []}, {"n": 3, "t": "أن المقصود بالاستثناء أهل النار وكل من دخلها", "ashab": "", "athar": []}, {"n": 4, "t": "أن الله أخبر بمشيئته لأهل الجنة أنها في الزيادة على مقدار مدة السماوات والأرض بقوله تعالى في معنى الاستثناء: {عطاء غير مجذوذ}، ولم يخبر بمشيئته في أهل النار، فجائز أن تكون في الزيادة، وجائز أن تكون في النقصان", "ashab": "", "athar": []}, {"n": 5, "t": "أنه استثناء من مدة المسافات التي بينهم في دخول النار، إذ دخولهم إنما هو زمرا بعد زمر", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]], "2": [["ابن جرير", "w"]]}, "t": {"1": [["ابن عطية", "w"], ["ابن جرير", "r"]], "2": [["ابن جرير", "w"]]}, "gen": [], "rules": {"ابن جرير": ["القرآن والنظائر", "السنة", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 108, "title": "تأويل: ﴿وأما الذين سعدوا ففي الجنة خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك عطاء غير مجذ﴾", "tabari": {"page": "12/586", "sarih": 0, "tarjih": "وأولى الأقوال فى ذلك عندى بالصواب القول الذي ذكرته عن الضحاك؛ وهو: ﴿وأما الذين سعدوا ففي الجنة خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك﴾ من قدر مكثهم فى النار، من لدن دخلوها ، إلى أن أدخلوا الجنة، وتكون الآية معناها الخصوص؛ لأن الأشهر من كلام العرب في \"إلا\" توجيهها إلى معنى الاستثناء، وإخراج معنى ما بعدها مما قبلها، إلا أن يكون معها دلالة تدل على خلاف ذلك، ولا دلالة في الكلام -أعنى في قوله: ﴿إلا ما شاء ربك﴾ - تدل على أن معناها غير معنى المفهوم في الكلام، فيوجه إليه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "معنى ذلك: ﴿إلا ما شاء ربك﴾ من الزيادة على قدر مدة دوام السماوات والأرض، قالوا : وذلك هو الخلود فيها أبدا", "taqdim": 0, "n_athar": 1, "qailun": [["أبي سنان", ""]], "athar": [36464]}, {"n": 2, "t": "جائز فيه وجه ثالث، وهو أن يكون استثنى من خلودهم فى الجنة احتباسهم عنها ما بين الموت والبعث؛ وهو البرزخ، إلى أن يصيروا إلى الجنة، ثم هو خلود الأبد ، يقول: فلم يغيبوا عن الجنة إلا بقدر إقامتهم في البرزخ", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "جائز أن يكون دوام السماوات والأرض بمعنى الأبد على ما تعرف العرب، وتستعمل وتستثنى المشيئة من دوامها؛ لأن أهل الجنة وأهل النار قد كانوا فى وقت من أوقات دوام السماء والأرض في الدنيا، لا فى الجنة، فكأنه قال: خالدين فى الجنة وخالدين في النار دوام السماء والأرض، إلا ما شاء ربك من تعميرهم في الدنيا قبل ذلك", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3286, "mi": 1, "aya": 108, "alam": "ابن جرير", "fil": "زاد", "kind": "نقل", "ref": "12/ 586 - 587", "qawl": "", "nass": "فقال بعضهم: في ذلك معنيان: أحدهما: أن تجعله استثناء يستثنيه ولا يفعله، كقولك: والله، لأضربنك إلا أن أرى غير ذلك. وعزمك على ضربه، قال: فكذلك قال: {خالدين فيها ما دامت السموات والأرض إلا ما شاء ربك}، ولا يشاؤه. قال: والقول الآخر: أن العرب إذا استثنت شيئا كثيرا مع مثله، ومع ما هو أكثر منه؛ كان معنى إلا ومعنى الواو سواء، فمن ذلك قوله: {خالدين فيها ما دامت السموات والأرض} سوى ما شاء الله من زيادة الخلود، فيجعل {إلا} مكان", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3286, "mi": 1, "aya": 108, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 22", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "mushid": {"i": 21, "imgs": ["011_021_1.png"], "pages": [292], "n": 2, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 3286, "masala": "معنى الاستثناء في قوله تعالى: {إلا ما شاء ربك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الاستثناء يرجع إلى مدة من لبث في النار من الموحدين، ثم أدخل الجنة", "ashab": "", "athar": []}, {"n": 2, "t": "أن المعنى: {إلا ما شاء ربك} من الزيادة على قدر مدة دوام السماوات والأرض", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 110, "title": "قوله: {ولولا كلمة سبقت من ربك لقضي بينهم}", "mawsua": {"taliq": 3289, "masala": "قوله: {ولولا كلمة سبقت من ربك لقضي بينهم}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد به: أمة موسى عليه السلام", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد به: معاصري محمد عليه السلام", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3289, "mi": 0, "aya": 110, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 23", "qawl": "العموم", "nass": "وأن يعمهم اللفظ أحسن عندي، ويؤكد ذلك قوله: {وإن كلا}", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 111, "title": "تأويل: ﴿وإن كلا لما ليوفينهم ربك أعمالهم إنه بما يعملون خبير﴾", "tabari": {"page": "12/594", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك، إذا قرئ كذلك: ﴿وإن كلا﴾: شديدا وحقا، ﴿ليوفينهم ربك أعمالهم﴾. قالوا : وإنما يراد إذا قرئ ذلك كذلك: (وإن كلا لما) بالتشديد والتنوين ، ولكن قارئ ذلك كذلك حذف منه التنوين، فأخرجه على لفظ \"فعلى\": \"لما\"، كما فعل ذلك في قوله: ﴿ثم أرسلنا رسلنا تترى﴾ [المؤمنون: ٤٤] فقرأ بعضهم: (تترى) بالتنوين -كما قرأ من قرأ: (لما) بالتنوين - وقرأها آخرون بغير تنوين، كما قرأ: (لما) من قرأه بغير تنوين . وقالوا: أصله من اللمم من قول ا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك، إذا قرئ كذلك: وإن كلا \"إلا\" ليوفينهم؛ كما يقول القائل: [بالله لما] قمت عنا، وبالله إلا قمت عنا. ووجدت عامة أهل العلم بالعربية ينكرون هذا القول، ويأبون أن يكون جائزا توجيه \"لما\" إلى معنى \"إلا\" إلا في اليمين خاصة؛ وقالوا: لو جاز أن يكون ذلك بمعنى \"إلا\"، لجاز أن يقال: قام القوم لما أخاك. بمعنى: إلا أخاك، ودخولها في كل موضع صلح دخول \"إلا\" فيه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 114, "title": "تأويل: ﴿وأقم الصلاة طرفي النهار وزلفا من الليل إن الحسنات يذهبن السيئات ذلك ذكرى للذاكرين﴾", "tabari": {"page": "12/603", "sarih": 0, "tarjih": "وأولى هذه الأقوال فى ذلك عندى بالصواب قول من قال: هي صلاة المغرب. [كما ذكرنا عن ابن عباس] .", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره لنبيه محمد ﷺ: ﴿وأقم الصلاة﴾ يا محمد، يعني: صل، ﴿طرفي النهار﴾. يعني: الغداة والعشي.", "taqdim": 1, "n_athar": 5, "qailun": [["مجاهد", "تابعي"], ["مجاهد فى", "تابعي"], ["محمد بن كعب القرظي", "تابعي"]], "athar": [36540, 36549, 36550, 36557, 36558, 36559, 36564, 36580, 36581, 36585]}, {"n": 2, "t": "بل عنى بها صلاة المغرب", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["الحسن", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [36525, 36526, 36527, 36528, 36529, 36538, 36539, 36543, 36544, 36545, 36546, 36547, 36552, 36553, 36554, 36555, 36556, 36561, 36562, 36567, 36573, 36577, 36583, 36584, 36588]}, {"n": 3, "t": "عنى بها صلاة العصر", "taqdim": 0, "n_athar": 6, "qailun": [["محمد بن كعب", "تابعي"], ["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": [36543, 36544, 36545, 36546, 36547, 36548, 36549, 36550, 36553, 36561, 36562, 36563, 36564, 36583, 36584, 36585, 36588]}, {"n": 4, "t": "بل عنى بطرفى النهار: الظهر والعصر، وبقوله: ﴿وزلفا من الليل﴾: المغرب والعشاء والصبح", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3293, "mi": 1, "aya": 114, "alam": "ابن جرير", "fil": "زاد", "kind": "نقل", "ref": "12/ 605", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3293, "mi": 1, "aya": 114, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "5/ 28", "qawl": "الثالث", "nass": "وليست الظهر في هذه الآية على هذا القول، بل هي في غيرها", "qawaid": [], "tabi": ""}, {"taliq": 3293, "mi": 1, "aya": 114, "alam": "ابن جرير", "fil": "زاده", "kind": "نقل", "ref": "", "qawl": "", "nass": "كأن هذا القائل راعى جهر القراءة", "qawaid": [], "tabi": ""}, {"taliq": 3293, "mi": 1, "aya": 114, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الثاني", "nass": "وإنما قلنا: هو أولى بالصواب. لإجماع الجميع على أن صلاة أحد الطرفين من ذلك صلاة الفجر، وهي تصلى قبل طلوع الشمس؛ فالواجب -إذ كان ذلك من جميعهم إجماعا- أن تكون صلاة الطرف الآخر: المغرب؛ لأنها تصلى بعد غروب الشمس، ولو كان واجبا أن يكون مرادا بصلاة أحد الطرفين قبل غروب الشمس وجب أن يكون مرادا بصلاة الطرف الآخر بعد طلوعها، وذلك ما لا نعلم قائلا قاله، إلا من قال: عني بذلك: صلاة الظهر والعصر. وذلك قول لا يخيل فساده، لأنهما إلى أن يكونا جميعا من صلاة أحد الطرفين أقرب منهما إلى أن يكونا من صلاة طرفي النهار، وذلك أن الظهر لا شك أنها تصلى بعد مضي نصف النهار في النصف الثاني منه، فمحال أن تكون من طرف النهار الأول، وهي تصلى في طرفه الآخر، فإذ كان لا قائل من أهل العلم يقول: عني بصلاة طرف النهار الأول صلاة بعد طلوع الشمس؛ وجب أن يكون غير جائز أن يقال: عني بصلاة طرف النهار الآخر صلاة قبل غروبها. وإذا كان ذلك كذلك صح ما قلنا في ذلك من القول، وفسد ما خالفه", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3293, "mi": 1, "aya": 114, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "والأول أحسن هذه الأقوال عندي، ورجح الطبري أن الطرفين: الصبح والمغرب، وأنه الظاهر، إلا أن عموم الصلوات الخمس بالآية أولى", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 22, "imgs": ["011_022_1.png", "011_022_2.png"], "pages": [292, 293], "n": 4, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 3293, "masala": "صلاة الطرف الثاني من طرفي النهار -بعد اتفاقهم على أن المقصود بالطرف الأول: صلاة الفجر-", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هما صلاة الظهر والعصر", "ashab": "", "athar": []}, {"n": 2, "t": "صلاة المغرب", "ashab": "", "athar": []}, {"n": 3, "t": "صلاة العصر", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]], "1": [["ابن عطية", "r"]]}, "t": {"2": [["ابن جرير", "r"]], "4": [["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"], "ابن عطية": ["العموم"]}, "rulesD": {}}}, {"aya": 114, "title": "تأويل: ﴿إن الحسنات يذهبن السيئات﴾", "tabari": {"page": "12/616", "sarih": 0, "tarjih": "وأولى التأويلين بالصواب فى ذلك قول من قال في ذلك: هن الصلوات الخمس؛ لصحة الأخبار عن رسول الله ﷺ، وتواترها عنه، أنه قال: \"مثل الصلوات الخمس مثل نهر جار على باب أحدكم، يغتمس فيه كل يوم خمس مرات، فماذا يبقين من درنه؟! . وأن ذلك فى سياق أمر الله بإقامة الصلوات، فالوعد على إقامتها الجزيل من الثواب عقيبها، أولى من الوعد على ما لم يجر له ذكر من سائر صالحات الأعمال، إذا خص بالقصد بذلك بعض دون بعض.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "﴿إن الحسنات يذهبن السيئات﴾. يقول تعالى ذكره: إن الإنابة إلى طاعة الله، والعمل بما يرضيه، تذهب آثام معصية الله، وتكفر الذنوب.", "taqdim": 1, "n_athar": 17, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["الحسن", "تابعي"], ["الضحاك", "تابعي"], ["عبد الله", "صحابي"], ["سلمان", "صحابي"], ["مسروق", "تابعي"], ["أبي مالك الأشعري", "صحابي"], ["أبي عثمان النهدي", "تابعي"]], "athar": [36525, 36526, 36527, 36528, 36529, 36538, 36539, 36540, 36541, 36542, 36543, 36544, 36545, 36546, 36547, 36553, 36554, 36555, 36556, 36557, 36558, 36559, 36560, 36561, 36562, 36568, 36569, 36573, 36574, 36575, 36576, 36577, 36579, 36580, 36581, 36582, 36583, 36584, 36588, 36597]}, {"n": 2, "t": "هى قول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [36540, 36557, 36558, 36559, 36580, 36581]}]}, "mawaqif": [{"taliq": 3294, "mi": 1, "aya": 114, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "5/ 29", "qawl": "", "nass": "وهذا كله إنما هو على جهة المثال في الحسنات، ومن أجل أن الصلوات الخمس هي أعظم الأعمال", "qawaid": [], "tabi": ""}, {"taliq": 3294, "mi": 1, "aya": 114, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 617", "qawl": "الأول", "nass": "لصحة الأخبار عن رسول الله صلى الله عليه وسلم، وتواترها عنه، أنه قال: «مثل الصلوات الخمس مثل نهر جار على باب أحدكم، يغتمس فيه كل يوم خمس مرات، فماذا يبقين من درنه؟!", "qawaid": ["السنة", "السياق"], "tabi": ""}, {"taliq": 3294, "mi": 1, "aya": 114, "alam": "ابن عطية", "fil": "استظهر", "kind": "ترجيح", "ref": "", "qawl": "العموم", "nass": "أن لفظ الآية لفظ عام في الحسنات، خاص في السيئات لقوله عليه الصلاة والسلام: «ما اجتنبت الكبائر»", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 24, "imgs": ["011_024_1.png"], "pages": [293], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3294, "masala": "المعني ب «الحسنات» اللاتي يذهبن «السيئات»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها الصلوات الخمس المكتوبات", "ashab": "", "athar": []}, {"n": 2, "t": "أنها قول: سبحان الله، والحمدلله، ولا إله إلا الله، والله أكبر", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [["ابن عطية", "رجّح العموم"]], "rules": {"ابن جرير": ["السنة", "السياق"], "ابن عطية": ["العموم"]}, "rulesD": {}}}, {"aya": 116, "title": "تأويل: ﴿واتبع الذين ظلموا ما أترفوا فيه﴾", "tabari": {"page": "12/630", "sarih": 0, "tarjih": "وأولى الأقوال فى ذلك بالصواب أن يقال: إن الله ﷿ أخبر أن الذين ظلموا أنفسهم من كل أمة سلفت، فكفروا بالله، اتبعوا ما أنظروا فيه من لذات الدنيا ، فاستكبروا عن أمر الله وتجبروا، وصدوا عن سبيله.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿واتبع الذين ظلموا ما أترفوا فيه﴾. يقول تعالى ذكره: واتبع الذين ظلموا أنفسهم وكفروا بالله ﴿ما أترفوا فيه﴾. [فاختلف أهل التأويل فى تأويل ذلك؛ فقال بعضهم: معناه أنهم اتبعوا ما أبطروا فيه] .", "taqdim": 1, "n_athar": 2, "qailun": [["ابن جريج", "تابع التابعين"], ["قتادة", "تابعي"]], "athar": [36611, 36614, 36619]}, {"n": 2, "t": "معنى ذلك: واتبع الذين ظلموا ما تجبروا فيه من الملك، وعتوا عن أمر الله", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [36617]}]}, "mawaqif": [{"taliq": 3297, "mi": 1, "aya": 116, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "12/ 630", "qawl": "الأول", "nass": "وكأن هؤلاء وجهوا تأويل الكلام: واتبع الذين ظلموا الشيء الذي أنظرهم فيه ربهم من نعيم الدنيا ولذاتها، إيثارا له على عمل الآخرة، وما ينجيهم من عذاب الله", "qawaid": [], "tabi": ""}, {"taliq": 3297, "mi": 1, "aya": 116, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 631", "qawl": "العموم", "nass": "أن يقال: إن الله عز وجل أخبر أن الذين ظلموا أنفسهم من كل أمة سلفت فكفروا بالله؛ اتبعوا ما أنظروا فيه من لذات الدنيا، فاستكبروا عن أمر الله، وتجبروا، وصدوا عن سبيله. وذلك أن المترف في كلام العرب: هو المنعم الذي قد غذي باللذات", "qawaid": ["اللغة", "العموم"], "tabi": ""}], "mushid": {"i": 25, "imgs": ["011_025_1.png"], "pages": [293], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3297, "masala": "معنى: {واتبع الذين ظلموا ما أترفوا فيه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "معناه: واتبع الذين ظلموا ما أبطروا فيه", "ashab": "", "athar": []}, {"n": 2, "t": "واتبع الذين ظلموا ما تجبروا فيه من الملك، وعتوا عن أمر الله", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "w"], ["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "w"], ["ابن جرير", "r"]]}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {"ابن جرير": ["اللغة", "العموم"]}, "rulesD": {}}}, {"aya": 116, "title": "مدة القرن", "mawsua": {"taliq": 3296, "masala": "مدة القرن", "sigha": "ذكر ثلاثة أقوال", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن أكثره مائة سنة", "ashab": "", "athar": []}, {"n": 2, "t": "ثمانون سنة", "ashab": "", "athar": []}, {"n": 3, "t": "قيل غير ذلك إلى ثلاثين سنة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3296, "mi": 1, "aya": 116, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 32", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3296, "mi": 1, "aya": 116, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "والأرجح الأول؛ لقول النبي صلى الله عليه وسلم: «أرأيتكم ليلتكم هذه فإن إلى رأس مائة سنة منها لا يبقى ممن هو اليوم على ظهر الأرض أحد", "qawaid": ["السنة"], "tabi": ""}], "tags": {"m": {"1": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["السنة"]}, "rulesD": {}}}, {"aya": 117, "title": "معنى قوله تعالى: {بظلم}", "mawsua": {"taliq": 3298, "masala": "معنى قوله تعالى: {بظلم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "يحتمل أن يريد: بظلم منه لهم -تعالى عن ذلك-", "ashab": "", "athar": []}, {"n": 2, "t": "قال الطبري: ويحتمل أن يريد: بشرك منهم وهم مصلحون في أعمالهم وسيرهم، وعدل بعضهم في بعض، أي: أنهم لا بد من معصية تقترن بكفرهم\"", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 3298, "mi": 1, "aya": 117, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 33", "qawl": "", "nass": "يحتمل أن يريد: بظلم منه لهم -تعالى عن ذلك-", "qawaid": [], "tabi": ""}, {"taliq": 3298, "mi": 1, "aya": 117, "alam": "ابن القيم", "fil": "وجه", "kind": "توجيه", "ref": "2/ 61 - 62 بتصرف", "qawl": "الأول", "nass": "والمعنى: إنه لم يكن ظالما لهم في إهلاكهم، فإنه لم يهلكهم وهم مصلحون، وإنما أهلكهم وهم ظالمون، فهم الظالمون لمخالفتهم، وهو العادل في إهلاكهم", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن القيم", "w"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 119, "title": "تأويل: ﴿ولا يزالون مختلفين﴾", "tabari": {"page": "12/636", "sarih": 0, "tarjih": "وأولى الأقوال في تأويل ذلك بالصواب قول من قال: معنى ذلك: ولا يزال الناس مختلفين في أديانهم وأهوائهم على أديان وملل وأهواء شتى، ﴿إلا من رحم ربك﴾، فآمن بالله، وصدق رسله، فإنهم لا يختلفون في توحيد الله، وتصديق رسله، وما جاءهم من عند الله.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "﴿ولا يزالون مختلفين﴾. يقول: ولا يزال الناس مختلفين، ﴿إلا من رحم ربك﴾.", "taqdim": 1, "n_athar": 19, "qailun": [["عطاء", "تابعي"], ["مجاهد", "تابعي"], ["منصور بن عبد الرحمن", ""], ["عكرمة", "تابعي"], ["ابن جريج", "تابع التابعين"], ["قتادة", "تابعي"], ["الأعمش", "تابع التابعين"], ["الحسن", "تابعي"]], "athar": [36649, 36650, 36654, 36655, 36656, 36658, 36659, 36660]}, {"n": 2, "t": "بل معنى ذلك: ولا يزالون مختلفين في الرزق؛ فهذا فقير، وهذا غني", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 3, "t": "مختلفين فى المغفرة والرحمة. أو كما قال", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3299, "mi": 1, "aya": 118, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 636 - 637", "qawl": "الأول", "nass": "لأن الله -جل ثناؤه- أتبع ذلك قوله: {وتمت كلمة ربك لأملأن جهنم من الجنة والناس أجمعين}، ففي ذلك دليل واضح أن الذي قبله من ذكر خبره عن اختلاف الناس، إنما هو خبر عن اختلاف مذموم يوجب لهم النار، ولو كان خبرا عن اختلافهم في الرزق لم يعقب ذلك بالخبر عن عقابهم وعذابهم", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3299, "mi": 1, "aya": 118, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 33", "qawl": "", "nass": "لا يزالون مختلفين في السعادة والشقاوة", "qawaid": [], "tabi": ""}, {"taliq": 3299, "mi": 1, "aya": 118, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 489", "qawl": "الأول", "nass": "والمشهور الصحيح الأول", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 26, "imgs": ["011_026_1.png"], "pages": [293], "n": 3, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3299, "masala": "معنى الاختلاف الذي وصف الله الناس أنهم لا يزالون به", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هو الاختلاف في الأديان، والمعنى: ولا يزال الناس مختلفين على أديان شتى، من بين يهودي، ونصراني، ومجوسي، وغير ذلك، وقالوا: استثنى الله من ذلك من رحمهم، وهم أهل الإيمان", "ashab": "", "athar": []}, {"n": 2, "t": "هو الاختلاف في الرزق، فهذا فقير وهذا غني", "ashab": "", "athar": []}, {"n": 3, "t": "هو الاختلاف في المغفرة والرحمة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"], "ابن كثير": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 119, "title": "في تأويله", "tabari": {"page": "12/637", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب قول من قال: وللاختلاف بالشقاء والسعادة. خلقهم. لأن الله جل ثناؤه، ذكر صنفين من خلقه؛ أحدهما: أهل اختلاف وباطل. والآخر: أهل حق. ثم عقب ذلك بقوله: ﴿ولذلك خلقهم﴾. فعم بقوله: ﴿ولذلك خلقهم﴾. صفة الصنفين، فأخبر عن كل فريق منهما أنه ميسر لما خلق له.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: وللاختلاف خلقهم", "taqdim": 0, "n_athar": 9, "qailun": [["الحسن", "تابعي"], ["خالد الحذاء", "تابعي"], ["ابن عباس", "صحابي"], ["عطاء فى", "تابعي"], ["قول الله", ""]], "athar": [36646, 36647, 36654, 36655, 36656]}, {"n": 2, "t": "بل معنى ذلك: وللرحمة خلقهم", "taqdim": 0, "n_athar": 9, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["الضحاك", "تابعي"], ["ابن جريج", "تابع التابعين"], ["ابن عباس", "صحابي"]], "athar": [36646, 36647, 36649, 36650, 36651, 36659]}]}, "mawaqif": [{"taliq": 3300, "mi": 1, "aya": 119, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 640 - 641", "qawl": "الأول", "nass": "لأن الله -جل ثناؤه- ذكر صنفين من خلقه: أحدهما: أهل اختلاف وباطل، والآخر: أهل حق. ثم عقب ذلك بقوله: {ولذلك خلقهم}، فعم بقوله: {ولذلك خلقهم} صفة الصنفين، فأخبر عن كل فريق منهما أنه ميسر لما خلق له. فإن قال قائل: فإن كان تأويل ذلك كما ذكرت فقد ينبغي أن يكون المختلفون غير ملومين على اختلافهم؛ إذ كان لذلك خلقهم ربهم، وأن يكون المتمتعون هم الملومين؟ قيل: إن معنى ذلك بخلاف ما إليه ذهبت، وإنما معنى الكلام: ولا يزال الناس مختلفين بالباطل من أديانهم ومللهم، {إلا من رحم ربك} فهداه للحق ولعلمه، وعلى علمه النافذ فيهم قبل أن يخلقهم -أنه يكون فيهم المؤمن والكافر، والشقي والسعيد- خلقهم، فمعنى اللام في قوله: {ولذلك خلقهم} بمعنى: على، كقولك للرجل: أكرمتك على برك بي، وأكرمتك لبرك بي", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 3300, "mi": 1, "aya": 119, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "", "qawl": "", "nass": "ولشهود اليوم المشهود -المتقدم ذكره- خلقهم", "qawaid": [], "tabi": ""}, {"taliq": 3300, "mi": 1, "aya": 119, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "7/ 490", "qawl": "الثاني", "nass": "ويرجع معنى هذا القول إلى قوله تعالى: {وما خلقت الجن والإنس إلا ليعبدون}", "qawaid": [], "tabi": ""}], "mushid": {"i": 27, "imgs": ["011_027_1.png"], "pages": [294], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 3300, "masala": "معنى: {ولذلك خلقهم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "وللاختلاف خلقهم", "ashab": "", "athar": []}, {"n": 2, "t": "وللرحمة خلقهم. وفرق ابن عطية (5/ 34) بين قول ابن عباس ومالك وبين قول الحسن، بينما جعلهما ابن جرير قولا واحدا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 120, "title": "في تأويله", "tabari": {"page": "12/643", "sarih": 1, "tarjih": "وأولى القولين بالصواب في تأويل ذلك قول من قال: وجاءك في هذه السورة الحق؛ لإجماع الحجة من أهل التأويل على أن ذلك تأويله.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: وجاءك فى هذه السورة الحق", "taqdim": 0, "n_athar": 20, "qailun": [["أبي موسى", "صحابي"], ["ابن عباس", "صحابي"], ["رجل من بنى العنبر", ""], ["مجاهد", "تابعي"], ["أبي العالية", "تابعي"], ["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": [36667, 36672, 36674, 36675, 36677, 36678, 36679, 36680, 36681]}, {"n": 2, "t": "معنى ذلك: وجاءك في هذه الدنيا الحق", "taqdim": 0, "n_athar": 3, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 3302, "mi": 1, "aya": 120, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 647", "qawl": "الأول", "nass": "لإجماع الحجة من أهل التأويل على أن ذلك تأويله", "qawaid": ["الإجماع"], "tabi": ""}, {"taliq": 3302, "mi": 1, "aya": 120, "alam": "ابن كثير", "fil": "رجحه", "kind": "ترجيح", "ref": "7/ 491", "qawl": "", "nass": "والصحيح: في هذه السورة المشتملة على قصص الأنبياء، وكيف نجاهم الله والمؤمنين بهم وأهلك الكافرين، جاءك فيها قصص حق، ونبأ صدق، وموعظة يرتدع بها الكافرون، وذكرى يتوقر بها المؤمنون", "qawaid": ["السياق"], "tabi": "ابن جرير"}, {"taliq": 3302, "mi": 1, "aya": 120, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 36", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3302, "mi": 1, "aya": 120, "alam": "ابن جرير", "fil": "أورد", "kind": "نقل", "ref": "", "qawl": "", "nass": "فإن قال قائل: أولم يجئ النبي صلى الله عليه وسلم الحق من سور القرآن إلا في هذه السورة، فيقال: وجاءك في هذه السورة الحق؟ قيل له: بلى، قد جاءه فيها كلها. فإن قال: فما وجه خصوصه إذن في هذه السورة بقوله: {وجاءك في هذه الحق}؟ قيل: إن معنى الكلام: وجاءك في هذه السورة الحق، مع ما جاءك في سائر سور القرآن، أو إلى ما جاءك من الحق في سائر سور القرآن، لا أن معناه: وجاءك في هذه السورة الحق، دون سائر سور القرآن", "qawaid": [], "tabi": ""}, {"taliq": 3302, "mi": 1, "aya": 120, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "", "qawl": "الأول", "nass": "ووجه تخصيص هذه السورة بوصفها ب {الحق} -والقرآن كله حق-: أن ذلك يتضمن معنى الوعيد للكفرة، والتنبيه للناظر، أي: جاءك في هذه السورة الحق الذي أصاب الأمم الظالمة. وهذا كما يقال عند الشدائد: جاء الحق. وإن كان الحق يأتي في غير شدة وغير ما وجه ولا يستعمل في ذلك: جاء الحق", "qawaid": [], "tabi": ""}], "mushid": {"i": 28, "imgs": ["011_028_1.png"], "pages": [294], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 3302, "masala": "معنى: {وجاءك في هذه الحق}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "وجاءك في هذه السورة الحق", "ashab": "", "athar": []}, {"n": 2, "t": "وجاءك في هذه الدنيا الحق", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الإجماع"], "ابن كثير": ["السياق"]}, "rulesD": {}}}], "extra": [{"i": 15, "aya": 80, "imgs": ["011_015_1.png"], "pages": [290], "ihala": 0}, {"i": 23, "aya": 114, "imgs": ["011_023_1.png"], "pages": [293], "ihala": 0}], "others": {"3": [{"id": 3170, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (12/ 313) غير قول قتادة.", "mawaqif": []}, {"id": 3171, "kinds": "نقد،بيان", "text": "انتَقَد ابنُ عطية (4/ 538) مستندًا إلى الدلالة العقلية ما أفاده قول مقاتل، فقال: «وأمّا مَن قال بأنّ المتاع الحسن: هو فوائد الدنيا وزينتها. فيضعف بأنّ الكفرة يتشاركون في ذلك أعظم مشاركة». وبيّن ابنُ عطية أنّ وصف المتاع بالحسن «إنما هو لطيب عيش المؤمن برجائه في الله عز وجل وفي ثوابه، وفرحه بالتقرب إليه بمفترضاته، والسرور بمواعيده، والكافر ليس في شيء من هذا».", "mawaqif": [{"taliq": 3171, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 538", "qawl": "مقاتل", "nass": "وأما من قال بأن المتاع الحسن: هو فوائد الدنيا وزينتها. فيضعف بأن الكفرة يتشاركون في ذلك أعظم مشاركة", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3171, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "", "qawl": "", "nass": "إنما هو لطيب عيش المؤمن برجائه في الله عز وجل وفي ثوابه، وفرحه بالتقرب إليه بمفترضاته، والسرور بمواعيده، والكافر ليس في شيء من هذا", "qawaid": [], "tabi": ""}]}, {"id": 3172, "kinds": "خلاف،ترجيح،تعليق،نقل،حصر", "text": "لم يذكر ابنُ جرير (12/ 313 - 314) غير قول قتادة، وقول مجاهد.\nوذكر ابنُ عطية (4/ 538) في الأجل قولين، استظهر الأول منهما، فقال: «والأجل المسمى: هو أجل الموت، معناه: إلى أجَلٍ مُسَمًّى لكل واحد منكم، وهذا ظاهر الآية». وعلّق عليه بقوله: «واليوم الكبير -على هذا- هو يوم القيامة». ثم ذكر في الآية احتمالًا آخر، فقال: «وتحتمل الآية أن يكون التوعد بتعجيل العذاب إن كفروا، والوعد بتمتيعهم إن آمنوا، فتشبه ما قاله نوح عليه السلام». وعلّق عليه بقوله: «واليوم الكبير -على هذا-: يوم بدر ونحوه، والمجهلة في أي الأمرين يكون إنما هي بحسب البشر، والأمر عند الله تعالى معلوم محصل، والأجل واحد».", "mawaqif": [{"taliq": 3172, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 538", "qawl": "", "nass": "والأجل المسمى: هو أجل الموت، معناه: إلى أجل مسمى لكل واحد منكم، وهذا ظاهر الآية", "qawaid": [], "tabi": ""}]}, {"id": 3174, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 539) في قوله: {يوم كبير} احتمالين، فقال: «وقوله تعالى: {فَإنِّي أخافُ عَلَيْكُمْ عَذابَ يَوْمٍ كَبِيرٍ} توعد بيوم القيامة، ويحتمل أن يريد به يومًا من الدنيا كبدر وغيره». ثم قوّى الاحتمال الأول بقوله: «وقوله تعالى: {إلى اللَّهِ مَرْجِعُكُمْ} توعد، وهو يؤيد أن اليوم الكبير يوم القيامة؛ لأنّه توعد به».", "mawaqif": [{"taliq": 3174, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 539", "qawl": "", "nass": "وقوله تعالى: {فإني أخاف عليكم عذاب يوم كبير} توعد بيوم القيامة، ويحتمل أن يريد به يوما من الدنيا كبدر وغيره", "qawaid": [], "tabi": ""}]}], "5": [{"id": 3176, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 541 - 542) في عود الضمير من قوله: {ليستخفوا منه} احتمالين، رجّح الأول منهما، فقال: «والضمير في {مِنهُ} عائد على الله تعالى، هذا هو الأفصح الأجزل في المعنى. وعلى بعض التأويلات يمكن أن يعود على محمد صلى الله عليه وسلم».\nورجح الأولَ ابنُ كثير (4/ 414) مستندًا إلى السياق، فقال: «وعود الضمير على الله أولى؛ لقوله: {ألا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون}».", "mawaqif": [{"taliq": 3176, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 541 - 542", "qawl": "", "nass": "والضمير في {منه} عائد على الله تعالى، هذا هو الأفصح الأجزل في المعنى. وعلى بعض التأويلات يمكن أن يعود على محمد صلى الله عليه وسلم", "qawaid": ["السياق"], "tabi": ""}]}, {"id": 3177, "kinds": "تعليق،نقل", "text": "ذكر ابنُ جرير (12/ 322) قول الضحاك بن مزاحم، وعلّق عليه قائلًا: «وهذا التأويل الذي تَأَوَّله الضحاك على مذهب قراءة ابن عباس، إلا أنّ الذي حدَّثنا هكذا ذكر القراءة في الرواية».", "mawaqif": [{"taliq": 3177, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 322", "qawl": "الضحاك بن", "nass": "وهذا التأويل الذي تأوله الضحاك على مذهب قراءة ابن عباس، إلا أن الذي حدثنا هكذا ذكر القراءة في الرواية", "qawaid": [], "tabi": ""}]}, {"id": 3179, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 323) في تفسير قوله: {ويستغشون ثيابهم} غير قول عبد الله بن عباس.", "mawaqif": []}], "6": [{"id": 3181, "kinds": "ترجيح،نقد،توجيه،نقل", "text": "ذكر ابنُ عطية (4/ 544) أنّ الكتاب هنا يراد به: اللوح المحفوظ. ثم نقل قولًا آخر: أن ذلك مجاز يراد به الإشارة إلى علم الله، ثم انتقده ورجَّح الأول مستندًا إلى ظاهر الآية، فقال: «وهذا ضعيف، وحملُه على الظاهر أولى».", "mawaqif": [{"taliq": 3181, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 544", "qawl": "", "nass": "وهذا ضعيف، وحمله على الظاهر أولى", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "7": [{"id": 3182, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 544) في مقدار أيام الخلق الستة أنّ أكثر أهل التفسير على أن هذه الأيام هي من أيام الدنيا، ثم نقل قولًا آخر نسبه لكعب الأحبار أنها من أيام الآخرة، ثم رجَّح الأول بقوله: «والأول أرجح». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3182, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 544", "qawl": "", "nass": "والأول أرجح", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 3183, "kinds": "غيره", "text": "لم يذكر ابن جرير (12/ 335) في معنى: {ليبلوكم أيكم أحسن عملًا} سوى حديث ابن عمر، وقول ابن جريج.", "mawaqif": []}], "8": [{"id": 3184, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 339) في معنى: {وحاق بهم ما كانوا به يستهزؤون} سوى قول مجاهد.", "mawaqif": []}], "9": [{"id": 3185, "kinds": "نقد،توجيه،بيان،تعليق،نقل", "text": "بيَّن ابنُ عطية (4/ 546) أن {الإنسان} في الآية يُرادُ به اسم الجنس، والمعنى: «إنّ هذا الخُلُق في سجية الناس. ثم استثنى منهم الذين ردَّتْهم الشرائع والإيمان إلى الصبر والعمل الصالح». ثم نقل قولًا آخر عن بعض الناس أنّ {الإنسان} في هذه الآية يُراد به: الكافر، وعلَّق عليه بقوله: «وحَمَلَه على ذلك لفظة {كفور}». ثم انتقده مستندًا إلى مخالفته اللغة بقوله: «وهذا عندي مردود؛ لأنّ صفة الكفر لا تطلق على جميع الناس كما تقتضي لفظة الإنسان».", "mawaqif": [{"taliq": 3185, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "4/ 546", "qawl": "", "nass": "إن هذا الخلق في سجية الناس. ثم استثنى منهم الذين ردتهم الشرائع والإيمان إلى الصبر والعمل الصالح", "qawaid": ["اللغة"], "tabi": ""}]}], "10": [{"id": 3186, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 341) في معنى: {إنه لفرح فخور} سوى قول ابن جريج.", "mawaqif": []}], "11": [{"id": 3187, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 547) أنّه على القول المتقدم بأنّ {الإنسان} عامٌّ يراد به اسم الجنس فالاستثناء متصل، وعلى القول بأنه مخصص بالكافر فالاستثناء منقطع، ثم انتقد القول الأخير بقوله: «وهو قول ضعيف من جهة المعنى، وأما من جهة اللفظ فجيِّد».", "mawaqif": [{"taliq": 3187, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 547", "qawl": "المتقدم بأن", "nass": "وهو قول ضعيف من جهة المعنى، وأما من جهة اللفظ فجيد", "qawaid": [], "tabi": ""}]}], "12": [{"id": 3188, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (4/ 536) قول مقاتل في مدنية الآيات الثلاث المذكورة في الأثر، ثم علَّق بقوله: «على أن الأولى تشبه المكي».", "mawaqif": [{"taliq": 3188, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "4/ 536", "qawl": "مقاتل في", "nass": "على أن الأولى تشبه المكي", "qawaid": [], "tabi": ""}]}], "13": [{"id": 3189, "kinds": "بيان،تعليق،نقل", "text": "قال ابنُ عطية (4/ 548 - 549): «ووقع التحدي في هذه الآية بعشرٍ لأنّه قيدها بالافتراء، فوسع عليهم في القدر لتقوم الحجة غاية القيام، إذ قد عجَّزهم في غير هذه الآية بسورة مِن مثله دون تقييد، فهذه مماثلة تامة في غيوب القرآن ومعانيه ونظمه ووعده ووعيده، وعُجِّزوا في هذه الآية بأن قيل لهم: عارضوا القدر منه بعشر أمثاله في التقدير، والغرض واحد، واجعلوه مفترًى لا يبقى لكم إلا نظمه، فهذه غاية التوسعة، وليس المعنى: عارضوا عشر سور بعشر؛ لأنّ هذه إنما كانت تجيء معارضة سورة بسورة مفتراة، ولا تبالي عن تقديم نزول هذه على هذه. ويؤيد هذا النظر أنّ التكليف في آية البقرة إنّما هو بسبب الريب، ولا يزيل الريب إلا العلم بأنّهم لا يقدرون على المماثلة التامة، وفي هذه الآية إنّما التكليف بسبب قولهم {افتراه} فكلفوا نحو ما قالوا، ولا يَطَّرِد هذا في آية يونس». ثم ذكر قولًا آخر، فقال: «وقال بعض الناس: هذه مقدمة في النزول على تلك، ولا يَصِحُّ أن يعجزوا في واحدة فيكلفوا عشرًا، والتكليفان سواء، ولا يَصِحُّ أن تكون السورة الواحدة إلا مفتراة، وآية سورة يونس في تكليف سورة متركبة على قولهم: افتراه، وكذلك آية البقرة وإنّما ريبهم بأنّ القرآن مفترى». وعلَّق عليه قائلًا: «وقائل هذا القول لم يلحظ الفرق بين التكليفين؛ في كمال المماثلة مرة، ووقوفها على النظم مرة».", "mawaqif": [{"taliq": 3189, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 548 - 549", "qawl": "", "nass": "ووقع التحدي في هذه الآية بعشر لأنه قيدها بالافتراء، فوسع عليهم في القدر لتقوم الحجة غاية القيام، إذ قد عجزهم في غير هذه الآية بسورة من مثله دون تقييد، فهذه مماثلة تامة في غيوب القرآن ومعانيه ونظمه ووعده ووعيده، وعجزوا في هذه الآية بأن قيل لهم: عارضوا القدر منه بعشر أمثاله في التقدير، والغرض واحد، واجعلوه مفترى لا يبقى لكم إلا نظمه، فهذه غاية التوسعة، وليس المعنى: عارضوا عشر سور بعشر؛ لأن هذه إنما كانت تجيء معارضة سورة بسورة مفتراة، ولا تبالي عن تقديم نزول هذه على هذه. ويؤيد هذا النظر أن التكليف في آية البقرة إنما هو بسبب الريب، ولا يزيل الريب إلا العلم بأنهم لا يقدرون على المماثلة التامة، وفي هذه الآية إنما التكليف بسبب قولهم {افتراه} فكلفوا نحو ما قالوا، ولا يطرد هذا في آية يونس", "qawaid": [], "tabi": ""}]}], "14": [{"id": 3190, "kinds": "بيان", "text": "بيَّن ابنُ عطية (4/ 549) أنّ لهذه الآية تأويلين: «أحدهما: أن تكون المخاطبة من النبي صلى الله عليه وسلم للكفار، أي: فإن لم يستجب مَن تدعون إلى شيء مِن المعارضة، ولا قدر جميعكم عليها؛ فأذعِنوا حينئذ، واعلموا أنّه من عند الله. ويأتي قوله: {فهل أنتم مسلمون} متمكنًا. والثاني: أن تكون مخاطبة من الله تعالى للمؤمنين، أي: فإن لم يستجب الكفار إلى ما دُعوا إليه من المعارضة فاعلموا أن ذلك مِن عند الله. وهذا على معنى: دوموا على علمكم؛ لأنهم كانوا عالمين بذلك».", "mawaqif": [{"taliq": 3190, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "4/ 549", "qawl": "", "nass": "أحدهما: أن تكون المخاطبة من النبي صلى الله عليه وسلم للكفار، أي: فإن لم يستجب من تدعون إلى شيء من المعارضة، ولا قدر جميعكم عليها؛ فأذعنوا حينئذ، واعلموا أنه من عند الله. ويأتي قوله: {فهل أنتم مسلمون} متمكنا. والثاني: أن تكون مخاطبة من الله تعالى للمؤمنين، أي: فإن لم يستجب الكفار إلى ما دعوا إليه من المعارضة فاعلموا أن ذلك من عند الله. وهذا على معنى: دوموا على علمكم؛ لأنهم كانوا عالمين بذلك", "qawaid": [], "tabi": ""}]}], "15": [{"id": 3191, "kinds": "توجيه", "text": "وجَّه ابنُ عطية (4/ 551) قول أنس بقوله: «ومعنى هذا: أنّ أهل الكتاب الكفرة يدخلون في هذه الآية، لا أنها ليست في غيرهم».", "mawaqif": [{"taliq": 3191, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "4/ 551", "qawl": "أنس بقوله", "nass": "ومعنى هذا: أن أهل الكتاب الكفرة يدخلون في هذه الآية، لا أنها ليست في غيرهم", "qawaid": [], "tabi": ""}]}, {"id": 3192, "kinds": "نقل", "text": "ذكر ابنُ عطية (4/ 551 - 552) في عود الضمير من قوله: {فيها} في هذه الآية والتي تليها احتمالات، فقال: «والضمير في قوله: {فيها} على الدنيا في الأولين، وفي الثالثة عائد على الآخرة، ويحتمل أن يعود في الثلاثة على الدنيا، ويحتمل أن تعود الثانية على الأعمال».", "mawaqif": [{"taliq": 3192, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 551 - 552", "qawl": "", "nass": "والضمير في قوله: {فيها} على الدنيا في الأولين، وفي الثالثة عائد على الآخرة، ويحتمل أن يعود في الثلاثة على الدنيا، ويحتمل أن تعود الثانية على الأعمال", "qawaid": [], "tabi": ""}]}], "17": [{"id": 3194, "kinds": "تعليق", "text": "علَّق ابن عطية (4/ 553) على قول مجاهد: مَلَكٌ يحفظه، بقوله: «ويحتمل أن يريد بهذه الألفاظ: جبريل عليه السلام».", "mawaqif": [{"taliq": 3194, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "4/ 553", "qawl": "مجاهد", "nass": "ويحتمل أن يريد بهذه الألفاظ: جبريل عليه السلام", "qawaid": [], "tabi": ""}]}], "18": [{"id": 3196, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابن عطية (4/ 556 - 557) قول مَن فسَّر {الأشهاد} بأنهم الشهداء من الأنبياء والملائكة، ثم علَّق عليه بقوله: «فيجيء قوله: {هؤلاء الذين كذبوا على ربهم} إخبارًا عنهم، وشهادةً عليهم». ثم نقل عن فرقة أنها قالت: {الأشهاد} بمعنى: الشاهدين، والمراد: جميع الخلائق. ثم علَّق بقوله: «وروي في نحو هذا حديث: «إنه لا يُخزى أحدٌ يوم القيامة إلا ويعلم ذلك جميع مَن شهد المحشر». فيجيء قوله: {هؤلاء} على هذا التأويل استفهامًا عنهم وتَثَبُّتًا فيهم، كما تقول إذا رأيت مجرمًا قد عُوقِب: هذا هو الذي فعل كذا وكذا. وإن كنت قد علمت ذلك، ويحتمل الإخبار عنهم».", "mawaqif": [{"taliq": 3196, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 556 - 557", "qawl": "", "nass": "فيجيء قوله: {هؤلاء الذين كذبوا على ربهم} إخبارا عنهم، وشهادة عليهم", "qawaid": [], "tabi": ""}]}], "22": [{"id": 3201, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 559) في قوله: {لا جرم} أربعة أقوال: الأول: أنها بمعنى: حقَّ. الثاني: أن تكون بمعنى: لا بُدَّ، أو: لا شك. الثالث: أن تكون {لا} ردٌّ عليهم ولما تقدم مِن كُلِّ ما قبلها، وتكون {جَرَم} بمعنى: كسَبَ، والمعنى: كسب فعلُهم {أنهم في الآخرة هم الأخسرون}. الرابع: أن تكون بمعنى: لا صَدَّ ولا منْع. وعلّق عليه قائلًا: «فكأنّ {جرم} على هذا مِن معنى القطع، تقول: جرمت، أي: قطعت».", "mawaqif": [{"taliq": 3201, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 559", "qawl": "", "nass": "فكأن {جرم} على هذا من معنى القطع، تقول: جرمت، أي: قطعت", "qawaid": [], "tabi": ""}]}], "27": [{"id": 3203, "kinds": "غيره", "text": "قال ابنُ القيم (2/ 54): «قال الزجاج: المعنى: إن كنتم تزعمون أنّهم إنما اتبعوني في بادي الرأي وظاهره فليس عَلَيَّ أن أطَّلع على ما في أنفسهم، فإذا رأيت مَن يُوَحِّد الله عملت على ظاهره، ورددت عِلْمَ ما في نفوسهم إلى الله. وهذا معنًى حسن. والذي يظهر من الآية: أنّ الله يعلم ما في أنفسهم، إذ أهَّلهم لقبول دينه وتوحيده، وتصديق رسله، والله? عليم حكيم، يضع العطاء في مواضعه، وتكون هذه الآية مثل قوله تعالى: {وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين} [الأنعام: 53]، فإنهم أنكروا أن يكون الله سبحانه أهلهم للهدى والحق، وحرمه رؤساء الكفار وأهل العزة والثروة منهم، كأنهم استدلوا بعطاء الدنيا على عطاء الآخرة، فأخبر الله سبحانه أنّه أعلم بمن يؤهله لذلك لِسِرٍّ عنده من معرفة قدر النعمة، ورؤيتها من مجرد فضل المنعم، ومحبته، وشكره عليها، وليس كل أحد عنده هذا السر؛ فلا يؤهل كل أحد لهذا العطاء».", "mawaqif": [{"taliq": 3203, "mi": 0, "aya": 27, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "2/ 54", "qawl": "", "nass": "قال الزجاج: المعنى: إن كنتم تزعمون أنهم إنما اتبعوني في بادي الرأي وظاهره فليس علي أن أطلع على ما في أنفسهم، فإذا رأيت من يوحد الله عملت على ظاهره، ورددت علم ما في نفوسهم إلى الله. وهذا معنى حسن. والذي يظهر من الآية: أن الله يعلم ما في أنفسهم، إذ أهلهم لقبول دينه وتوحيده، وتصديق رسله، والله? عليم حكيم، يضع العطاء في مواضعه، وتكون هذه الآية مثل قوله تعالى: {وكذلك فتنا بعضهم ببعض ليقولوا أهؤلاء من الله عليهم من بيننا أليس الله بأعلم بالشاكرين} [الأنعام: 53]، فإنهم أنكروا أن يكون الله سبحانه أهلهم للهدى والحق، وحرمه رؤساء الكفار وأهل العزة والثروة منهم، كأنهم استدلوا بعطاء الدنيا على عطاء الآخرة، فأخبر الله سبحانه أنه أعلم بمن يؤهله لذلك لسر عنده من معرفة قدر النعمة، ورؤيتها من مجرد فضل المنعم، ومحبته، وشكره عليها، وليس كل أحد عنده هذا السر؛ فلا يؤهل كل أحد لهذا العطاء", "qawaid": [], "tabi": ""}]}], "28": [{"id": 3204, "kinds": "توجيه", "text": "وجّه ابنُ عطية (4/ 565) قراءة أُبَيٍّ، فقال: «وفي قراءة أبي بن كعب: (أنُلْزِمُكُمُوها مِن شَطْرِ أنفُسِنا)، ومعناه: من تلقاء أنفسنا».", "mawaqif": [{"taliq": 3204, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "4/ 565", "qawl": "", "nass": "وفي قراءة أبي بن كعب: (أنلزمكموها من شطر أنفسنا)، ومعناه: من تلقاء أنفسنا", "qawaid": [], "tabi": ""}]}], "31": [{"id": 3205, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (12/ 387) غير قول ابن جريج.", "mawaqif": []}, {"id": 3206, "kinds": "نقد", "text": "قال ابنُ عطية (4/ 567): «وقوله: {اللَّهُ أعْلَمُ بِما فِي أنْفُسِهِمْ} تسليم لله تعالى، أي: لست أحكم عليهم بشيء من هذا، وإنما يحكم عليهم بذلك ويَخْرُج حكمه إلى حَيِّز الوجود اللهُ تعالى الذي يعلم ما في نفوسهم ويجازيهم بذلك. وقد قال بعض المتأولين: هي ردٌّ على قولهم: اتبعك أراذلنا على ما يظهر منهم. حسبما تقدم في بعض تأويلات تلك الآية آنفًا، فالمعنى: لست أنا أحكم عليهم بأن لا يكون لهم خيرٌ لظنكم بهم أنّ بواطنهم ليست كظواهرهم، الله أعلم بما في نفوسهم».", "mawaqif": [{"taliq": 3206, "mi": 0, "aya": 31, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 567", "qawl": "", "nass": "وقوله: {الله أعلم بما في أنفسهم} تسليم لله تعالى، أي: لست أحكم عليهم بشيء من هذا، وإنما يحكم عليهم بذلك ويخرج حكمه إلى حيز الوجود الله تعالى الذي يعلم ما في نفوسهم ويجازيهم بذلك. وقد قال بعض المتأولين: هي رد على قولهم: اتبعك أراذلنا على ما يظهر منهم. حسبما تقدم في بعض تأويلات تلك الآية آنفا، فالمعنى: لست أنا أحكم عليهم بأن لا يكون لهم خير لظنكم بهم أن بواطنهم ليست كظواهرهم، الله أعلم بما في نفوسهم", "qawaid": [], "tabi": ""}]}], "34": [{"id": 3207, "kinds": "نقد،بيان،نقل", "text": "قال ابنُ عطية (4/ 568 - 569 بتصرف): «وقالت فرقة: معنى قوله: {يُغْوِيَكُمْ}: يضلكم، مِن قولهم: غوى الرجل يغوى … وإذا كان هذا معنى اللفظة ففي الآية حُجَّة على المعتزلة القائلين: إنّ الضلال إنّما هو من العبد». ثم قال: «وقالت فرقة: معنى قوله: {يُغْوِيَكُمْ}: يهلككم، والغوى: المرض والهلاك، وفي لغة طيّء: أصبح فلان غاويًا، أي: مريضًا، والغوى: بَشَمُ الفصيل. قاله يعقوب في الإصلاح. وقيل: فقْده اللبن حتى يموت جوعًا. قاله الفرّاء، وحكاه الطبري. يقال: غوى يغوى، وحكى الزَّهراوي: أنه الذي قُطِع عنه اللبن حتى كاد يهلك ولَمّا يهلك بعدُ. فإذا كان هذا معنى اللفظة زال موضع النظر بين أهل السنة والمعتزلة، وبقي الاحتجاج عليهم بما هو أبين من هذه الآية، كقوله تعالى: {فَمَن يُرِدِ اللَّهُ أنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإسْلامِ} [الأنعام: 125] ونحوها. وأعتقد مكيٌّ أنّ للمعتزلة تَعَلُّقًا وحُجَّة بالغة بهذا التأويل، فردَّ عليه وأفرط حتى أنكر أن يكون الغوى بمعنى الهلاك موجودًا في لسان العرب».", "mawaqif": [{"taliq": 3207, "mi": 0, "aya": 34, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 568 - 569 بتصرف", "qawl": "", "nass": "وقالت فرقة: معنى قوله: {يغويكم}: يضلكم، من قولهم: غوى الرجل يغوى … وإذا كان هذا معنى اللفظة ففي الآية حجة على المعتزلة القائلين: إن الضلال إنما هو من العبد", "qawaid": [], "tabi": ""}]}], "35": [{"id": 3208, "kinds": "غيره", "text": "قال ابنُ عطية (4/ 569): «وقوله تعالى: {أمْ يَقُولُونَ افْتَراهُ} الآية، قال الطبريُّ وغيرُه من المتأولين والمؤلفين في التفسير: إنّ هذه الآية اعترضت في قصة نوح عليه السلام، وهي شأن محمد صلى الله عليه وسلم مع كفار قريش، وذلك أنهم قالوا: افترى القرآن، وافترى هذه القصة على نوح. فنَزلت الآية في ذلك. وهذا لو صَحَّ بسند وجب الوقوف عنده، وإلا فهو يحتمل أن يكون في شأن نوح عليه السلام، ويبقى اتِّساق الآيةِ مُطَّرِدًا، ويكون الضمير في قوله: {افْتَراهُ} عائدًا إلى العذاب الذي تَوَعَّدهم به، أو على جميع أخباره، وأوقع الافتراء على العذاب من حيث يقع على الإخبار به. والمعنى: أم يقول هؤلاء الكفرة: افترى نوحٌ هذا التَّوَعُّد بالعذاب، وأراد الإرهاب علينا بذلك. ثُمَّ يَطَّرِدُ باقي الآية على هذا».", "mawaqif": [{"taliq": 3208, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 569", "qawl": "", "nass": "وقوله تعالى: {أم يقولون افتراه} الآية، قال الطبري وغيره من المتأولين والمؤلفين في التفسير: إن هذه الآية اعترضت في قصة نوح عليه السلام، وهي شأن محمد صلى الله عليه وسلم مع كفار قريش، وذلك أنهم قالوا: افترى القرآن، وافترى هذه القصة على نوح. فنزلت الآية في ذلك. وهذا لو صح بسند وجب الوقوف عنده، وإلا فهو يحتمل أن يكون في شأن نوح عليه السلام، ويبقى اتساق الآية مطردا، ويكون الضمير في قوله: {افتراه} عائدا إلى العذاب الذي توعدهم به، أو على جميع أخباره، وأوقع الافتراء على العذاب من حيث يقع على الإخبار به. والمعنى: أم يقول هؤلاء الكفرة: افترى نوح هذا التوعد بالعذاب، وأراد الإرهاب علينا بذلك. ثم يطرد باقي الآية على هذا", "qawaid": [], "tabi": ""}]}], "37": [{"id": 3209, "kinds": "نقل", "text": "ذكر ابنُ عطية (4/ 573) في هيئة سفينة نوح قولًا أنّها كانت مربعة الشكل، طويلة في السماء، ضيقة الأعلى، وأنّ الغرض منها إنّما كان الحفظ، لا سرعة الجري، ثم قال: «والحديث الذي تَضَمَّن أنها كجؤجؤ الطائر أصَحُّ، ومعناه أظهر؛ لأنها لو كانت مربعة لم تكن فلكًا، بل كانت وعاء فقط، وقد وصفها الله تعالى بالجري في البحر، وفي الحديث: «كان راز سفينة نوح عليه السلام جبريل عليه السلام». والراز: القيِّم بعمل السفن».", "mawaqif": [{"taliq": 3209, "mi": 0, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 573", "qawl": "", "nass": "والحديث الذي تضمن أنها كجؤجؤ الطائر أصح، ومعناه أظهر؛ لأنها لو كانت مربعة لم تكن فلكا، بل كانت وعاء فقط، وقد وصفها الله تعالى بالجري في البحر، وفي الحديث: «كان راز سفينة نوح عليه السلام جبريل عليه السلام", "qawaid": [], "tabi": ""}]}, {"id": 3210, "kinds": "نقد،بيان", "text": "انتَقَدَ ابنُ عطية (4/ 573) مستندًا إلى السياق ما جاء في قول مجاهد وغيره بقوله: «ومَن فسر قوله: {ووَحْيِنا} أي: بأمرنا لك، فذلك ضعيف؛ لأن قوله: {واصْنَعِ الفُلْكَ} مُغْنٍ عن ذلك».", "mawaqif": [{"taliq": 3210, "mi": 0, "aya": 37, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 573", "qawl": "مجاهد وغيره", "nass": "ومن فسر قوله: {ووحينا} أي: بأمرنا لك، فذلك ضعيف؛ لأن قوله: {واصنع الفلك} مغن عن ذلك", "qawaid": ["السياق"], "tabi": ""}]}, {"id": 3211, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (12/ 392 - 393) غير قول قتادة، ومجاهد.", "mawaqif": []}, {"id": 3212, "kinds": "توجيه،بيان،نقل", "text": "ذكر ابنُ عطية (4/ 572) في قوله: {بأعيننا} احتمالين، فقال: «وقوله: {بِأَعْيُنِنا} يمكن -فيما يتأول- أن يريد به: بمرأًى منا وتحت إدراك، فتكون عبارة عن الإدراك والرعاية والحفظ، ويكون جمع الأعين للعظمة لا للتكثير، كما قال تعالى: {فَنِعْمَ القادِرُونَ} [المرسلات: 23]، فرجع معنى الأعين في هذه وفي غيرها إلى معنى عين في قوله: {لِتُصْنَعَ عَلى عَيْنِي} [طه: 39]، وذلك كله عبارة عن الإدراك وإحاطته بالمدركات، وهو تعالى مُنَزَّه عن الحواس والتشبيه والتكييف لا رب غيره. ويحتمل قوله: {بِأَعْيُنِنا} أي: بملائكتنا الذين جعلناهم عيونًا على مواضع حفظك ومعونتك، فيكون الجمع على هذا للتكثير». انتهى كلامه، وما قاله من نفي صفة العينين لله تعالى باطل، والحق إثباتهما له سبحانه على ما يليق بجلاله وكماله وعظمته، وهو إجماع السلف من الصحابة والتابعين وتابعيهم، ينظر: الإبانة الكبرى 3/ 113 - 127، شرح أصول اعتقاد أهل السنة 2/ 457 - 481.", "mawaqif": [{"taliq": 3212, "mi": 0, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 572", "qawl": "", "nass": "وقوله: {بأعيننا} يمكن -فيما يتأول- أن يريد به: بمرأى منا وتحت إدراك، فتكون عبارة عن الإدراك والرعاية والحفظ، ويكون جمع الأعين للعظمة لا للتكثير، كما قال تعالى: {فنعم القادرون} [المرسلات: 23]، فرجع معنى الأعين في هذه وفي غيرها إلى معنى عين في قوله: {لتصنع على عيني} [طه: 39]، وذلك كله عبارة عن الإدراك وإحاطته بالمدركات، وهو تعالى منزه عن الحواس والتشبيه والتكييف لا رب غيره. ويحتمل قوله: {بأعيننا} أي: بملائكتنا الذين جعلناهم عيونا على مواضع حفظك ومعونتك، فيكون الجمع على هذا للتكثير", "qawaid": [], "tabi": ""}]}], "38": [{"id": 3213, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 577) بعض ما جاء في قصص هذه الآية كما في هذا الأثر وما سبقه، فقال: «ورُوِي في قصص هذه الآية: أنّ نوحًا عليه السلام كان يأتيه الحيوان، فيضع يمينه على الذَّكَر، ويساره على الأنثى. ورُوِي: أنّ أول ما أدخل في السفينة الذَّرَّ، وآخر ما أدخل الحمار، فتَمَسَّك الشيطان بذنبه، فزجره نوحٌ عليه السلام، فلم يَنبَعِثْ، فقال له: ادخُلْ ولو كان معك الشيطان. قال ابن عباس: زَلَّت هذه الكلمةُ مِن لسانه، فدخل الشيطان حينئذ، وكان في كوثل السفينة، أي: عند مؤخرها، وقيل: كان على ظهرها. وروي: أنّ نوحًا عليه السلام آذاه نتن الزبل والعذرة، فأوحى الله إليه: أنِ امسح على ذَنَب الفيل، ففعل، فخرج مِن الفيل -وقيل: من أنفه- خنزير وخنزيرة، فكفيا نوحًا وأهله ذلك الأذى. وهذا يجيء منه أنّ نوع الخنازير لم يكن قبل ذلك. وروي: أنّ الفأر آذى الناس في السفينة بقرض حِبالها وغير ذلك، فأمر الله نوحًا أن يمسح على جبهة الأسد، ففعل، فعطس، فخرج منه هِرٌّ وهِرٌّة، فكفياهم الفأر. وروي أيضًا: أنّ الفأر خرج من أنف الخنزير». ثم علّق قائلًا: «وهذا كله قصص لا يصح إلا لو استند».", "mawaqif": [{"taliq": 3213, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 577", "qawl": "", "nass": "وروي في قصص هذه الآية: أن نوحا عليه السلام كان يأتيه الحيوان، فيضع يمينه على الذكر، ويساره على الأنثى. وروي: أن أول ما أدخل في السفينة الذر، وآخر ما أدخل الحمار، فتمسك الشيطان بذنبه، فزجره نوح عليه السلام، فلم ينبعث، فقال له: ادخل ولو كان معك الشيطان. قال ابن عباس: زلت هذه الكلمة من لسانه، فدخل الشيطان حينئذ، وكان في كوثل السفينة، أي: عند مؤخرها، وقيل: كان على ظهرها. وروي: أن نوحا عليه السلام آذاه نتن الزبل والعذرة، فأوحى الله إليه: أن امسح على ذنب الفيل، ففعل، فخرج من الفيل -وقيل: من أنفه- خنزير وخنزيرة، فكفيا نوحا وأهله ذلك الأذى. وهذا يجيء منه أن نوع الخنازير لم يكن قبل ذلك. وروي: أن الفأر آذى الناس في السفينة بقرض حبالها وغير ذلك، فأمر الله نوحا أن يمسح على جبهة الأسد، ففعل، فعطس، فخرج منه هر وهرة، فكفياهم الفأر. وروي أيضا: أن الفأر خرج من أنف الخنزير", "qawaid": [], "tabi": ""}]}, {"id": 3214, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 574) نحو ما جاء في هذا القول، ثم رجّح أن هذا في الدنيا، فقال: «وقوله: {فَإنّا نَسْخَرُ مِنكُمْ} قال الطبري: يريد في الآخرة. ويحتمل الكلام -بل هو الأرجح- أن يريد: إنا نسخر منكم الآن. أي: نستجهلكم؛ لعلمنا بما أنتم عليه مِن الغرر والكون بمدرج عذابه». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3214, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 574", "qawl": "", "nass": "وقوله: {فإنا نسخر منكم} قال الطبري: يريد في الآخرة. ويحتمل الكلام -بل هو الأرجح- أن يريد: إنا نسخر منكم الآن. أي: نستجهلكم؛ لعلمنا بما أنتم عليه من الغرر والكون بمدرج عذابه", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 3215, "kinds": "تعليق،نقل", "text": "علّق ابنُ عطية (4/ 574) على قول قتادة وغيره في وصف هيئة سفينة نوح، فقال: «قيل: طولها ثلاثمائة ذراع، وعرضها خمسون ذراعًا، وطولها في السماء ثلاثون ذراعًا. ذكره قتادة، وروي غير هذا مما لم يثبت، فاختصرت ذكره».", "mawaqif": [{"taliq": 3215, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "4/ 574", "qawl": "قتادة وغيره", "nass": "قيل: طولها ثلاثمائة ذراع، وعرضها خمسون ذراعا، وطولها في السماء ثلاثون ذراعا. ذكره قتادة، وروي غير هذا مما لم يثبت، فاختصرت ذكره", "qawaid": [], "tabi": ""}]}], "40": [{"id": 3217, "kinds": "نقد", "text": "انتَقَد ابنُ كثير (7/ 438) مستندًا إلى النظائر قولَ مَن قال: إنّ امرأة نوح كانت معه بالسفينة. فقال: «وهذا فيه نظر، بل الظاهر أنّها هلكت؛ لأنّها كانت على دين قومها، فأصابها ما أصابهم، كما أصاب امرأة لوط ما أصاب قومها».", "mawaqif": [{"taliq": 3217, "mi": 0, "aya": 40, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "7/ 438", "qawl": "", "nass": "وهذا فيه نظر، بل الظاهر أنها هلكت؛ لأنها كانت على دين قومها، فأصابها ما أصابهم، كما أصاب امرأة لوط ما أصاب قومها", "qawaid": ["القرآن والنظائر"], "tabi": ""}]}], "41": [{"id": 3220, "kinds": "توجيه", "text": "وجّه ابن عطية (4/ 578) ما جاء عن الضحاك في هذا القول، فقال: «ويصِحُّ أن يكون قولُه: {بسم الله} في موضع خبر، و {مجراها ومرساها} ابتداء مصدران، كأنّه قال: اركبوا فيها؛ فإنّ ببركة الله إجراءها وإرساءها، وتكون هذه الجملة -على هذا- في موضع حال مِن الضمير في قوله: {فيها}، ولا يصِحُّ أن يكون حالًا مِن الضمير في قوله: {اركبوا}؛ لأنّه لا عائد في الجملة يعود عليه: وعلى هذا التأويل قال الضحاك: إنّ نوحًا كان إذا أراد جري السفينة قال: بسم الله. فتجري، وإذا أراد وقوفها قال: بسم الله. فتقف».", "mawaqif": [{"taliq": 3220, "mi": 0, "aya": 41, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "4/ 578", "qawl": "", "nass": "ويصح أن يكون قوله: {بسم الله} في موضع خبر، و {مجراها ومرساها} ابتداء مصدران، كأنه قال: اركبوا فيها؛ فإن ببركة الله إجراءها وإرساءها، وتكون هذه الجملة -على هذا- في موضع حال من الضمير في قوله: {فيها}، ولا يصح أن يكون حالا من الضمير في قوله: {اركبوا}؛ لأنه لا عائد في الجملة يعود عليه: وعلى هذا التأويل قال الضحاك: إن نوحا كان إذا أراد جري السفينة قال: بسم الله. فتجري، وإذا أراد وقوفها قال: بسم الله. فتقف", "qawaid": [], "tabi": ""}]}], "42": [{"id": 3221, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 581) هذه القراءة، ثم علّق عليها قائلًا: «وعلى هذه القراءة يدخل تأويل مَن قال: كانت خائنة فيه».", "mawaqif": [{"taliq": 3221, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 581", "qawl": "", "nass": "وعلى هذه القراءة يدخل تأويل من قال: كانت خائنة فيه", "qawaid": [], "tabi": ""}]}, {"id": 3222, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 580) عن الزجاج وغيره أنّه أشار إلى أنّ الماء انطبق؛ ماء الأرض وماء السماء، فأصبح كالبحر، وانتقده مستندًا إلى الدلالة العقلية، فقال: «وهذا ضعيف، وأين كان الموج كالجبال على هذا؟! وكيف استقامت حياةُ مَن في السفينة على هذا؟!».", "mawaqif": [{"taliq": 3222, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 580", "qawl": "", "nass": "وهذا ضعيف، وأين كان الموج كالجبال على هذا؟! وكيف استقامت حياة من في السفينة على هذا؟!", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}, {"id": 3224, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 581) في قوله: {في معزل} احتمالين، فقال: «وقوله: {فِي مَعْزِلٍ} أي: في ناحية، فيمكن أن يريد في معزل في الدين، ويمكن أن يريد في معزل في بُعده عن السفينة». وعلّق بقوله: «واللفظ يعمهما».", "mawaqif": [{"taliq": 3224, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 581", "qawl": "", "nass": "وقوله: {في معزل} أي: في ناحية، فيمكن أن يريد في معزل في الدين، ويمكن أن يريد في معزل في بعده عن السفينة", "qawaid": [], "tabi": ""}]}], "43": [{"id": 3225, "kinds": "ترجيح،نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 174 - 175) في قوله: {لا عاصم اليوم} عدة احتمالات، فقال: «وقوله: {لا عاصِمَ} قيل فيه: إنّه على لفظة فاعل، وقوله: {إلّا مَن رَحِمَ} يريد: إلا الله الراحم، فـ {مَن} كناية عن اسم الله تعالى، المعنى: لا عاصم اليوم إلا الذي رحمنا، فـ {مَن} في موضع رفع. وقيل: قوله: {إلّا مَن رَحِمَ} استثناء منقطع، كأنّه قال: لا عاصم اليوم موجود، لكن من رحم اللهُ موجود». وعلّق على هذا الاحتمال الثاني بقوله: \"وحسَّنَ هذا من جهة المعنى أنّ نفي العاصم يقتضي نفي المعصوم، فهو حاصل بالمعنى. وأمّا من جهة اللفظ فـ {مَن} في موضع نصب، على حد قول النابغة: إلا الأواري. ولا يجوز أن تكون في موضع رفع على حد قول الشاعر:\nوبلدة ليس بها أنيس … إلا اليعافير وإلا العيس\nإذ هذان أنيس ذلك الموضع القفر، والمعصوم هنا ليس بعاصم بوجه «. ثم ذكر في الآية احتمالًا ثالثًا، فقال:» وقيل: {عاصِمَ} معناه: ذو اعتصام «. وعلق عليه قائلًا:» فـ {عاصِمَ} على هذا في معنى: معصوم، ويجيء الاستثناء مستقيمًا\".\nورجّح ابنُ القيم (2/ 55 - 56) أنّ الاستثناء في الآية منقطع، وانتقد ما سواه، مستندًا إلى دلالة العقل، فقال: «قوله تعالى: {لا عاصم اليوم من أمر الله إلا من رحم} الاستثناء منقطع على أصَحِّ الوجوه في الآية؛ فإنّه تعالى لَمّا ذكر العاصم استدعى معصومًا مفهومًا مِن السياق، فكأنه قيل: لا معصوم اليوم مِن أمره إلا مِن رحمة، فإنّه لما قال: {لا عاصم اليوم من أمر الله} بقي الذهنُ طالبًا للمعصوم، فكأنه قيل: فمَن الذي يعصم؟ فأجيب: بأنّه لا يعصم إلا من رحمة الله. ودلَّ هذا اللفظُ باختصاره وجلالته وفصاحته علي نفيِ كل عاصم سواه، وعلى نفي كل معصوم سوى مَن?، فدل الاستثناء على أمرين: على المعصوم من هو؟ وعلى العاصم وهو ذو الرحمة. وهذا مِن أبلغ الكلام وأفصحه وأوجزه، ولا يلتفت إلى ما قيل في الآية بعد ذلك».\nوذكر ابنُ القيم الاحتمال الثالث الذي أورده ابنُ عطية أنّ {عاصم} بمعنى: معصوم، وانتقده مستندًا إلى اللغة، فقال: «قيل: إنّ عاصمًا بمعنى: معصوم، كـ {ماء دافق} [الطارق: 6]، و {عيشة راضية} [الحاقة: 21]، والمعنى: لا معصوم إلا من رحمة الله. وهذا فاسد؛ لأنّ كل واحد من اسم الفاعل واسم المفعول موضوع لمعناه الخاص به، فلا يشاركه فيه الآخر، وليس الماء الدافق بمنى المدفوق، بل هو فاعل على بابه، كما يقال: ماء جار، فـ {دافق} كجار، فما الموجب للتكلف البارد؟». ثم ذكر بعده الاحتمال الأول الذي أورده ابنُ عطية، وانتقده أيضًا مستندًا إلى اللغة بقوله: «والقول الثاني: أنّ {من رحم} فاعل لا مفعول، والمعنى: لا يعصم اليوم من أمر الله إلا الراحم، فهو استثناء فاعل من فاعل. وهذا وإن كان أقل تكلفًا فهو أيضًا ضعيف جدًّا، وجزالة الكلام وبلاغته تأباه بأول نظر». ثم ذكر قولًا ثالثًا، وانتقده مستندًا إلى اللغة، فقال: «والقول الثالث: أن في الكلام مضافًا محذوفًا قام المضاف إليه مقامه، والتقدير: لا معصوم عاصم اليوم من أمر الله إلا من رحمة الله. وهذا من أنكر الأقوال وأشدها منافاة للفصاحة والبلاغة».", "mawaqif": [{"taliq": 3225, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 174 - 175", "qawl": "", "nass": "وقوله: {لا عاصم} قيل فيه: إنه على لفظة فاعل، وقوله: {إلا من رحم} يريد: إلا الله الراحم، ف {من} كناية عن اسم الله تعالى، المعنى: لا عاصم اليوم إلا الذي رحمنا، ف {من} في موضع رفع. وقيل: قوله: {إلا من رحم} استثناء منقطع، كأنه قال: لا عاصم اليوم موجود، لكن من رحم الله موجود", "qawaid": [], "tabi": ""}, {"taliq": 3225, "mi": 0, "aya": 43, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "2/ 55 - 56", "qawl": "", "nass": "قوله تعالى: {لا عاصم اليوم من أمر الله إلا من رحم} الاستثناء منقطع على أصح الوجوه في الآية؛ فإنه تعالى لما ذكر العاصم استدعى معصوما مفهوما من السياق، فكأنه قيل: لا معصوم اليوم من أمره إلا من رحمة، فإنه لما قال: {لا عاصم اليوم من أمر الله} بقي الذهن طالبا للمعصوم، فكأنه قيل: فمن الذي يعصم؟ فأجيب: بأنه لا يعصم إلا من رحمة الله. ودل هذا اللفظ باختصاره وجلالته وفصاحته علي نفي كل عاصم سواه، وعلى نفي كل معصوم سوى من?، فدل الاستثناء على أمرين: على المعصوم من هو؟ وعلى العاصم وهو ذو الرحمة. وهذا من أبلغ الكلام وأفصحه وأوجزه، ولا يلتفت إلى ما قيل في الآية بعد ذلك", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 3225, "mi": 0, "aya": 43, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "الثالث", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 3225, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "أورده", "kind": "نقل", "ref": "", "qawl": "الثالث", "nass": "قيل: إن عاصما بمعنى: معصوم، ك {ماء دافق} [الطارق: 6]، و {عيشة راضية} [الحاقة: 21]، والمعنى: لا معصوم إلا من رحمة الله. وهذا فاسد؛ لأن كل واحد من اسم الفاعل واسم المفعول موضوع لمعناه الخاص به، فلا يشاركه فيه الآخر، وليس الماء الدافق بمنى المدفوق، بل هو فاعل على بابه، كما يقال: ماء جار، ف {دافق} كجار، فما الموجب للتكلف البارد؟", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 3225, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "أورده", "kind": "نقل", "ref": "", "qawl": "", "nass": "والقول الثاني: أن {من رحم} فاعل لا مفعول، والمعنى: لا يعصم اليوم من أمر الله إلا الراحم، فهو استثناء فاعل من فاعل. وهذا وإن كان أقل تكلفا فهو أيضا ضعيف جدا، وجزالة الكلام وبلاغته تأباه بأول نظر", "qawaid": ["اللغة"], "tabi": ""}]}], "44": [{"id": 3227, "kinds": "تعليق،نقل", "text": "أشار ابنُ عطية (4/ 586) إلى ماجاء في هذا الأثر، وما رُوِي أنّ السفينة طافت بالكعبة أسبوعًا، ثم علّق قائلًا: «والقصص في هذه المعاني كثيرٌ صعب أن يستوفي، فأشرت منه إلى نُبَذ، ويدخله الاختلاف كما ترى في أمر الكعبة، والله أعلم كيف كان».", "mawaqif": [{"taliq": 3227, "mi": 0, "aya": 44, "alam": "ابن عطية", "fil": "أشار", "kind": "نقل", "ref": "4/ 586", "qawl": "", "nass": "والقصص في هذه المعاني كثير صعب أن يستوفي، فأشرت منه إلى نبذ، ويدخله الاختلاف كما ترى في أمر الكعبة، والله أعلم كيف كان", "qawaid": [], "tabi": ""}]}], "45": [{"id": 3228, "kinds": "خلاف،ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 586) في قوله: {ونادى نوح ربه} قولين، رجّح الأول منهما: «هذه جملة معطوفة على التي قبلها دون ترتيب، وذلك أنّ هذه القِصَّة كانت في أول ما ركب نوح في السفينة، ويظهر مِن كلام الطبري أنّ ذلك كان بعد غرق الابن، وهو محتمل، والأول أليق». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 3228, "mi": 0, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 586", "qawl": "", "nass": "هذه جملة معطوفة على التي قبلها دون ترتيب، وذلك أن هذه القصة كانت في أول ما ركب نوح في السفينة، ويظهر من كلام الطبري أن ذلك كان بعد غرق الابن، وهو محتمل، والأول أليق", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "46": [{"id": 3230, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 588) هذا الحديث مرفوعًا، ثم رجّح وقفَه على ابن عباس مِن جهةِ المعنى، فقال: «وهذا الحديث ليس بالمعروف، وإنما هو مِن كلام ابن عباس?، ويعضده شرف النبوة».", "mawaqif": [{"taliq": 3230, "mi": 0, "aya": 46, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 588", "qawl": "", "nass": "وهذا الحديث ليس بالمعروف، وإنما هو من كلام ابن عباس?، ويعضده شرف النبوة", "qawaid": [], "tabi": ""}]}, {"id": 3231, "kinds": "نقد،نقل", "text": "انتَقَد ابنُ عطية (4/ 590) ما جاء في هذا القول، فقال: «ورُوِي أنّ هذا الابن إنّما كان ربيبه، وهذا ضعيف».", "mawaqif": [{"taliq": 3231, "mi": 0, "aya": 46, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 590", "qawl": "", "nass": "وروي أن هذا الابن إنما كان ربيبه، وهذا ضعيف", "qawaid": [], "tabi": ""}]}, {"id": 3233, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 589 - 590 بتصرف) في الآية احتمالين، فقال: \" {فَلا تَسْئَلْنِ ما لَيْسَ لَكَ بِهِ عِلْمٌ} أي: إذ وعدتك، فاعلم يقينًا أنّه لا خلف في الوعد، فإذا رأيت ولدك لم يُحْمَل فكان الواجِبُ عليك أن تقِف وتعلم أنّ ذلك هو بحقٍّ واجب عند الله … ويحتمل قوله: {فَلا تَسْئَلْنِ ما لَيْسَ لَكَ بِهِ عِلْمٌ}، أي: لا تطلب مني أمرًا لا تعلم المصلحة فيه علم يقين. ونحا إلى هذا أبو علي الفارسي، وقال: إنّ {بِهِ} يجوز أن يتعلق بلفظة {عِلْمٌ} كما قال الشاعر:\nكان جزائي بالعصا أن أجلدا\nويجوز أن يكون {بِهِ} بمنزلة: فيه، فتتعلق الباء بالمستقر. واختلاف هذين الوجهين إنما هو لفظي، والمعنى في الآية واحد\".\nوانتقد (3/ 178) مستندًا إلى ظاهر لفظ الآية قول ابن زيد بقوله: «وهذا تأويل بشع، وليس في الألفاظ ما يقتضي أنّ نوحًا اعتقد هذا -وعياذًا بالله-، وغاية ما وقع لنوح عليه السلام أن رأى ترك ابنه معارِضًا للوعد فذكر به، ودعا بحسب الشفقة ليكشف له الوجه الذي استوجب به ابنه الترك في الغرقى».", "mawaqif": [{"taliq": 3233, "mi": 0, "aya": 46, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 589 - 590 بتصرف", "qawl": "ابن زيد", "nass": "وهذا تأويل بشع، وليس في الألفاظ ما يقتضي أن نوحا اعتقد هذا -وعياذا بالله-، وغاية ما وقع لنوح عليه السلام أن رأى ترك ابنه معارضا للوعد فذكر به، ودعا بحسب الشفقة ليكشف له الوجه الذي استوجب به ابنه الترك في الغرقى", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "51": [{"id": 3234, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (4/ 593) في قوله: {أفلا تعقلون} احتمالين، فقال: «وقوله: {أفَلا تَعْقِلُونَ} توقيفٌ على مجال القول بأنّ غير الفاطر إلهٌ، ويحتمل أن يريد: {أفَلا تَعْقِلُونَ} إذ لم أطلب عَرَضًا مِن أعراض الدنيا، إنِّي إنما أريد النفع لكم والدار الآخرة». ثم رجّح الأول لظهوره من اللفظ بقوله: «والأول أظهر».", "mawaqif": [{"taliq": 3234, "mi": 0, "aya": 51, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 593", "qawl": "", "nass": "وقوله: {أفلا تعقلون} توقيف على مجال القول بأن غير الفاطر إله، ويحتمل أن يريد: {أفلا تعقلون} إذ لم أطلب عرضا من أعراض الدنيا، إني إنما أريد النفع لكم والدار الآخرة", "qawaid": [], "tabi": ""}]}], "52": [{"id": 3235, "kinds": "غيره", "text": "قال ابنُ عطية (4/ 595): «وقوله: {ويَزِدْكُمْ قُوَّةً إلى قُوَّتِكُمْ} ظاهره العموم في جميع ما يُحْسِن اللهُ تعالى فيه إلى العباد. وقالت فرقة: كان الله تعالى قد حبس نسلَهم، فمعنى قوله: {ويَزِدْكُمْ قُوَّةً إلى قُوَّتِكُمْ} أي: الولد. ويحتمل أن خصَّ القوة بالذِّكْرِ إذ كانوا أقوى العوالم، فوُعِدوا بالزيادة فيما بهروا فيه، ثم نهاهم عن التولي عن الحق والإعراض عن أمر الله».", "mawaqif": [{"taliq": 3235, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "4/ 595", "qawl": "", "nass": "وقوله: {ويزدكم قوة إلى قوتكم} ظاهره العموم في جميع ما يحسن الله تعالى فيه إلى العباد. وقالت فرقة: كان الله تعالى قد حبس نسلهم، فمعنى قوله: {ويزدكم قوة إلى قوتكم} أي: الولد. ويحتمل أن خص القوة بالذكر إذ كانوا أقوى العوالم، فوعدوا بالزيادة فيما بهروا فيه، ثم نهاهم عن التولي عن الحق والإعراض عن أمر الله", "qawaid": [], "tabi": ""}]}], "56": [{"id": 3236, "kinds": "خلاف،توجيه،نقل", "text": "نقل ابنُ القيم (2/ 56 - 57) عن ابن الأنباري في قوله: {إن ربي على صراط مستقيم} قولين، فقال: «وقال ابن الأنباري: لَمّا قال: {هُوَ آخِذٌ بِناصِيَتِها} كان في معنى: لا يخرج مِن قبضته، وأنّه قاهِرٌ بعظيم سلطانه لكل دابة، فأتبع قوله: {إنَّ رَبِّي عَلى صِراطٍ مُسْتَقِيمٍ}. قال: وهذا نحو كلام العرب إذا وصَفُوا بحسن السيرة والعدل والإنصاف قالوا: فلان على طريقة حسنة، وليس ثمَّ طريق. ثم ذكر وجهًا آخر، فقال:» لَمّا ذكر أنّ سلطانه قد قهر كل دابة أتبع هذا قوله: {إنَّ رَبِّي عَلى صِراطٍ مُسْتَقِيمٍ}، أي: لا تخفى عليه مشيئتُه، ولا يعدل عنه هارِبٌ، فذكر الصراط المستقيم وهو يعني به: الطريق الذي لا يكون لأحد مسلك إلا عليه، كما قال: {إنَّ رَبَّكَ لَبِالمِرْصادِ} [الفجر: 14] «. ثم وجّه ابنُ القيم معنى الآية على القولين، فقال:» فعلى هذا القول الأول يكون المراد: أنّه في تصرُّفه في ملكه يتصرَّف بالعدل، ومجازاة المحسن بإحسانه والمسيء بإساءته، ولا يظلم مثقال ذرة، ولا يُعاقِب أحدًا بما لم يَجْنِه، ولا يهضمه ثوابَ ما عمله، ولا يحمل عليه ذنبَ غيره، ولا يأخذ أحدًا بجريرة أحد، ولا يُكَلِّف نفسًا ما لا تطيقه، فيكون من باب: له الملك وله الحمد، ومن باب: ماضٍ فِيَّ حُكْمُك عدلٌ فِيَّ قضاؤك، ومن باب: الحمد لله رب العالمين، أي: كما أنّه رب العالمين المتصرف فيهم بقدرته ومشيئته فهو المحمود على هذا التصرف، وله الحمد على جميعه. وعلى القول الثاني المراد به: التهديد والوعيد، وأنّ مصير العباد إليه، وطريقهم عليه، لا يفوته منهم أحد، كما قال تعالى: {قالَ هَذا صِراطٌ عَلَيَّ مُسْتَقِيمٌ} [الحجر: 41] \".", "mawaqif": [{"taliq": 3236, "mi": 0, "aya": 56, "alam": "ابن القيم", "fil": "نقل", "kind": "نقل", "ref": "2/ 56 - 57", "qawl": "", "nass": "وقال ابن الأنباري: لما قال: {هو آخذ بناصيتها} كان في معنى: لا يخرج من قبضته، وأنه قاهر بعظيم سلطانه لكل دابة، فأتبع قوله: {إن ربي على صراط مستقيم}. قال: وهذا نحو كلام العرب إذا وصفوا بحسن السيرة والعدل والإنصاف قالوا: فلان على طريقة حسنة، وليس ثم طريق. ثم ذكر وجها آخر، فقال:", "qawaid": [], "tabi": ""}, {"taliq": 3236, "mi": 0, "aya": 56, "alam": "ابن القيم", "fil": "وجه", "kind": "توجيه", "ref": "", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}]}], "59": [{"id": 3239, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (4/ 598) ما أفاده قولُ مقاتل في تفسير قوله: {وعصوا رسله} مِن أنه هود وحده، وذكر احتمالًا آخر أن يكون ذلك: «شنعة عليهم؛ وذلك أنّ في تكذيب رسولٍ واحدٍ تكذيبُ سائر الرسل وعصيانهم؛ إذ النبوات كلها مُجْمِعَةٌ على الإيمان بالله، والإقرار بربوبيته».", "mawaqif": [{"taliq": 3239, "mi": 0, "aya": 59, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 598", "qawl": "مقاتل في", "nass": "شنعة عليهم؛ وذلك أن في تكذيب رسول واحد تكذيب سائر الرسل وعصيانهم؛ إذ النبوات كلها مجمعة على الإيمان بالله، والإقرار بربوبيته", "qawaid": [], "tabi": ""}]}, {"id": 3240, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (12/ 452) غير قول قتادة.", "mawaqif": []}], "60": [{"id": 3241, "kinds": "غيره", "text": "قال ابنُ جرير (12/ 452): «وقيل: إنّ معنى {كفروا ربهم}: كفروا نعمة ربهم».", "mawaqif": [{"taliq": 3241, "mi": 0, "aya": 60, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "12/ 452", "qawl": "", "nass": "وقيل: إن معنى {كفروا ربهم}: كفروا نعمة ربهم", "qawaid": [], "tabi": ""}]}], "61": [{"id": 3242, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 453) في معنى: {واسْتَعْمَرَكُمْ فِيها} سوى قول مجاهد مِن طريق ابن أبي نجيح.", "mawaqif": []}], "62": [{"id": 3243, "kinds": "نقد،توجيه،بيان،نقل", "text": "ذكر ابنُ عطية (4/ 600) أنّ النقاش حكى عن بعضِهم في: {مَرْجُوًّا} أنّ معناه: حقيرًا، ثم انتَقَدَه مِن جهةِ اللغة، ووجَّهه بقوله: «فأمّا أن يكون لفظ {مَرْجُوًّا} بمعنى: حقير؛ فليس ذلك في كلام العرب، وإنما يتَّجه ذلك على جهة التفسير للمعنى، وذلك أنّ القصد بقولهم: {مَرْجُوًّا} يكون: لقد كنت فينا سهلًا مرامُك، قريبًا ردُّ أمرك، مِمَّن لا يُظَنُّ أن يَسْتَفْحِلَ مِن أمره مثل هذا، فمعنى مرجوّ: أي مرجوّ اطِّراحه وغلبته ونحو هذا، فيكون ذلك على جهة الاحتقار، فلذلك فُسِّر بحقير، ويشبه هذا المعنى قول أبي سفيان بن حرب: لقد أمِرَ أمْرُ ابن أبي كَبْشَة».", "mawaqif": [{"taliq": 3243, "mi": 0, "aya": 62, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 600", "qawl": "", "nass": "فأما أن يكون لفظ {مرجوا} بمعنى: حقير؛ فليس ذلك في كلام العرب، وإنما يتجه ذلك على جهة التفسير للمعنى، وذلك أن القصد بقولهم: {مرجوا} يكون: لقد كنت فينا سهلا مرامك، قريبا رد أمرك، ممن لا يظن أن يستفحل من أمره مثل هذا، فمعنى مرجو: أي مرجو اطراحه وغلبته ونحو هذا، فيكون ذلك على جهة الاحتقار، فلذلك فسر بحقير، ويشبه هذا المعنى قول أبي سفيان بن حرب: لقد أمر أمر ابن أبي كبشة", "qawaid": [], "tabi": ""}]}], "65": [{"id": 3244, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 604) نحو هذا الأثر، ثم انتقده بدلالة التاريخ قائلًا: «وفي هذا نظر، وخلافه في السِّيَر».", "mawaqif": [{"taliq": 3244, "mi": 0, "aya": 65, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 604", "qawl": "", "nass": "وفي هذا نظر، وخلافه في السير", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}], "69": [{"id": 3246, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 606 بتصرف) روايةً تَنُصُّ على «أنّ جبريل عليه السلام كان مختصًّا بإهلاك قرية لوط، وميكائيل عليه السلام مختصًّا بتبشير إبراهيم عليه السلام بإسحاق عليه السلام، وإسرافيل عليه السلام مختصًّا بإنجاء لوط عليه السلام ومَن معه». ثم استدرك عليها بقوله: «وهذه الآية تقضي باشتراكهم في البشارة بإسحاق عليه السلام».", "mawaqif": [{"taliq": 3246, "mi": 0, "aya": 69, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 606 بتصرف", "qawl": "", "nass": "أن جبريل عليه السلام كان مختصا بإهلاك قرية لوط، وميكائيل عليه السلام مختصا بتبشير إبراهيم عليه السلام بإسحاق عليه السلام، وإسرافيل عليه السلام مختصا بإنجاء لوط عليه السلام ومن معه", "qawaid": [], "tabi": ""}]}], "70": [{"id": 3248, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 610) أن امرأة إبراهيم عليه السلام سارة هي ابنة عمِّه، ونقل قولًا ولم ينسبه: أنها أخت لوط عليه السلام، واستدرك عليه بدلالة التاريخ بقوله: «وما أظنُّ ذلك إلا أخوة القرابة؛ لأن إبراهيم عليه السلام هو عمّ لوط عليه السلام فيما روي».", "mawaqif": [{"taliq": 3248, "mi": 0, "aya": 70, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 610", "qawl": "", "nass": "وما أظن ذلك إلا أخوة القرابة؛ لأن إبراهيم عليه السلام هو عم لوط عليه السلام فيما روي", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}], "72": [{"id": 3251, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (4/ 613) بعض الأقوال في سِنِّ سارة وإبراهيم عليه السلام ساعة هذه المقالة، واستدرك عليها، فقال: «ورُوِي أنّ سارة كانت وقت هذه المقالة مِن تسع وتسعين سنة. وقيل: من تسعين. قاله ابن إسحاق. وقيل: من ثمانين. وكذلك قيل في إبراهيم عليه السلام: إنه كان مائة وعشرين سنة. وقيل: مائة سنة. وغير ذلك مما يحتاج إلى سند».", "mawaqif": [{"taliq": 3251, "mi": 0, "aya": 72, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 613", "qawl": "", "nass": "وروي أن سارة كانت وقت هذه المقالة من تسع وتسعين سنة. وقيل: من تسعين. قاله ابن إسحاق. وقيل: من ثمانين. وكذلك قيل في إبراهيم عليه السلام: إنه كان مائة وعشرين سنة. وقيل: مائة سنة. وغير ذلك مما يحتاج إلى سند", "qawaid": [], "tabi": ""}]}], "74": [{"id": 3254, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 616) في صورة جدال إبراهيم عليه السلام أنها «كانت أن قال إبراهيم عليه السلام: إن كان فيهم مائة مؤمن أتعذبونهم؟ قالوا لا، قال: أفَتِسْعون؟ قالوا: لا، قال: أفثمانون؟ فلم يزل كذلك حتى بلغ خمسة ووقف عند ذلك، وقد عد في بيت لوط عليه السلام امرأته، فوجدهم ستة بها، فطمع في نجاتهم، ولم يشعر أنها من الكفرة، وكان ذلك من إبراهيم عليه السلام حرصًا على إيمان تلك الأُمَّة ونجاتها». ثم علَّق بقوله: «وقد كثر اختلاف رواة المفسرين لهذه الأعداد في قول إبراهيم عليه السلام، والمعنى كله نحو مما ذكرته». ونقل عن فرقة في قوله تعالى: {يُجادِلُنا فِي قَوْمِ لُوطٍ} أنّ المعنى: «يجادلنا في مؤمني قوم لوط». ثم انتقده قائلًا: «وهذا ضعيف».", "mawaqif": [{"taliq": 3254, "mi": 0, "aya": 74, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 616", "qawl": "", "nass": "كانت أن قال إبراهيم عليه السلام: إن كان فيهم مائة مؤمن أتعذبونهم؟ قالوا لا، قال: أفتسعون؟ قالوا: لا، قال: أفثمانون؟ فلم يزل كذلك حتى بلغ خمسة ووقف عند ذلك، وقد عد في بيت لوط عليه السلام امرأته، فوجدهم ستة بها، فطمع في نجاتهم، ولم يشعر أنها من الكفرة، وكان ذلك من إبراهيم عليه السلام حرصا على إيمان تلك الأمة ونجاتها", "qawaid": [], "tabi": ""}]}], "75": [{"id": 3255, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 493) في معنى: {أواَّهٌ مُنِيبٌ} سوى قول مجاهد بن جبر.", "mawaqif": []}, {"id": 3256, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (4/ 616) أنّ الأوّاه معناه: الخائِف الذي يُكْثِرُ التَّأَوُّهَ مِن خوف الله تعالى، ثم علَّق بقوله: «وللمفسرين في الأوّاه عباراتٌ، كلها ترجع إلى ما ذكرته، وتلزمه».", "mawaqif": [{"taliq": 3256, "mi": 0, "aya": 75, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 616", "qawl": "", "nass": "وللمفسرين في الأواه عبارات، كلها ترجع إلى ما ذكرته، وتلزمه", "qawaid": [], "tabi": ""}]}], "77": [{"id": 3257, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 495) في معنى: {سِيءَ بِهِمْ وضاقَ بِهِمْ ذَرْعًا} سوى قول ابن عباس.", "mawaqif": []}, {"id": 3258, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 498 - 499) في معنى: {وقالَ هَذا يَوْمٌ عَصِيبٌ} سوى قول ابن عباس، وقتادة، وابن إسحاق.", "mawaqif": []}], "78": [{"id": 3259, "kinds": "تعليق،نقل", "text": "ساق ابنُ عطية (4/ 619) هذا القول، ثم علَّق بقوله: «وذلك على أن كانت سُنَّتُهم جوازَ نكاح الكافر المؤمنة، أو على أنّ في ضمن كلامه أن يؤمنوا».", "mawaqif": [{"taliq": 3259, "mi": 0, "aya": 78, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "4/ 619", "qawl": "", "nass": "وذلك على أن كانت سنتهم جواز نكاح الكافر المؤمنة، أو على أن في ضمن كلامه أن يؤمنوا", "qawaid": [], "tabi": ""}]}, {"id": 3260, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (4/ 619) عن أبي عبيدة أنّ قول لوط عليه السلام: {هَؤُلاءِ بَناتِي هُنَّ أطْهَرُ لَكُمْ}: إنّما كان مُدافَعةً، ولم يُرِد إمضاءه، ثم انتقده مستندًا إلى الدلالة العقلية، فقال: «وهو ضعيف، وهذا كما يُقال لِمَن ينهى عن مال الغير: الخنزير أحلُّ لك مِن هذا. وهذا التَّنَطُّع ليس مِن كلام الأنبياء -صلى الله عليهم وسلم-».", "mawaqif": [{"taliq": 3260, "mi": 0, "aya": 78, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "4/ 619", "qawl": "لوط عليه", "nass": "وهو ضعيف، وهذا كما يقال لمن ينهى عن مال الغير: الخنزير أحل لك من هذا. وهذا التنطع ليس من كلام الأنبياء -صلى الله عليهم وسلم-", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}], "79": [{"id": 3261, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 507) في معنى: {ألَيْسَ مِنكُمْ رَجُلٌ رَشِيدٌ} سوى قول ابن إسحاق.", "mawaqif": []}], "80": [{"id": 3262, "kinds": "تعليق", "text": "علَّق ابنُ عطية (4/ 621) على هذا الحديث بقوله: «هذا نقدٌ لأن يلفظ لوط عليه السلام هذه الألفاظ، وإلا فحالة النبي صلى الله عليه وسلم وقت طُرِح سَلا الجزور، ومع أهل الطائف، وفي غير موطن تقتضي مقالة لوط، لكن محمدًا صلى الله عليه وسلم لم ينطق بشيءٍ من ذلك عزامة منه ونجدة، وإنما خشي لوط عليه السلام أن يُمْهِل الله أولئك العصاة حتى يعصوه في الأضياف كما أمهلهم فيما قبل ذلك مِن معاصيهم فيمن مضى، فتمنّى ركنًا من البشر يعاجلهم به، وهو يعلم أنّ الله تعالى مِن وراء عقابهم».", "mawaqif": [{"taliq": 3262, "mi": 0, "aya": 80, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "4/ 621", "qawl": "", "nass": "هذا نقد لأن يلفظ لوط عليه السلام هذه الألفاظ، وإلا فحالة النبي صلى الله عليه وسلم وقت طرح سلا الجزور، ومع أهل الطائف، وفي غير موطن تقتضي مقالة لوط، لكن محمدا صلى الله عليه وسلم لم ينطق بشيء من ذلك عزامة منه ونجدة، وإنما خشي لوط عليه السلام أن يمهل الله أولئك العصاة حتى يعصوه في الأضياف كما أمهلهم فيما قبل ذلك من معاصيهم فيمن مضى، فتمنى ركنا من البشر يعاجلهم به، وهو يعلم أن الله تعالى من وراء عقابهم", "qawaid": [], "tabi": ""}]}], "81": [{"id": 3264, "kinds": "ترجيح،نقد،نقل", "text": "استظهر ابنُ عطية (4/ 625) في {يلتفت} أنّها مِن التفات البصر، ثم نقل عن فرقة في قوله تعالى: {يَلْتَفِتْ}: أنها «من لَفَتَ الشيء يلفته إذا ثَناه ولواه، والمعنى: ولا يَتَثَبَّط». ثم استدرك على قولهم قائلًا: «وهذا شاذٌّ مع صِحَّته».", "mawaqif": [{"taliq": 3264, "mi": 0, "aya": 81, "alam": "ابن عطية", "fil": "استظهر", "kind": "ترجيح", "ref": "4/ 625", "qawl": "", "nass": "من لفت الشيء يلفته إذا ثناه ولواه، والمعنى: ولا يتثبط", "qawaid": [], "tabi": ""}]}], "84": [{"id": 3268, "kinds": "توجيه،نقل", "text": "نقل ابنُ عطية (4/ 628 - 629) قولًا بأنّ مدين: هي بقعة. ثم وجَّهه بقوله: «فالتقدير على هذا: وإلى أهل مدين. كما قال: {وسْئَلِ القَرْيَةَ} [يوسف: 82]».", "mawaqif": [{"taliq": 3268, "mi": 0, "aya": 84, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "4/ 628 - 629", "qawl": "", "nass": "فالتقدير على هذا: وإلى أهل مدين. كما قال: {وسئل القرية} [يوسف: 82]", "qawaid": [], "tabi": ""}]}, {"id": 3269, "kinds": "نقد،بيان،نقل", "text": "أفاد قولُ مقاتلٍ أمرين: الأول: أنّ مدين هو ولد إبراهيم الخليل عليه السلام، وهو ما ذكره ابنُ عطية (4/ 629) عن النقاش، ثم انتقده قائلًا: «وهذا بعيد». الثاني: أنّ شعيبًا عربيٌّ إذ هو مِن نسل إبراهيم، وهو ما انتقده ابنُ عطية (4/ 629) مستندًا لدلالة التاريخ، فقال: «فكيف يجتمع هذا وليس للعرب اتصالٌ بإبراهيم إلا مِن جهة إسماعيل فقط؟!».", "mawaqif": [{"taliq": 3269, "mi": 0, "aya": 84, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "4/ 629", "qawl": "", "nass": "وهذا بعيد", "qawaid": [], "tabi": ""}, {"taliq": 3269, "mi": 0, "aya": 84, "alam": "ابن عطية", "fil": "انتقده", "kind": "نقد", "ref": "4/ 629", "qawl": "", "nass": "فكيف يجتمع هذا وليس للعرب اتصال بإبراهيم إلا من جهة إسماعيل فقط؟!", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}], "86": [{"id": 3271, "kinds": "نقل", "text": "ذكر ابنُ جرير (12/ 541) هذا المعنى، ونسبه لابن عباس، ولم يذكر له سندًا، وذكر أنه رُوِي عن ابن عباس بإسناد غير مُرْتَضًى عند أهل النقل.", "mawaqif": [{"taliq": 3271, "mi": 0, "aya": 86, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 541", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "87": [{"id": 3274, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 545 - 546) في معنى: {أوْ أنْ نَفْعَلَ فِي أمْوالِنا ما نَشاءُ} سوى قول محمد بن كعب، وزيد بن أسلم، وابن زيد.", "mawaqif": []}, {"id": 3275, "kinds": "خلاف،توجيه،بيان،تعليق،نقل", "text": "نقل ابنُ عطية (5/ 6) قولًا ولم ينسبه: أنّ قولهم: {إنَّكَ لأَنْتَ الحَلِيمُ الرَّشِيدُ} «قالوه على جهة الحقيقة، وأنّه اعتقادهم فيه». ثم وجَّهه بقوله: «فكأنهم فنَّدوه، أي: أنت حليمٌ رشيدٌ فلا ينبغي لك أن تأمرنا بهذه الأوامر. ويشبه هذا المعنى قولُ اليهود مِن بني قريظة حين قال لهم رسول الله صلى الله عليه وسلم: «يا إخوة القِرَدَة»: يا محمد، ما عَلِمناك جهولًا». ثم علَّق بقوله: «والشبه بين الأمرين إنما هو بالمناسبة بين كلام شعيب عليه السلام وتلطفه، وبين ما بادر به محمد عليه الصلاة والسلام بني قريظة». ونقل قولين آخرين: الأول: إنما كانت ألفاظهم: إنك لأنت الجاهل السفيه. فكنّى الله عن ذلك. والثاني: أنّ المعنى: إنك لأنت الحليم الرشيد عند نفسك. ولم يعلِّق عليهما.", "mawaqif": [{"taliq": 3275, "mi": 0, "aya": 87, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 6", "qawl": "", "nass": "قالوه على جهة الحقيقة، وأنه اعتقادهم فيه", "qawaid": [], "tabi": ""}]}], "88": [{"id": 3276, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 549 - 550) في معنى: {وإلَيْهِ أُنِيبُ} سوى قول مجاهد.", "mawaqif": []}], "89": [{"id": 3277, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 551) في معنى: {لا يَجْرِمَنَّكُمْ شِقاقِي} سوى قول قتادة، وابن جريج.", "mawaqif": []}, {"id": 3278, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 8) أنّ قصة قوم لوط كانت أقربَ القصص عهدًا بقصة قوم شعيب، ثم أورد احتمالًا آخر، فقال: «وقد يحتمل أن يريد: وما منازل قوم لوط منكم ببعيد. فكأنه قال: وما قوم لوط منكم ببعيد بالمسافة. ويتضمن هذا القول ضرب المثل لهم بقوم لوط».", "mawaqif": [{"taliq": 3278, "mi": 0, "aya": 89, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 8", "qawl": "", "nass": "وقد يحتمل أن يريد: وما منازل قوم لوط منكم ببعيد. فكأنه قال: وما قوم لوط منكم ببعيد بالمسافة. ويتضمن هذا القول ضرب المثل لهم بقوم لوط", "qawaid": [], "tabi": ""}]}], "91": [{"id": 3279, "kinds": "ترجيح،نقد،نقل", "text": "نقل ابنُ عطية (5/ 9) عن سعيد بن جبير، وشريك القاضي «في قولهم: {ضَعِيفًا}: أنّه كان ضرير البصر أعمى … وقيل: كان ناحل البدن». ثم انتقده مستندًا إلى الدلالة العقلية قائلًا: «وهذا كله ضعيف ولا تقوم عليه حجة بضعف بصره أو بدنه». واختار في «قولهم: {ضَعِيفًا} أنّه: ضعيف الانتصار والقدرة، وأنّ رهطه الكفرة كانوا يراعون فيه».", "mawaqif": [{"taliq": 3279, "mi": 0, "aya": 91, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "5/ 9", "qawl": "", "nass": "في قولهم: {ضعيفا}: أنه كان ضرير البصر أعمى … وقيل: كان ناحل البدن", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}], "106": [{"id": 3283, "kinds": "ترجيح،بيان،تعليق،نقل", "text": "حكى ابنُ عطية (5/ 19) بعض الأقوال المثبتة في الآثار هنا في التفريق بين معنى: الزفير والشهيق، ثم نقل قولًا آخر أنّ: «الزفير مأخوذ مِن الزَّفْر وهو الشدة، والشهيق مِن قولهم: جبل شاهق، أي: عالٍ». وعلَّق عليه بقوله: «فهما على هذا المعنى واحد، أو متقارب». ثم رجَّح قول أبي العالية مستندًا إلى واقع الحال، فقال: «والظاهر ما قال أبو العالية؛ فإنّ الزَّفرة هي التي يعظم معها الصدر والجوف، والشهقة هي الوقعة الأخيرة مِن الصوت المندفعة معها النَّفَس أحيانًا، فقد يشهق المحتضر، ويشهق المغشي عليه».", "mawaqif": [{"taliq": 3283, "mi": 0, "aya": 106, "alam": "ابن عطية", "fil": "حكى", "kind": "نقل", "ref": "5/ 19", "qawl": "", "nass": "الزفير مأخوذ من الزفر وهو الشدة، والشهيق من قولهم: جبل شاهق، أي: عال", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}], "107": [{"id": 3284, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 579) في معنى: {خالِدِينَ فِيها ما دامَتِ السَّماواتُ والأَرْضُ} سوى قول ابن زيد.", "mawaqif": []}], "108": [{"id": 3287, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 588 - 590) في معنى: {عَطاءً غَيْرَ مَجْذُوذٍ} سوى قول ابن عباس، وما في معناه.", "mawaqif": []}], "109": [{"id": 3288, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 591 - 592) في معنى: {وإنّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍ} سوى قول ابن عباس، وابن زيد.", "mawaqif": []}], "112": [{"id": 3290, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 27) أنّ معنى قوله: {ولا تَطْغَوْا}: ولا تتجاوزوا حدود الله تعالى، ثم قال: «والطغيان: تجاوز الحد، ومنه قوله: {طَغى الماءُ} [الحاقة: 11]، وقوله في فرعون: {إنَّهُ طَغى} [طه: 24، 43، النازعات: 17]». ونقل أنه قيل: إن المعنى: ولا تطغينكم النِّعَم. ثم علَّق بقوله: «وهذا كالأول».", "mawaqif": [{"taliq": 3290, "mi": 0, "aya": 112, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 27", "qawl": "", "nass": "والطغيان: تجاوز الحد، ومنه قوله: {طغى الماء} [الحاقة: 11]، وقوله في فرعون: {إنه طغى} [طه: 24، 43، النازعات: 17]", "qawaid": [], "tabi": ""}]}, {"id": 3291, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (5/ 26 - 27) رواية نحو هذا المعنى، ثم علَّق عليها بقوله: «والتأويل المشهور في قوله صلى الله عليه وسلم: «شَيَّبَتْنِي هود وأخواتها» أنها إشارة إلى ما فيها مِمّا حلَّ بالأمم السابقة، فكأنّ حَذَرَه على هذه الأمة مثلَ ذلك شيَّبه عليه الصلاة والسلام».", "mawaqif": [{"taliq": 3291, "mi": 0, "aya": 112, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 26 - 27", "qawl": "", "nass": "والتأويل المشهور في قوله صلى الله عليه وسلم: «شيبتني هود وأخواتها", "qawaid": [], "tabi": ""}]}], "113": [{"id": 3292, "kinds": "تعليق", "text": "علَّق ابنُ كثير (7/ 476) على قول ابن عباس بقوله: «وهذا القول حسن، أي: لا تستعينوا بالظَّلمة؛ فتكونوا كأنّكم قد رضيتم بباقي صنيعهم».", "mawaqif": [{"taliq": 3292, "mi": 0, "aya": 113, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "7/ 476", "qawl": "ابن عباس", "nass": "وهذا القول حسن، أي: لا تستعينوا بالظلمة؛ فتكونوا كأنكم قد رضيتم بباقي صنيعهم", "qawaid": [], "tabi": ""}]}], "114": [{"id": 3295, "kinds": "نقل", "text": "ذكر ابنُ عطية (5/ 31) أنّ قوله: {ذلك} يحتمل احتمالات: الأول: أن يكون إشارة إلى الصلوات، ووصفها بـ {ذِكْرى}، أي: هي سبب ذِكْرٍ، وموضع ذكرى. الثاني: أن يكون إشارة إلى الإخبار بأنّ الحسنات يذهبن السيئات، فتكون هذه الذكرى تحض على الحسنات. الثالث: أن تكون الإشارة إلى جميع ما تقدم من الأوامر والنواهي في هذه السورة.", "mawaqif": [{"taliq": 3295, "mi": 0, "aya": 114, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "5/ 31", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "120": [{"id": 3301, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (12/ 643) في معنى: {وكُلا نَقُصُّ عَلَيْكَ مِن أنْباءِ الرُّسُلِ ما نُثَبِّتُ بِهِ فُؤادَكَ} سوى قول ابن جريج.", "mawaqif": []}]}, "athar": {"35328": {"num": 35328, "aya": 20, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- في قوله: {معجزين}، قال: مُسابِقِين."}, "35329": {"num": 35329, "aya": 20, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: هارِبين."}, "35332": {"num": 35332, "aya": 20, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {يضاعف لهم العذاب}، أي: عذاب الدنيا، والآخرة."}, "35333": {"num": 35333, "aya": 20, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قال: أخبر الله سبحانه أنّه حال بين أهل الشرك وبين طاعته في الدنيا والآخرة؛ أمّا في الدنيا فإنه قال: {ما كانوا يستطيعون السمع} وهي طاعته، {وما كانوا يبصرون}. وأما في الآخرة فإنه قال: {لا يستطيعون* خاشعة} [القلم: 42 - 43]."}, "35334": {"num": 35334, "aya": 20, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {ما كانوا يستطيعون السمع وما كانوا يبصرون}، قال: ما كانوا يستطيعون أن يسمعوا خيرًا فينتفعوا به، ولا يُبْصِروا خيرًا فيأخذوا به."}, "35342": {"num": 35342, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وأخبَتُوا}، قال: خافوا."}, "35343": {"num": 35343, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قال: الإخبات: الإنابة."}, "35344": {"num": 35344, "aya": 23, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- {وأخبتوا إلى ربهم}، قال: اطْمَأَنُّوا."}, "35345": {"num": 35345, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- قال: الإخبات: الخُشُوع والتَّواضع."}, "35346": {"num": 35346, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وأخبتوا إلى ربهم}، يقول: وأنابوا إلى ربهم."}, "35348": {"num": 35348, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق ابن إسحاق بسنده- قوله: {أولئك أصحاب الجنة} أي: مَن آمَنَ بما كفرتم، وعَمِل بما تركتم مِن دينه فلهم الجنة خالدين فيها، {هم فيها خالدون} فلهم الجنة خالدين فيها، يخبرهم أنّ الثواب بالخير [والشَّرِّ] مُقِيمٌ على أهله أبدًا لا انقطاع له."}, "36574": {"num": 36574, "aya": 114, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق زِرٍّ- قال: إنّ الصلوات مِن الحسنات، وكفّارة ما بين الأولى إلى العصر صلاة العصر، وكفّارة ما بين صلاة العصر إلى المغرب صلاة المغرب، وكفّارة ما بين المغرب إلى العَتَمَة صلاة العَتَمَة، ثم يأوي المسلمُ إلى فراشه لا ذَنبَ له ما اجْتُنِبَتِ الكبائر. ثم قرأ: {إن الحسنات يذهبن السيئات}."}, "36541": {"num": 36541, "aya": 114, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم -من طريق عبد الرحمن بن مغراء، عن جُوَيْبِر- في قوله: {أقم الصلاة طرفي النهار}، يقول: الفجر، والظهر، والعصر."}, "36542": {"num": 36542, "aya": 114, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مُزاحِم -من طريق عبدة بن سليمان، عن جُوَيْبِر- في قوله: {أقم الصلاة طرفي النهار}، قال: صلاة الفجر، والعصر."}, "35889": {"num": 35889, "aya": 71, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن جريج- {وامرأته قائمة}، قال: في خِدمة أضياف إبراهيم."}, "35896": {"num": 35896, "aya": 71, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {فضحكت}، قال: حاضَتْ، وكانت ابنةَ بِضعٍ وتسعين سنة، وكان إبراهيمُ ابنَ مائة سنة."}, "36646": {"num": 36646, "aya": 119, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الحكم بن أبان، عن عكرمة-: {ولذلك} للرحمة {خلقهم}، ولم يخلقهم للعذاب."}, "35898": {"num": 35898, "aya": 71, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- قال: لَمّا أوجس إبراهيمُ خِيفَةً في نفسه حدَّثوه عند ذلك بما جاءوا فيه، فضحِكت امرأته تَعَجُّبًا مِمّا فيه قوم لوط مِن الغفلة، ومِمّا أتاهم مِن العذاب."}, "35899": {"num": 35899, "aya": 71, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- قال: لَمّا ضَحِكَتْ سارةُ وقالت: عَجَبًا لأضيافِنا هؤلاء، إنّا نخدمُهم بأنفسنا تَكرِمَةً لهم، وهم لا يأكلون طعامنا! قال لها جبريل: أبشِري بولد اسمه: إسحاق، ومن وراء إسحاق يعقوب. فضربت جبهتها عَجَبًا، فذلك قوله: {فصكت وجهها} [الذاريات: 29]، وقالت: {ءألد وأنا عجوز وهذا بعلي شيخًا إن هذا لشيء عجيب* قالوا أتعجبين من أمر الله رحمت الله وبركاته عليكم أهل البيت إنه حميد مجيد}. قالت سارة: ما آيةُ ذلك؟ فأخذ بيده عُودًا يابِسًا، فلواه بين أصابعه، فاهْتَزَّ أخضر، فقال إبراهيم: هو لله إذن ذبيحًا."}, "35900": {"num": 35900, "aya": 71, "qail": "محمد بن قيس", "tabaqa": "", "bab": "تفسير الآية", "text": "عن محمد بن قيس -من طريق أبي معشر- في قوله: {وامرأته قائمة فضحكت}، قال: لَمّا جاءت الملائكة ظَنَّت أنهم يريدون أن يعملوا كما يعمل قومُ لوط."}, "35901": {"num": 35901, "aya": 71, "qail": "محمد بن السائب الكلبي", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن محمد بن السائب الكلبي -من طريق معمر- {فضحكت}، قال: ضَحِكَت حين راعَوْا إبراهيم مِمّا رَأَتْ مِن الرَّوْع بإبراهيم."}, "36545": {"num": 36545, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق قُرَّة بن خالد- في قول الله: {طَرَفَيِ النَّهارِ}: مِن صلاة الغداة، إلى صلاة الفجر."}, "36575": {"num": 36575, "aya": 114, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق علقمة- في قوله: {إن الحسنات يذهبن السيئات}، قال: الصلوات الخمس."}, "36647": {"num": 36647, "aya": 119, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {ولذلك خلقهم}، قال: خلقهم فريقين؛ فريقًا يُرحَمُ فلا يَختلف، وفريقًا لا يُرحم يختلف، وذلك قوله: {فمنهم شقي وسعيد} [هود: 105]."}, "36418": {"num": 36418, "aya": 107, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق المسيب، عن رجل حدَّثه- {خالدين فيها ما دامت السموات والأرض}: لا يموتون، ولا هم منها يخرجون، ما دامت السماوات والأرض."}, "36419": {"num": 36419, "aya": 107, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: ما دامت السماوات والأرض مِن ابتدائها إلى وقت فنائِها."}, "36420": {"num": 36420, "aya": 107, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- في قوله: {ما دامت السماوات والأرض}، قال: لكل جَنَّةٍ سماءٌ وأرض."}, "35909": {"num": 35909, "aya": 71, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد بن بشير- في قوله: {فبشرناها بإسحاق} بابنها."}, "35910": {"num": 35910, "aya": 71, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "قال إسماعيل السُّدِّيّ -من طريق أسباط-: لَمّا ضحِكت سارة وقالت: عجبًا لأضيافنا هؤلاء، إنّا نخدمهم بأنفسنا تكرِمةً لهم، وهم لا يأكلون طعامنا! قال لها جبريل: أبشِري بولدٍ اسمه: إسحاق، ومن وراء إسحاق يعقوب. فضربت وجهها عجبًا، فذلك قوله: {فَصَكَّتْ وجْهَها} [الذاريات: 29]."}, "35911": {"num": 35911, "aya": 71, "qail": "محمد بن السائب الكلبي", "tabaqa": "تابع التابعين", "bab": "", "text": "قال محمد بن السائب الكلبي: {فضحكت}، لَمّا رأت سارةُ فَرَق إبراهيم عَجِبَتْ مِن فَرَقِه، فضَحِكَت وهي لا تدري مَنِ القوم، فبشروها بإسحاق، وقالوا: نرجع إليك عامًا قابِلًا وقد ولدت لإبراهيم غلامًا اسمه: إسحاق، ويكون مِن وراء إسحاق يعقوب. أي: من بعد إسحاق."}, "36422": {"num": 36422, "aya": 107, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "قال الضَّحّاك بن مُزاحِم: ما دامت سماوات الجنة والنار، وأرضهما."}, "36427": {"num": 36427, "aya": 107, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {خالدين فيها ما دامت السموات والأرض}، قال: ما دامت الأرض أرضًا، والسماء سماءً."}, "36548": {"num": 36548, "aya": 114, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {أقم الصلاة طرفي النهار}، يعني: صلاة العصر، والصبح."}, "36433": {"num": 36433, "aya": 107, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق المسيب، عن رجل حدَّثه- {إلا ما شاء ربك}، قال: استثناء الله. قال: يأمر النارَ أن تأكلهم. قال: وقال ابن مسعود: لَيَأْتِيَنَّ على جهنمَ زمانٌ تَخْفِقُ أبوابُها، ليس فيها أحد، وذلك بعد ما يلبثون فيها أحقابًا."}, "36434": {"num": 36434, "aya": 107, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي رَوْق، عن الضَّحّاك- قال: هاتان مِن المُخَبَّآت؛ قول الله: {فمنهم شقي وسعيد}، و {يوم يجمع الله الرسل فيقول ماذا أُجِبتُم قالوا لا علم لنا} [المائدة: 109]. أمّا قوله: {فمنهم شقي وسعيد} فهم قومٌ مِن أهل الكبائر مِن أهل هذه القبلة، يُعَذِّبهم اللهُ بالنار ما شاء بذنوبهم، ثم يأذن في الشفاعة لهم، فيشفَع لهم المؤمنون، فيُخرجُهم مِن النار، فيدخلهم الجنة، فسمّاهم أشقياء حين عذبهم في النار، {فأما الذين شقوا ففي النار لهم فيها زفير وشهيق* خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك} حين أذِن في الشفاعة لهم، وأخرجهم من النار، وأدخلهم الجنة، وهم هم."}, "36651": {"num": 36651, "aya": 119, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق ثابت- {ولذلك خلقهم}، قال: للرِّحمة."}, "36436": {"num": 36436, "aya": 107, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق مَعْمَر- {إلا ما شاء ربك}، قال: إلّا ما اسْتَثْنى مِن أهل القِبْلَة."}, "36437": {"num": 36437, "aya": 107, "qail": "خالد بن معدان", "tabaqa": "تابعي", "bab": "", "text": "عن خالد بن معدان -من طريق عامر بن جَشِيبٍ- في قوله: {إلا ما شاء ربك}، قال: إنّها في أهل التوحيد مِن أهل القِبْلة."}, "36438": {"num": 36438, "aya": 107, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق بيان- قال: جهنمُ أسرعُ الدارين عمرانًا، وأسرعهما خَرابًا."}, "35533": {"num": 35533, "aya": 40, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- قال: حُدِّثتُ: أنّ نوحًا حمل معه بنيه الثلاثة، وثلاث نسوة لبنيه، وأصاب حامٌ زوجتَه في السفينة، فدعا نوحٌ أن تُغَيَّرَ نطفته، فجاء بالسودان."}, "36442": {"num": 36442, "aya": 107, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق أبي هلال- أنّه تلا هذه الآية: {فَأَمّا الَّذِينَ شَقُوا فَفِي النّارِ لَهُمْ فِيها زَفِيرٌ وشَهِيقٌ}. فقال عند ذلك: حدثنا أنس بن مالك، عن النبي صلى الله عليه وسلم قال: «يخرج قوم من النار». قال قتادة: ولا نقول كما يقول أهل حروراء."}, "36443": {"num": 36443, "aya": 107, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {فأما الذين شقوا ففي النار لهم فيها زفير وشهيق خالدين فيها ما دامت السموات والأرض إلا ما شاء ربك}، قال: الله أعلم بِثنيته. وقد ذُكِر لنا: أنّ ناسًا يُصِيبهم سَفْعٌ مِن النار بذنوب أصابوها، ثم يدخلهم الجنة."}, "36576": {"num": 36576, "aya": 114, "qail": "سلمان الفارسي", "tabaqa": "صحابي", "bab": "", "text": "عن سلمان الفارسي -من طريق أبي عثمان- قال: والِّذي نفسي بيده، إنّ الحسنات التي يمحو اللهُ بِهِنَّ السيِّئات كما يغسل الماءُ الدَّرَنَ: الصلواتُ الخمسُ."}, "35534": {"num": 35534, "aya": 40, "qail": "محمد بن إسحاق", "tabaqa": "تابع التابعين", "bab": "", "text": "قال محمد بن إسحاق: كانوا عشرة سوى نسائهم: نوح، وبنوه حام وسام ويافث، وستة أناس مِمَّن كان آمَن معه، وأزواجهم جميعًا."}, "36552": {"num": 36552, "aya": 114, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {أقم الصلاة طرفي النهار}: الصبح، والمغرب."}, "36449": {"num": 36449, "aya": 107, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {خالِدِينَ فِيها ما دامَتِ السَّمَواتُ والأَرْضُ إلّا ما شاءَ رَبُّكَ} فقرأ حتى بلغ: {عَطاءً غَيْرَ مَجْذُوذٍ}: فأخبرنا بالذي يشاءُ لأهل الجنة، فقال: {عَطاءً غَيْرَ مَجْذُوذٍ}، ولم يُخْبِرنا بالذي يشاء لأهل النار."}, "36553": {"num": 36553, "aya": 114, "qail": "الحسن", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن: {وزلفًا من الليل}، قال: قال رسول الله صلى الله عليه وسلم: «هما زُلْفَتا الليل؛ المغرب، والعشاء»."}, "36554": {"num": 36554, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وزلفًا من الليل}، قال: صلاة العَتَمَة."}, "36555": {"num": 36555, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عبيد الله بن أبي يزيد-: أنّه كان يَسْتَحِبُّ تأخير العشاء، ويقرأ: {وزلفًا من الليل}."}, "36464": {"num": 36464, "aya": 108, "qail": "أبي سنان", "tabaqa": "", "bab": "", "text": "عن أبي سنان -من طريق أبي مالك- قال: ومشيئته خلودُهم فيها، استثنى في أهل التوحيد، ثُمَّ أتبعها قال: {عطاء غير مجذوذ}."}, "36556": {"num": 36556, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- قوله: {وزلفا من الليل}، يقول: صلاة القيام."}, "36557": {"num": 36557, "aya": 114, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {وزلفًا من الليل}، قال: المغرب، والعشاء."}, "36558": {"num": 36558, "aya": 114, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {وزلفًا من الليل}، قال: ساعة بعد ساعة. يعني: صلاة العشاء الآخرة."}, "36559": {"num": 36559, "aya": 114, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- {وزلفا من الليل}، قال: ساعةً مِن الليل: صلاة العَتَمَة."}, "36560": {"num": 36560, "aya": 114, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مُزاحِم -من طريق جُوَيْبِر- في قوله: {وزلفا من الليل}، قال: المغرب، والعشاء."}, "36561": {"num": 36561, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق المبارك بن فضالة- قال: {وزلفا من الليل}: المغرب، والعشاء."}, "35469": {"num": 35469, "aya": 40, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب، قال: فار التَّنُّور مِن مسجد الكوفة، مِن قِبَلِ أبواب كِندة."}, "35471": {"num": 35471, "aya": 40, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق الشعبي- قال: والَّذِي فَلَق الحبَّة وبَرَأ النسمة، إنّ مسجدكم هذا لرابِع أربعة مِن مساجد المسلمين، ولَرَكعتان فيه أحبُّ إلى الله مِن عشر فيما سواه، إلا المسجد الحرام، ومسجد رسول الله صلى الله عليه وسلم بالمدينة، وإنّ مِن جانبه الأيمن مُستَقبَل القبلة فار التنُّور."}, "35472": {"num": 35472, "aya": 40, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق أبي جحيفة- {وفار التنور}، قال: طلع الفجر، قيل له: إذا طلع الفجر فاركب أنت وأصحابُك."}, "35473": {"num": 35473, "aya": 40, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق أبي جحيفة- {وفار التنور}، قال: تنور الصُّبْح."}, "35474": {"num": 35474, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وفار التنور}: نَبَع الماء."}, "35475": {"num": 35475, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- {وفار التنور}، قال: إذا رأيت تَنُّورَ أهلِك يخرج منه الماء؛ فإنّه هلاك قومك."}, "35476": {"num": 35476, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: كان بين دعوة نوحٍ عليه السلام وبين هلاك قومه ثلاثمائة سنة، وكان فار التَّنُّور بالهند، وطافت سفينةُ نوح عليه السلام بالبيت أُسبُوعًا."}, "35477": {"num": 35477, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {وفار التنور}، قال: العين التي بالجزيرة؛ عين الوردة."}, "35478": {"num": 35478, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- قال: التَّنُّور: وجه الأرض. قيل له: إذا رأيت الماء على وجْه الأرض فاركب أنت ومَن معك. والعرب تسمي وجه الأرض: تنور الأرض."}, "35479": {"num": 35479, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- قال: كان تَنُّورًا مِن حجارة، كانت حواء تَخْبُزُ فيه، فصار إلى نوح عليه السلام، فقيل لنوح: إذا رأيت الماء يفور من التَّنُّور فاركب أنت وأصحابُك."}, "36562": {"num": 36562, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي رجاء- في قوله: {وزلفًا من الليل}، قال: هما زُلْفَتان؛ صلاة المغرب، وصلاة العشاء."}, "36563": {"num": 36563, "aya": 114, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة- من طريق سعيد -: {وزلفا من الليل}. قال: يعني صلاة المغرب وصلاة العشاء."}, "35483": {"num": 35483, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "ومجاهد بن جبر، نحو ذلك."}, "36564": {"num": 36564, "aya": 114, "qail": "محمد بن كعب القرظي", "tabaqa": "تابعي", "bab": "", "text": "عن محمد بن كعب القرظي- من طريق أفلح بن سعيد - يقول: {زلفا من الليل}: يعني صلاة المغرب والعشاء."}, "35485": {"num": 35485, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- {وفار التنور}، قال: انبَجَسَ الماءُ منه؛ آيةٌ أن يركب بأهله ومَن معه في السفينة."}, "35486": {"num": 35486, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- قال: نَبَعَ الماءُ في التَّنُّور، فعَلِمَتْ به امرأتُه، فأَخْبَرَتْهُ. قال: وكان ذلك في ناحية الكوفة."}, "35487": {"num": 35487, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قوله: {وفار التنور} الماء منه."}, "35488": {"num": 35488, "aya": 40, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق العوام- {وفار التنور}، قال: التنور: وجه الأرض. قال: قيل له: إذا رأيت الماء على وجه الأرض فاركب أنت ومَنِ اتَّبعك. قال: والعربُ تُسَمِّي وجه الأرض: تَنُّور الأرض."}, "35489": {"num": 35489, "aya": 40, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- يقول في قوله: {وفار التنور}: كان آيةً لنوح: إذا خرج منه الماءُ فقد أتى الناسَ الهلاكُ والغرقُ. وكان ابن عباس يقول في معنى {فار}: نَبَع."}, "35494": {"num": 35494, "aya": 40, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: {التنور} الباب الذي يجتمع فيه ماءُ السفينة، ففار منه الماءُ والسفينةُ على الأرض، فكان ذلك علامةً لإهلاك القوم."}, "35495": {"num": 35495, "aya": 40, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي محمد- قال: كان تَنُّورًا مِن حجارة، كان لحواء حتى صار إلى نوح عليه السلام، فقيل له: إذا رأيتَ الماء يفور مِن التَّنُّور فاركب أنت وأصحابُك."}, "35497": {"num": 35497, "aya": 40, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وفار التنور}، قال: أعلى الأرضِ وأشرفُها، وكان عَلَمًا فيما بين نوح وبين ربِّه عز وجل."}, "36525": {"num": 36525, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، قال: جاء رجلٌ إلى النَّبِيِّ صلى الله عليه وسلم، فقال: إنّ امرأةً جاءت تُبايِعُني، فأدْخَلتُها، فأصبتُ منها ما دُونَ الجِماع. فقال: «لعلها مُغِيبَة في سبيل الله». قال: أجل. فنَزَل القرآن: {وأقم الصلاة طرفي النهار} الآية. فقال الرجل: ألي خاصَّة أم للمؤمنين عامَّة؟ فضرب عمر في صدره، وقال: لا، ولا نُعمَة عَيْنٍ، ولكن للمؤمنين عامَّة. فضحِك رسولُ الله صلى الله عليه وسلم، وقال: «صدق عمر، هي للمؤمنين عامَّة»."}, "36526": {"num": 36526, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، قال: جاء رجل إلى النبيِّ صلى الله عليه وسلم، فقال: إنِّي نِلْتُ مِن امرأةٍ ما دُونَ نَفْسِها. فأنزل الله: {وأقم الصلاة} الآية."}, "36527": {"num": 36527, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس: أنّ رجلًا كان يُحِبُّ امرأةً، فاستأذن النبيَّ صلى الله عليه وسلم في حاجةٍ، فأَذِن له، فانطلق في يوم مَطِير، فإذا هو بالمرأة على غديرِ ماءٍ تَغْتَسِلُ، فلمّا جلس منها مجلس الرجل مِن المرأة ذهب يُحَرِّكُ ذَكَرَهُ، فإذا هو كأنّه هُدْبَةٌ، فنَدِم، فأتى النَّبِيَّ صلى الله عليه وسلم، فذكر ذلك له، فقال له النبيُّ صلى الله عليه وسلم: «صَلِّ أربعَ ركعات». فأنزل الله: {وأقم الصلاة طرفي النهار} الآية."}, "35504": {"num": 35504, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {قلنا احمل فيها من كل زوجين اثنين}، قال: في كلام العرب يقولون للذكر والأنثى: زوجان."}, "35505": {"num": 35505, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {من كل زوجين اثنين}، قال: فالواحد زوج، والزوجين ذكرٌ وأُنثى مِن كل صِنفٍ."}, "35506": {"num": 35506, "aya": 40, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد بن سليمان- يقول في قوله: {من كل زوجين اثنين}: يعني بالزوجين اثنين: ذكرًا أو أنثى."}, "36528": {"num": 36528, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس: أن نبهان التمّار أتته امرأة حسناء جميلة تبتاع منه تمرًا، فضرب على عَجِيزتها ثم ندِم، فأتى النبي صلى الله عليه وسلم فقال: «إياك أن تكون امرأة غازٍ في سبيل الله»، فذهب يبكي ويصوم ويقوم، فأنزل الله تعالى: {والَّذِينَ إذا فَعَلُوا فاحِشَةً أوْ ظَلَمُوا أنْفُسَهُمْ ذَكَرُوا اللَّهَ} الآية [آل عمران: 135]، فأخبره، فحمدالله وقال: يا رسول الله هذه توبتي قبلت، فكيف لي بأن يتقبل شكري؟ فنزلت: {وأَقِمِ الصَّلاةَ طَرَفَيِ النَّهارِ} الآية."}, "35508": {"num": 35508, "aya": 40, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: لم يحمل نوحٌ في السفينة إلا ما يَلِد ويبيض، فأمّا ما يَتَوَلَّد مِن الطين مِن حشرات الأرض كالبَقِّ والبعوض فلم يحمل منها شيئًا."}, "35509": {"num": 35509, "aya": 40, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {قلنا احمل فيها من كل زوجين اثنين}، يقول: مِن كل صِنفٍ اثنين."}, "36529": {"num": 36529, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس في قوله: {وأَقِمِ الصَّلاةَ طَرَفَيِ النَّهارِ} قال: نزلت في عمرو بن غزِيِّة، وكان يبيع التمر، فأتته امرأة تبتاع تمرا فأعجبته. الحديث."}, "36568": {"num": 36568, "aya": 114, "qail": "سلمان", "tabaqa": "صحابي", "bab": "", "text": "عن سلمان: أنّ رسول الله صلى الله عليه وسلم أخذ غُصنًا يابسًا مِن شجرة، فهزَّه حتى تَحاتَّ ورقُه، ثم قال: «إنّ المسلم إذا تَوَضَّأ فأحسن الوضوء، ثم صلّى الصلوات الخمس؛ تحاتَّت خطاياه كما يَتَحاتُّ هذا الوَرَق». ثم تلا هذه الآية: {وأقم الصلاة طرفي النهار}."}, "36569": {"num": 36569, "aya": 114, "qail": "أبي مالك الأشعري", "tabaqa": "صحابي", "bab": "", "text": "عن أبي مالك الأشعري، قال: قال رسول الله صلى الله عليه وسلم: «جُعِلَت الصلواتُ كفّارات لِما بَيْنَهُنَّ؛ فإن الله تعالى قال: {إن الحسنات يذهبن السيئات}»."}, "35514": {"num": 35514, "aya": 40, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحاك بن مُزاحِم -من طريق أبي رَوْق- في قوله: {وأهلك إلا من سبق عليه القول}، قال: ابنه غَرِق فيمَن غَرِق."}, "35515": {"num": 35515, "aya": 40, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد بن بشير- قوله: {وأهلك إلا من سبق عليه القول} إنّه مُغْرَق."}, "36540": {"num": 36540, "aya": 114, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق منصور- في قوله: {وأقم الصلاة طرفي النهار}، قال: صلاة الفجر، وصلاتي العَشِيِّ. يعني: الظهر، والعصر."}, "36538": {"num": 36538, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {وأقم الصلاة طرفي النهار}، قال: صلاة المغرب، والغَداة."}, "35518": {"num": 35518, "aya": 40, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- {إلا من سبق عليه القول}، قال: العذاب؛ هي امرأتُه كانت في الغابرين."}, "35519": {"num": 35519, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي نهيك- قال: حَمَل نوح معه في السفينة ثمانين إنسانًا، أحدُهم جُرْهُم، وكان لسانه عربيًّا."}, "35520": {"num": 35520, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: كان مع نوح في السفينة ثمانون رجلًا معهم أهلوهم، وكانوا في السفينة مائة وخمسين يومًا."}, "35521": {"num": 35521, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عبد الوهاب بن مجاهد- قال: … فحمل أهلَه وبنيه وبناته وكنائنه."}, "36539": {"num": 36539, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "قال عبد الله بن عباس: يعني: صلاة الغداة، والمغرب."}, "35523": {"num": 35523, "aya": 40, "qail": "الحكم بن عتيبة", "tabaqa": "تابعي", "bab": "", "text": "عن الحكم [بن عتيبة] ="}, "36543": {"num": 36543, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق أبي رجاء- في قوله: {وأقم الصلاة طرفي النهار}، قال: الفجر، والعصر."}, "35525": {"num": 35525, "aya": 40, "qail": "الحكم بن عتيبة", "tabaqa": "تابعي", "bab": "", "text": "عن الحكم [بن عتيبة]-من طريق عبد الملك بن أبي غَنِيَّةَ- {وما آمن معه إلا قليل}، قال: نوح، وثلاثة بنيه، وأربع كنائنه."}, "35526": {"num": 35526, "aya": 40, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وأهلك إلا من سبق عليه القول ومن آمن وما آمن معه إلا قليل}، قال: ذُكِر لنا: أنّه لم يُتِمَّ في السفينة إلا نوحٌ، وامرأته، وثلاثة بنيه، ونساؤهم؛ فجميعهم ثمانية."}, "36549": {"num": 36549, "aya": 114, "qail": "محمد بن كعب القرظي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن محمد بن كعب القُرَظِيِّ -من طريق ابن المبارك، عن أفْلَح بن سعيد- يقول: {أقم الصلاة طرفي النهار}، قال: فطرفا النهار: الفجر، والظهر، والعصر."}, "36550": {"num": 36550, "aya": 114, "qail": "محمد بن كعب القرظي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن محمد بن كعب القرظي -من طريق زيد بن الحباب، عن أفْلَح بن سعيد- {أقم الصلاة طرفي النهار}: الفجر، والعصر."}, "36544": {"num": 36544, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عوف- {أقم الصلاة طرفي النهار}، قال: صلاة الفجر، والمغرب."}, "35530": {"num": 35530, "aya": 40, "qail": "سليمان بن مهران الأعمش", "tabaqa": "تابعي", "bab": "", "text": "عن سليمان بن مهران الأعمش -من طريق سفيان- {وما آمن معه إلا قليل}، قال: كانوا سبعة: نوح، وثلاث كنائن له، وثلاثة بنين."}, "36546": {"num": 36546, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق قُرَّة بن خالد- {أقم الصلاة طرفي النهار}، قال: الغداة، والظهر، والعصر."}, "36547": {"num": 36547, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق المبارك بن فضالة- قال: {أقم الصلاة طرفي النهار}: الغداة، والعصر."}, "35021": {"num": 35021, "aya": 1, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ثم فصلت}، قال: فُسِّرَت."}, "35022": {"num": 35022, "aya": 1, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي بكر الهذلي- في قوله: {كتاب أحكمت آياته ثم فصلت}، قال: أُحْكِمت بالأمر والنهي، وفُصِّلَت بالوعد والوعيد."}, "35023": {"num": 35023, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {كتاب أُحكمت آياته ثم فصلت}، قال: أحكَمَها الله مِن الباطل، ثم فصَّلها بعلمِه، فبيَّن حلاله وحرامه، وطاعته ومعصيته."}, "35024": {"num": 35024, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: أحكمها الله؛ فليس فيها اختِلاف، ولا تَناقُض."}, "35537": {"num": 35537, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق يوسف بن مهران- قال: لَمّا كان نوحٌ في السفينة قَرَضَ الفأرُ حِبال السفينة، فشكا ذلك إلى الله عز وجل، فأوحى اللهُ إليه، فمسح جبهة الأسد، فخرج سِنَّوران. وكان في السفينة عَذِرة، فشكا نوحٌ إلى الله، فأوحى اللهُ إليه، فمَسَح ذَنَب الفيل، فخرج خِنزيران، فأكلا العَذِرة."}, "35538": {"num": 35538, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: تَأَذّى أهلُ السفينة بالفأر، فعطس الأسد، فخرج من مَنخَرِه سِنَّوْران؛ ذكر وأنثى، فأكلا الفأر إلا ما أراد الله أن يبقى منه. وتأذَّوا بأذى أهل السفينة، فعطس الفيل، فخرج مِن منخره خنزيران؛ ذكر وأنثى، فأكلا أذى أهل السفينة، قال: ولَمّا أراد أن يُدخِل الحمارَ السفينةَ أخذ نوحٌ بأُذُنِي الحمار، وأخذ إبليسُ بذَنَبه، فجعل نوح يجذبه، وجعل إبليس يجذبه، فقال نوح: ادخُل، شيطانُ. فدخل الحمارُ، ودخل إبليسُ معه، فلمّا سارت السفينة جلس في أذنابها يَتَغَنّى، فقال له نوح: ويلك، مَن أذِن لك؟ قال: أنت. قال: متى؟ قال: أن قلت للحمار: ادخُل، شيطانُ. فدخلتُ بإذنك."}, "35539": {"num": 35539, "aya": 40, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق يوسف بن مهران- قال: أول ما حمل نوحٌ في الفُلْكِ مِن الدواب الدُّرَّةُ، وآخر ما حمل الحمار، فلمّا دخل الحمارُ أدخل صدره، فتعلَّق إبليس بذنبه، فلم تَسْتَقِلَّ رجلاه، فجعل نوح يقول: ويحك، ادخُل، يا شيطان. فينهض فلا يستطيع، حتى قال نوح: ويحك، ادخل، وإن كان الشيطان معك. كلمةٌ زَلَّت على لسانه، فلمّا قالها نوح خلّى الشيطان سبيله فدخل، ودخل الشيطان معه، فقال له نوح: ما أدْخَلَك، يا عدوَّ الله؟ قال: ألم تقل: ادخل، وإن كان الشيطان معك؟! قال: اخرُج عَنِّي. قال: مالك بُدٌّ مِن أن تحملني. فكان -فيما يزعمون- في ظَهْر الفُلْك."}, "35536": {"num": 35536, "aya": 40, "qail": "علي", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن علي مرفوعًا: «أنّ نوحًا عليه السلام حمل معه في السفينة مِن جميع الشجر»."}, "35029": {"num": 35029, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {من لدن حكيم}، يعني: من عند حكيم."}, "35030": {"num": 35030, "aya": 1, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {حكيم خبير}، قال: خبير بخلقه."}, "35543": {"num": 35543, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق الأعمش- قال: مَرَّ نوح عليه السلام بالأسد وهو في السفينة، فضربه برجله، فخَمَشَه الأسد، فبات ساهِرًا، فشكا نوحٌ مِن ذلك، فأوحى الله إليه: إنّك ظلمتَه، وإنِّي لا أُحِبُّ الظُّلْم."}, "35544": {"num": 35544, "aya": 40, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر، قال: لَمّا حمَل نوح في السفينة مِن كل شيء حمل الأسد، وكان يؤذي أهل السفينة، فأُلقيت عليه الحُمّى."}, "35545": {"num": 35545, "aya": 40, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن الضحاك بن مزاحم -من طريق مقاتل- ="}, "36054": {"num": 36054, "aya": 80, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، في قوله: {أو ءاوي إلى ركن شديد}، قال: قال رسول الله صلى الله عليه وسلم: «رَحِم الله لوطًا، كان يأوي إلى ركن شديد -يعني: الله تعالى-، فما بعث اللهُ بعده نبيًّا إلا في ثَرْوَةٍ مِن قومه»."}, "36055": {"num": 36055, "aya": 80, "qail": "قتادة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة، قال: ذُكِر لنا: أنّ نبي الله صلى الله عليه وسلم كان إذا قرأ هذه الآية قال: «رَحِم الله لوطًا، إن كان لَيَأْوِي إلى رُكْنٍ شديد». وذُكر لنا: أنّ الله لم يبعث نبيًّا بعد لوط إلا في ثروة من قومه، حتى بعث الله نبيَّكم صلى الله عليه وسلم في ثروة مِن قومه."}, "36060": {"num": 36060, "aya": 80, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق مبارك بن فضالة- {أو آوي إلى ركن شديد}، قال: إلى رُكْنٍ مِن الناس."}, "36061": {"num": 36061, "aya": 80, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن [الحسن البصري]-من طريق مبارك- في قوله: {أو آوي إلى ركن شديد}، قال: إلى ركن من الناس شديدٍ يمنعونه، لا واللهِ، ما جادلوه حتى قال: {أليس منكم رجل رشيد}."}, "36062": {"num": 36062, "aya": 80, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: فلم يبعث الله سبحانه بعد لوطٍ نبيًّا إلا في عِزٍّ مِن قومه، وكانت امرأةُ لوطٍ منافقةً؛ تُظْهِر الإسلام، وقلبُها على الكُفْر."}, "36567": {"num": 36567, "aya": 114, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وزلفا من الليل}، قال: العَتَمَة. وما سمعت أحدًا مِن فقهائنا ومشايخنا يقول: العشاء. ما يقولون إلا: العَتَمَة."}, "36064": {"num": 36064, "aya": 80, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {أو آوي إلى ركن شديد}، قال: العشيرة."}, "36065": {"num": 36065, "aya": 80, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط-: قال لوطٌ: {لو أن لي بكم قوة أو ءاوي إلى ركن شديد}، يقول: إلى جُندٍ شديد لَقاتَلْتُكُم."}, "36573": {"num": 36573, "aya": 114, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن ابن عباس، عن النبي صلى الله عليه وسلم، قال: «لم أرَ شيئًا أحسن طلبًا، ولا أسرع إدراكًا من حسنة حديثة لسيئة قديمة؛ {إن الحسنات يذهبن السيئات}»."}, "36067": {"num": 36067, "aya": 80, "qail": "محمد بن إسحاق", "tabaqa": "تابع التابعين", "bab": "", "text": "عن محمد بن إسحاق -من طريق سلمة- قال: {لو أن لي بكم قوة أو آوي إلى ركن شديد}، أي: عشيرة تمنعني، أو شيعة تنصرني؛ لَحُلْتُ بينكم وبين هذا."}, "36068": {"num": 36068, "aya": 80, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن أبي هريرة، أنّ النبي صلى الله عليه وسلم قال: «يغفِر الله لِلُوطٍ، إن كان لَيَأْوِي إلى ركن شديد»."}, "36580": {"num": 36580, "aya": 114, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق شريك، عن منصور- {إن الحسنات يذهبن السيئات}، قال: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر."}, "36070": {"num": 36070, "aya": 80, "qail": "الحسن", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن الحسن، أنّ هذه الآية لَمّا نزلت: {لو أن لي بكم قوة أو ءاوي إلى ركن شديد} قال رسول الله صلى الله عليه وسلم: «رَحِم اللهُ أخي لوطًا، لقد كان يأوي إلى ركن شديد، فلِأَيِّ شيء استكان!»."}, "36581": {"num": 36581, "aya": 114, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق الثوري، عن منصور- في قوله: {إن الحسنات يذهبن السيئات}، قال: الصلوات الخمس."}, "36072": {"num": 36072, "aya": 80, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "آثار متعلقة بالآية", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- في قوله: {أو ءاوي إلى ركن شديد}، قال: بلغني: أنّه لم يُبعَث نبيٌّ بعد لوطٍ إلا في ثروة مِن قومه، حتى النبي صلى الله عليه وسلم."}, "36585": {"num": 36585, "aya": 114, "qail": "محمد بن كعب القرظي", "tabaqa": "تابعي", "bab": "", "text": "عن محمد بن كعب القرظي -من طريق أفْلَح- يقول في قوله: {إن الحسنات يذهبن السيئات}، قال: هُنَّ الصلوات الخمس."}, "36577": {"num": 36577, "aya": 114, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {إن الحسنات يذهبن السيئات}، قال: الصلوات الخمس. {والباقيات الصالحات} [الكهف: 46]، قال: الصلوات الخمس."}, "36583": {"num": 36583, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق حَوْشَب- قال: استَعِينوا على السيِّئات القديمات بالحسنات الحديثات، وإنّكم لن تجدوا شيئًا أذْهَبَ لسيِّئة قديمة مِن حَسَنَة حديثة، وتصديقُ ذلك في كتاب الله: {إن الحسنات يذهبن السيئات}."}, "36584": {"num": 36584, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- {إن الحسنات يذهبن السيئات}، قال: الصلوات الخمس."}, "36588": {"num": 36588, "aya": 114, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق حَوْشَب- في قوله: {ذلك ذكرى للذاكرين}، قال: هُمُ الَّذين يذكرون الله في السَّرّاء والضَّرّاء، والشِّدَّة والرَّخاء، والعافية والبلاء."}, "36579": {"num": 36579, "aya": 114, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأجدع الهمداني -من طريق مزْيَدَةَ بن زيد- {إن الحسنات يذهبن السيئات}، قال: الصَّلَوات الخمس."}, "36582": {"num": 36582, "aya": 114, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جُوَيْبِر- في قوله: {إن الحسنات يذهبن السيئات}، قال: الصلوات الخمس."}, "35059": {"num": 35059, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "قرأ عبد الله بن عباس -من طريق محمد بن عباد بن جعفر-: (ألَآ إنَّهُمْ تَثْنَوْنِي صُدُورُهُمْ)."}, "35060": {"num": 35060, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "قرأ عبد الله بن عباس -من طريق عبد الرحمن الأعرج-: (ألَآ إنَّهُمْ تَثْنَوِنُّ صُدُورُهُمْ)."}, "35061": {"num": 35061, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "قرأ عبد الله بن عباس -من طريق عمرو بن دينار-: {ألَآ إنَّهُمْ يَثْنُونَ صُدُورَهُمْ}."}, "35062": {"num": 35062, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق محمد بن عباد بن جعفر- أنّه قرأ: (ألَآ إنَّهُمْ تَثْنَوْنِي صُدُورُهُمْ). وقال: أُناسٌ كانوا يستحيون أن يَتَخَلَّوا فيُفضُوا إلى السماء، وأن يُجامِعوا نساءَهم فيُفضوا إلى السماء؛ فنَزل ذلك فيهم."}, "35063": {"num": 35063, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق ابن أبي مُليكة- يقول: (ألَآ إنَّهُمْ تَثْنَوْنِي صُدُورُهُمْ). قال: كانوا لا يأتون النساءَ ولا الغائط إلا وقد تَغَشَّوا بثيابهم؛ كراهة أن يُفضُوا بفروجهم إلى السماء."}, "35064": {"num": 35064, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "قال عبد الله بن عباس، في قوله: {ألا إنهم يثنون صدورهم}: نزلت في الأخنس بن شَرِيق، وكان رجلًا حلو الكلام حلوَ المنظر، يلقى رسول الله صلى الله عليه وسلم بما يُحِبُّ، ويَنطَوِي بقلبه على ما يكره."}, "36597": {"num": 36597, "aya": 114, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن مسعود، قال: قال رسول الله صلى الله عليه وسلم: «تحترقون تحترقون، فإذا صلَّيْتُم الصبحَ غَسَلَتْها، ثم تحترقون تحترقون، فإذا صَلَّيْتُمُ الظُّهْرَ غَسَلَتْها، ثم تحترقون تحترقون فإذا صلَّيْتُم العصر غَسَلَتْها، ثم تحترقون تحترقون، فإذا صَلَّيْتُم المغربَ غَسَلَتْها، ثم تحترقون تحترقون، فإذا صلَّيْتُم العشاءَ غَسَلَتْها، ثم تنامون فلا يُكتَبُ عليكم حتى تستيقظوا»."}, "35067": {"num": 35067, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {ألا إنهم يثنون صدورهم}، قال: الشكُّ في الله، وعمل السيئات."}, "35068": {"num": 35068, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {ألا إنهم يثنون صدورهم}، يقول: يكتمون ما في قلوبهم."}, "35069": {"num": 35069, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ألا إنهم يثنون صدورهم}، قال: يَكُنُّون."}, "35070": {"num": 35070, "aya": 5, "qail": "أبي رزين مسعود بن مالك الأسدي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي رزين [مسعود بن مالك الأسدي]-من طريق منصور- في الآية، قال: كان أحدهم يَحْنِي ظهرَه، ويستغشي بثوبه."}, "35071": {"num": 35071, "aya": 5, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {يثنون صدورهم} قال: تضيق شكًّا وامتراء في الحق؛ {ليستخفوا منه} قال: مِن الله إن استطاعوا."}, "35073": {"num": 35073, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: {يثنون صدورهم} على ما هُم عليه من الكفر؛ {ليستخفوا منه} بذلك، يظنون أنّ الله عز وجل لا يعلم الذي يستخفون به. قال بعضهم: هم المنافقون."}, "35074": {"num": 35074, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق هشام- {ألا إنهم يثنون صدورهم}، قال: حديث النفس."}, "35075": {"num": 35075, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- في قوله: {ألا إنهم يثنون صدورهم ليستخفوا منه}: وهو من جهالتهم به."}, "35076": {"num": 35076, "aya": 5, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في الآية، قال: كانوا يَحْنُون صدورهم لكيلا يسمعوا كتاب الله."}, "36611": {"num": 36611, "aya": 116, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في الآية، قال: أي: لَم يكُن مِن قبلِكم مَن يَنْهى عنِ الفساد في الأرض إلا قليلًا."}, "36614": {"num": 36614, "aya": 116, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجّاج- {إلا قليلًا ممن أنجينا منهم}: يَسْتَقِلُّهم اللهُ مِن كُلِّ قوم."}, "35081": {"num": 35081, "aya": 5, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ألا إنهم يثنون صدورهم ليستخفوا منه}، قال: هذا حين يناجي بعضُهم بعضًا. وقرأ: {ألا حين يستغشون ثيابهم} الآية."}, "35082": {"num": 35082, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {ألا حين يستغشون ثيابهم يعلم ما} عمِلوا بالليل والنهار."}, "35083": {"num": 35083, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ألا إنهم يثنون صدورهم} قال: يَكُنُّون، {ألا حين يستغشون ثيابهم} قال: يُغَطُّون رُءوسَهم."}, "35084": {"num": 35084, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس -من طريق عكرمة- {يستغشون ثيابهم}: يستكبر، أو يَسْتَكِنُّ مِن الله، والله يراه؛ {يعلم ما يسرون وما يعلنون}."}, "36108": {"num": 36108, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- قال: لَمّا جاءت رسلُ اللهِ لوطًا عليه السلام ظَنَّ أنّهم ضِيفانٌ لقوه، فأدناهم حتى أقعدهم قريبًا، وجاء ببناته، وهُنَّ ثلاثة، فأقْعَدَهُنَّ بين ضيفانه وبين قومه، فجاءه قومه يُهرَعون إليه، فلمّا رآهم قال: {هؤلاء بناتي هن أطهر لكم فاتقوا الله ولا تخزون في ضيفي}. قالوا: {ما لنا في بناتك من حق وإنك لتعلم ما نريد}. قال: {لو أن لي بكم قوة أو ءاوي إلى ركن شديد}. فالتفت إليه جبريل عليه السلام، فقال: {إنا رسل ربك لن يصلوا إليك}. فلمّا دَنَوْا طَمَسَ أعينَهم، فانطلقوا عُميًا يركب بعضهم بعضًا، حتى إذا خرجوا إلى الذين بالباب قالوا: جئناكم مِن عند أسْحَرِ الناس. ثم رُفِعَتْ في جوف الليل، حتى إنّهم لَيَسْمَعون صوت الطير في جوِّ السماء، ثم قُلبت عليهم، فمَن أصابته الائتِفاكة أهلكته، ومَن خرج منها أتبَعَته حيث كان حجرًا فقتلته، فارتحل ببناته، حتى بلغ مكان كذا مِن الشام ماتت ابنتُه الكبرى، فخرجت عندها عينٌ، ثم انطلق حيث شاء الله أن يبلغ فماتت الصغرى، فخرجت عندها عين، فما بقي مِنهُنَّ إلا الوُسْطى."}, "35086": {"num": 35086, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- في قوله: {ألا إنهم يثنون صدورهم ليستخفوا منه ألا حين يستغشون ثيابهم} قال: من جهالتهم به، قال الله: {ألا حين يستغشون ثيابهم} في ظُلْمَة الليل في أجوف بيوتهم {يعلم} تلك الساعة {ما يسرون وما يعلنون إنه عليم بذات الصدور}."}, "35087": {"num": 35087, "aya": 5, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في الآية، قال: كانوا يحنون صدورهم لكيلا يسمعوا كتاب الله، قال تعالى: {ألا حين يستغشون ثيابهم يعلم ما يسرون}. وذلك أخفى ما يكون ابنُ آدم، إذا حنى ظهره، واستغشى بثوبه، وأضمر هَمَّه في نفسه، فإنّ الله لا يخفى ذلك عليه."}, "36109": {"num": 36109, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الكلبي، عن أبي صالح- قال: أغْلَقَ لوطٌ على ضيفه الباب، فجاءوا، فكسروا الباب، ودخلوا، فطمس جبريلُ أعينَهم، فذهبت أبصارهم، قالوا: يا لوط، جِئْتَنا بسَحَرَة. فتَوَعَّدوه، فأوجس في نفسه خيفة، قال: يذهب هؤلاء ويَذَرُوني؟ قال جبريل: لا تخف؛ إنّا رُسُل ربك، إن موعدَهم الصبح. قال لوط: الساعةَ. قال جبريل: أليس الصبح بقريب؟! قال: الساعةَ. فرُفِعت حتى سَمِع أهلُ السماء الدنيا نبيح الكلاب، ثم أُقلِبت، ورُمُوا بالحجارة."}, "36111": {"num": 36111, "aya": 82, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {فلما جاء أمرنا جعلنا عاليها سافلها}، قال: لَمّا أصبحوا غدا جبريلُ على قريتهم، ففَتَقَها مِن أركانها، ثم أدخل جناحه، ثم حملها على خَوافِي جناحيه بما فيها، ثُمَّ صعد بها إلى السماء حتى سمع أهل السماء نباح كلابهم، ثم قلبها، فكان أول ما سقط منها سُرادِقُها، فلم يُصِب قومًا ما أصابهم؛ إنّ الله طمَس على أعينهم، ثم قلب قريتهم، وأمطر عليهم حجارة مِن سِجِّيل."}, "36619": {"num": 36619, "aya": 116, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد-: {واتبع الذين ظلموا ما أترفوا فيه} في دُنْياهم، وإنّ هذه الدنيا قد تَقَعَّدتْ أكثرَ الناسِ، وأَلْهَتْهُم عن آخرتهم."}, "35091": {"num": 35091, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- {إنه عليم بذات الصدور}: يعلم تلك الساعة."}, "36115": {"num": 36115, "aya": 82, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: ذُكِر لنا: أنّ جبريل عليه السلام أخذ بعُرْوَتِها الوسطى، ثم ألْوى بها إلى جَوِّ السماء حتى سمعت الملائكة ضواغي كلابهم، ثم دَمَّر بعضَها على بعض، ثم أتبع شُذّانَ القومِ صخرًا. قال: وهي ثلاث قرى، فيها من العدد ما شاء الله أن يكون من الكثرة، ذُكِر لنا: أنّه كان مِنها أربعة آلاف ألف، وهي سدوم؛ قرية بين المدينة والشام."}, "36116": {"num": 36116, "aya": 82, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: ذُكِر لنا: أنّ جبريل عليه السلام أخذ بعُرْوَتها الوسطى، ثم ألْوى بها إلى جَوِّ السماء حتى سمعت الملائكة ضواغي كلابهم، ثم دَمَّر بعضها على بعض، ثم أتبع شُذّانَ القوم صخرًا. قال: وهي ثلاث قرى يُقال لها: سدوم. وهي بين المدينة والشام. قال: وذُكِر لنا: أنّه كان فيها أربعة آلاف ألف. وذُكِر لنا: أنّ إبراهيم عليه السلام كان يُشرف، يقول: سدوم؛ يومٌ ما لَكِ!."}, "35094": {"num": 35094, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {وما من دابة في الأرض إلا على الله رزقها}، يعني: كل دابَّة."}, "35095": {"num": 35095, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جُرَيْج- في قوله: {وما من دابة في الأرض إلا على الله رزقها}، يعني: ما جاءها مِن رزق فمِن الله، ورُبَّما لم يرزقها حتى تموت جوعًا، ولكن ما كان مِن رزق لها فمِن الله."}, "36117": {"num": 36117, "aya": 82, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- قال: بلغنا: أنّ جبريل عليه السلام لَمّا أصبح نَشَر جناحَه، فانتَسَفَ به أرضَهم بما فيها مِن قصورها، ودوابِّها، وحجارتها، وشجرها وجميع ما فيها، فضمَّها في جناحه، فحَواها وطواها في جوف جناحه، ثم صعد بها إلى السماء الدنيا، حتى سمع سكان السماء أصوات الناس والكلاب، وكانوا أربعة آلاف ألف، ثم قلبها فأرسلها إلى الأرض منكوسة، دَمْدَم بعضَها على بعض، فجعل عاليها سافلها، ثم أتبعها حجارة مِن سِجِّيل."}, "36118": {"num": 36118, "aya": 82, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السدي -من طريق أسباط- قال: لَمّا أصبحوا -يعني: قوم لوط- نزل جبريل فاقتلع الأرض مِن سبع أرَضِين، فحملها حتى بلغ السماء الدنيا، حتى سمع أهلُ السماء نباحَ كلابهم وأصوات ديوكهم، ثم قلبها، فقتلهم، فذلك حين يقول: {والمؤتفكة أهوى} [النجم: 53]: المنقلبة حين أهوى بها جبريل الأرض، فاقتلعها بجناحه، فمَن لم يَمُتْ حين أسقط الأرضَ أمطر الله عليه وهو تحت الأرض الحجارة، ومَن كان منهم شاذًّا في الأرض، وهو قول الله عز وجل: {فجعلنا عاليها سافلها وأمطرنا عليهم"}, "35098": {"num": 35098, "aya": 6, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود، عن النبي صلى الله عليه وسلم، قال: «إذا كان أجلُ أحدِكم بأرضٍ أُتِيحَت له إليها حاجة، حتى إذا بلغ أقصى أثرَه منها فيُقْبَض، فتقول الأرض يوم القيامة: هذا ما استودعتني»."}, "35099": {"num": 35099, "aya": 6, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق قيس بن أبي حازم-، نحوه موقوفًا."}, "35100": {"num": 35100, "aya": 6, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق إبراهيم- في قوله: {ويعلم مستقرها ومستودعها}، قال: مستقرها في الأرحام، ومستودعها حيث تموت."}, "35101": {"num": 35101, "aya": 6, "qail": "عبد الله", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله -من طريق إبراهيم- قال: {مستقرها} في الدنيا، {ومستودعها} في الآخرة."}, "35102": {"num": 35102, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مقسم- في قوله: {ويعلم مستقرها} قال: حيث تأوي، {ومستودعها} قال: حيث تموت."}, "35103": {"num": 35103, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- في قوله: {ويعلم مستقرها}، قال: يأتيها رِزْقُها حيث كانت."}, "35104": {"num": 35104, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- قوله: {ويعلم مستقرها ومستودعها}، فالمستقر: ما كان في الرَّحِم، والمستودع: ما كان في الصُّلْب."}, "35105": {"num": 35105, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق إسماعيل السدي، عن رجل حدَّثه- {ويعلم مستقرها}، قال: مستقرها في الأرض."}, "35106": {"num": 35106, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: المستقر: ما كان في أرحام النساء، والمستودع قال: ما كان في أصلاب الرجال."}, "36122": {"num": 36122, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {حجارة من سجيل}، قال: حجارة فيها طين."}, "36123": {"num": 36123, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- في قوله: {حجارة من سجيل}، قال: مِن طين."}, "36125": {"num": 36125, "aya": 82, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق جعفر- {حجارة من سجيل}، قال: فارسية أُعْرِبَت؛ سَنك وكِل."}, "36126": {"num": 36126, "aya": 82, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- قال: {سجيل} فارسية ونبطية: سج إيل."}, "36127": {"num": 36127, "aya": 82, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن نَجِيح- في قوله: {حجارة من سجيل}، قال: بالفارسية أوَّلها حجارة، وآخرها طين."}, "36130": {"num": 36130, "aya": 82, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "وإسماعيل السُّدِّيّ، نحو ذلك."}, "36131": {"num": 36131, "aya": 82, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر: {حجارة من سجيل}، قال: هي كلمة أعجمية عُرِّبت؛ سِنك وكِل."}, "36134": {"num": 36134, "aya": 82, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة -من طريق مَعْمَر- في قوله: {حجارة من سجيل}، قالا: مِن طين منضود."}, "36649": {"num": 36649, "aya": 119, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- {ولذلك خلقهم}، قال: لِلرَّحمة."}, "35116": {"num": 35116, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح-: {ويعلم مستقرها} في الرَّحِم، {ومستودعها} في الصُّلْب. مثل التي في الأنعام."}, "36650": {"num": 36650, "aya": 119, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر -من طريق ابن جُرَيْج- قال: خلق أهلَ الحقِّ ومَن اتبعه لرحمته."}, "36142": {"num": 36142, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس، في قوله: {منضود}: مُتَتابِع، يتبع بعضها بعضًا."}, "36143": {"num": 36143, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق السدي- {منضود}: مختّمة."}, "36654": {"num": 36654, "aya": 119, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق مبارك بن فضالة- {ولذلك خلقهم}، قال: للاختلاف."}, "36145": {"num": 36145, "aya": 82, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة -من طريق مَعْمَر- في قوله: {حجارة من سجيل}، قالا: مِن طين منضود، مصفوفة مسوَّمة مُطَوَّقة."}, "35122": {"num": 35122, "aya": 6, "qail": "الربيع بن أنس", "tabaqa": "تابعي", "bab": "", "text": "عن الربيع بن أنس -من طريق أبي جعفر- قوله: {ويعلم مستقرها ومستودعها}، قال: مستقرها: أيام حياتها. ومستودعها: حيث تموت ومِن حيثُ تُبْعَث."}, "36146": {"num": 36146, "aya": 82, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {منضود}، أي: بعضه على بعض."}, "36655": {"num": 36655, "aya": 119, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق منصور- {ولذلك خلقهم}، قال: خَلَقهم للرَّحمة."}, "36656": {"num": 36656, "aya": 119, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق منصور بن عبد الرحمن- في قوله: {ولذلك خلقهم}، قال: خَلَق هؤلاء لِجَنَّته، وهؤلاء للنار، وخلق هؤلاء لِرحمته، وهؤلاء لعذابه."}, "36658": {"num": 36658, "aya": 119, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق طلحة بن عمرو- في قوله: {ولا يزالون مختلفين} قال: يهود، ونصارى، ومجوس، {إلا من رحم ربك} قال: مَن جعله على الإسلام، {ولذلك خلقهم} قال: مؤمن وكافر."}, "36659": {"num": 36659, "aya": 119, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، {ولذلك خلقهم}، قال: للرِّحمة والعبادة، ولم يخلقهم للاختلاف."}, "36660": {"num": 36660, "aya": 119, "qail": "سليمان بن مهران الأعمش", "tabaqa": "تابعي", "bab": "", "text": "عن سليمان بن مهران الأعمش -من طريق سفيان- {ولذلك خلقهم}، قال: مؤمن وكافر."}, "36667": {"num": 36667, "aya": 120, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس، في قوله: {ما نثبت به فؤادك}: نشدد."}, "36672": {"num": 36672, "aya": 120, "qail": "أبي موسى الأشعري", "tabaqa": "صحابي", "bab": "", "text": "عن أبي موسى الأشعري -من طريق أبي إياس- {وجاءك في هذه الحق}، قال: في هذه السورة."}, "35650": {"num": 35650, "aya": 46, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن ابن عباس، عن النبيِّ صلى الله عليه وسلم أنّه قرأ: «إنَّهُ عَمِلَ غَيْرَ صالِحٍ»."}, "36674": {"num": 36674, "aya": 120, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- {وجاءك في هذه الحق}، قال: في هذه السورة."}, "36675": {"num": 36675, "aya": 120, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحِيِّ -من طريق الربيع بن أنس- قال: هذه السورة."}, "35653": {"num": 35653, "aya": 46, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سليمان بن قتة- أنّه قرأ: «عَمِلَ غَيْرَ صالِحٍ»."}, "36677": {"num": 36677, "aya": 120, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- {وجاءك في هذه الحق}، قال: في هذه السورة."}, "35655": {"num": 35655, "aya": 46, "qail": "أبي جعفر الرازي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي جعفر الرازي، قال: سألتُ زيد بن أسلم: كيف تقرأ هذا الحرف؟ قال: {عَمَلٌ غَيْرُ صالِحٍ}."}, "35656": {"num": 35656, "aya": 46, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- قال: ما بَغَتِ امرأةُ نبيٍّ قطُّ، وقوله: {إنه ليس من أهلك} يقول: إنّه ليس مِن أهلك الذين وعدتُك أن أنجيهم معك."}, "35657": {"num": 35657, "aya": 46, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: هو ابنه، غير أنّه خالفه في العَمَلِ والنِّيَّة. قال عكرمة في بعض الحروف: (إنَّهُ عَمِلَ عَمَلًا غَيْرَ صالِحٍ)، والخيانة تكون على غير باب."}, "36678": {"num": 36678, "aya": 120, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي رجاء- {وجاءك في هذه الحق}، قال: في هذه السورة."}, "36679": {"num": 36679, "aya": 120, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: في الدُّنيا."}, "36680": {"num": 36680, "aya": 120, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق شعبة- {وجاءك في هذه الحق}، قال: في هذه الدنيا."}, "36681": {"num": 36681, "aya": 120, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وجاءك في هذه الحق}، قال: في هذه السورة."}, "35662": {"num": 35662, "aya": 46, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق أبي معاوية البجلي- أنّه جاء إليه رجلٌ، فسأله، فقال: أرأيتك ابن نوح ابنه؟ فسبَّح طويلًا، ثم قال: لا إله إلا الله، يُحَدِّث اللهُ محمدًا: {ونادى نوح ابنه}، وتقول ليس منه! ولكن خالفه في العمل، فليس مِنه مَن لم يؤمن."}, "35663": {"num": 35663, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق جابر- ="}, "35665": {"num": 35665, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- قال: كلُّ نبيٍّ أبو أُمَّتِه."}, "35666": {"num": 35666, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- في قوله: {فلا تسألن ما ليس لك به علم}، قال: بيَّن الله لنوح عليه السلام أنّه ليس بابنه."}, "35667": {"num": 35667, "aya": 46, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مُزاحِم -من طريق جُوَيْبِر- قال: هو -واللهِ- ابنُه لِصُلْبِه."}, "35668": {"num": 35668, "aya": 46, "qail": "بزيع", "tabaqa": "", "bab": "", "text": "قال بَزِيعٌ: سأل رجلٌ الضحاك عن ابن نوح. فقال: ألا تعجبون إلى هذا الأحمق يسألني عن ابن نوح؟! وهو ابنُ نوح كما قال الله: [{ونادى نوح ابنه}]."}, "35669": {"num": 35669, "aya": 46, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق عبيد- أنّه قرأ: {ونادى نوح ابنه}، وقوله: {ليس من أهلك}، قال: يقول: ليس هو مِن أهلك. قال: يقول: ليس هو مِن أهل وِلايتك، ولا مِمَّن وعدتُك أن أُنجي مِن أهلِك، {إنه عمل غير صالح} قال: يقول: كان عملُه في شِرْكٍ."}, "35672": {"num": 35672, "aya": 46, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف، ومنصور- في قوله: {إنه ليس من أهلك}، قال: لم يكن ابنَه. وكان يقرؤها: «إنَّهُ عَمِلَ غَيْرَ صالِحٍ»."}, "35673": {"num": 35673, "aya": 46, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- يقرأ هذه الآية: {إنَّهُ ليس من أهلك إنه عمل غير صالح}، فقال عند ذلك: واللهِ، ما كان ابنَه. ثم قرأ هذه الآية: {فخانتاهما} [التحريم: 10]."}, "35677": {"num": 35677, "aya": 46, "qail": "أبي جعفر محمد بن علي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي جعفر محمد بن علي -من طريق جابر- في قوله: {ونادى نوح ابنه}، قال: هي بلغةِ طيِّءٍ، لم يكن ابنَه، وكان ابنَ امرأتِه."}, "35678": {"num": 35678, "aya": 46, "qail": "أبي جعفر محمد بن علي الباقر", "tabaqa": "تابعي", "bab": "", "text": "عن أبي جعفر [محمد بن علي الباقر]-من طريق ثوير- {إنه ليس من أهلك}، قال: لو كان مِن أهله لَنَجا."}, "36191": {"num": 36191, "aya": 84, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {إني أراكم بخير}، قال: يعني: خير الدنيا، وزينتها."}, "36192": {"num": 36192, "aya": 84, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {إني أراكم بخير}: أبْصَر عليهم قِشْرًا مِن قِشْرِ الدنيا وزينتها."}, "36194": {"num": 36194, "aya": 84, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {إني أراكم بخير}، قال: في دنياكم، كما قال الله تعالى: {إن ترك خيرا} [البقرة: 180]، سمّاه: خيرًا؛ لأنّ الناس يُسَمُّون المالَ: خيرًا."}, "35685": {"num": 35685, "aya": 46, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- قال: إنّ نساء الأنبياء لا يَزْنِين. وكان يقرؤها: {إنه عمل غير صالح}، يقول: مسألتُك إيّاي -يا نوح- عمل غيرُ صالح لا أرضاه لك."}, "35686": {"num": 35686, "aya": 46, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {إنَّهُ عَمَلٌ غَيْرُ صالِحٍ}، يقول: سؤالك عمّا ليس لك به علم."}, "35687": {"num": 35687, "aya": 46, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- {إنَّهُ عَمَلٌ غَيْرُ صالِحٍ}، قال: كان مُخالِفًا في النِّيَّة والعمل."}, "35688": {"num": 35688, "aya": 46, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق يعقوب بن قيس- أنّه قرأ: «إنَّهُ عَمِلَ غَيْرَ صالِحٍ»، قال: معصية نبيِّ الله."}, "35689": {"num": 35689, "aya": 46, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق مُغِيرة- {إنَّهُ عَمَلٌ غَيْرُ صالِحٍ}، قال: إنّ مسألتك إيّاي هذه عَمَلٌ غيرُ صالح."}, "35690": {"num": 35690, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق الأعمش- قوله: {إنَّهُ عَمَلٌ غَيْرُ صالِحٍ}، قال: سؤالك إيّاي عمل غير صالح، {فلا تسألن ما ليس لك به علم}."}, "35691": {"num": 35691, "aya": 46, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مُزاحِم: «إنَّهُ عَمِلَ غَيْرَ صالِحٍ»، قال: كان عملُه كفرًا بالله."}, "35693": {"num": 35693, "aya": 46, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عون- أنّه قرأ: {إنَّهُ عَمَلٌ غَيْرُ صالِحٍ}، قال: كان ولد زنية، وكان يُنسَب إليه، فنفاه الله منذ يوم الغرق."}, "35694": {"num": 35694, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {إنه عمل غير صالح} أي: سوء، {فلا تسألن ما ليس لك به علم}."}, "35695": {"num": 35695, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {إنه عمل غير صالح}: سؤالك إيّاي ما ليس لك به علم."}, "35696": {"num": 35696, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في الآية، قال: إنّه لَمّا نهاه أن يُراجِعَه في أحَدٍ كان العمل غير صالح مراجعة ربه. في قراءة عبد الله [بن مسعود]: (أن تَسْأَلَنِي ما لَيْسَ لَكَ بِهِ عِلْمٌ). وعن غير قتادة: كان اسم ابنِ نوح الذي غرق: كنعان. وقال قتادة: خالف نوحًا في النية والعمل."}, "36209": {"num": 36209, "aya": 86, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سفيان، عمَّن ذَكَرَه- في قوله: {بقيت الله}، قال: رِزْق الله."}, "36210": {"num": 36210, "aya": 86, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: يعني: ما أبْقى اللهُ لكم مِن الحلال بعد إيفاء الكيل والوَزْنِ خيرٌ مِمّا تأخذونه بالتَّطْفِيف."}, "35699": {"num": 35699, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {فلا تسألن ما ليس لك به علم}، قال: بينَّ الله لنوح عليه السلام أنّه ليس بابنه."}, "35700": {"num": 35700, "aya": 46, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: {فلا تسألن ما ليس لك به علم}، أي: أنّك لم تكن تعلم ما يُسِرُّ مِن النِّفاق."}, "36213": {"num": 36213, "aya": 86, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {بقيت الله خير لكم}، يقول: حَظُّكم مِن ربِّكم خيرٌ لكم."}, "36617": {"num": 36617, "aya": 116, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- {واتبع الذين ظلموا ما أُترِفُوا فيه}، قال: في مُلكِهم، وتجبُّرِهم، وتركِهم الحقَّ."}, "35257": {"num": 35257, "aya": 17, "qail": "الحسين بن علي", "tabaqa": "", "bab": "", "text": "عن الحسين بن علي -من طريق سليمان العلاف- في قوله: {ويتلوه شاهد منه}، قال: محمد صلى الله عليه وسلم هو الشّاهِد من الله."}, "35258": {"num": 35258, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الكلبي، عن أبي صالح- قال: {أفمن كان على بينة من ربه} رسول الله صلى الله عليه وسلم، {ويتلوه شاهد منه} عليٌّ خاصَّته."}, "35259": {"num": 35259, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {أفمن كان على بينة من ربه} قال: محمد صلى الله عليه وسلم، {ويتلوه شاهد منه} قال: جبريل، فهو شاهِد مِن الله بالذي يتلو مِن كتاب الله الذي أُنزِل على محمد صلى الله عليه وسلم."}, "35260": {"num": 35260, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: جبريل. يعني: قوله: {ويتلوه شاهد منه}."}, "35263": {"num": 35263, "aya": 17, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحِيِّ -من طريق الربيع بن أنس- في قوله: {أفمن كان على بينة من ربه} قال: ذاك محمد صلى الله عليه وسلم، {ويتلوه شاهد منه} هو جبريل."}, "35265": {"num": 35265, "aya": 17, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {أفمن كان على بينة من ربه} قال: محمد صلى الله عليه وسلم، {ويتلوه شاهد منه} قال: جبريل. (8/ 28)"}, "35266": {"num": 35266, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {أفمن كان على بينة من ربه} قال: هو محمد صلى الله عليه وسلم ="}, "35269": {"num": 35269, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {أفمن كان على بينة من ربه} قال: هو محمد صلى الله عليه وسلم، {ويتلوه شاهد منه} قال: مَلَك يحفظه."}, "35270": {"num": 35270, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- قال: هو جبرئيل، تلا التوراةَ والإنجيلَ والقرآنَ، وهو الشاهِد مِن الله."}, "35271": {"num": 35271, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أيوب- {أفَمَن كانَ عَلى بَيِّنَةٍ مِن رَبِّهِ ويَتْلُوهُ شاهِدٌ مِنهُ}، قال: جبريل عليه السلام، والتالي: التابِع. وقرأ: {والقَمَرِ إذا تَلاها} [الشمس: 2]."}, "35272": {"num": 35272, "aya": 17, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أيوب- {ويَتْلُوهُ شاهِدٌ مِنهُ}، قال: المَلك يحفظه، {يَتْلُونَهُ حَقَّ تِلاوَتِهِ} [البقرة: 121]، قال: يتَّبِعونه حقَّ اتِّباعِه."}, "35275": {"num": 35275, "aya": 17, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري، في قوله: {أفمن كان على بينة من ربه}، قال: المؤمن على بيِّنة من ربه."}, "35276": {"num": 35276, "aya": 17, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي رجاء- {ويتلوه شاهد منه}، قال: لِسانُه."}, "36302": {"num": 36302, "aya": 92, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "واتخذتموه وراءكم ظهريا}", "text": "عن مجاهد بن جبر -من طريق جابر- في قوله: {واتخذتموه ورآءكم ظهريًا}، قال: نَبَذْتُم أمرَه."}, "35279": {"num": 35279, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {أفمن كان على بينة من ربه}: وهو محمد، كان على بيِّنة مِن ربه."}, "35280": {"num": 35280, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- {ويتلوه شاهد منه}، قال: لِسانه هو الشّاهِد."}, "36303": {"num": 36303, "aya": 92, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "واتخذتموه وراءكم ظهريا}", "text": "عن مجاهد بن جبر -من طريق ابن أبي نَجِيح- {واتخذتموه وراءكم ظهريا}، قال: استثناؤهم رهطَ شعيب، وتركهم ما جاء به شعيبٌ وراءَ ظهورهم ظهريًّا."}, "35287": {"num": 35287, "aya": 17, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {أفمن كان على بينة من ربه ويتلوه شاهد منه}، قال: رسول الله صلى الله عليه وسلم كان على بيِّنة من ربِّه، والقرآن يتلوه شاهد منه أيضًا مِن الله بأنّه رسول الله صلى الله عليه وسلم."}, "35288": {"num": 35288, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- {ومن قبله كتاب موسى}، قال: ومن قبله تلا التوراةَ على لسان موسى، كما تلا القرآنَ على لسان محمد صلى الله عليه وسلم."}, "35289": {"num": 35289, "aya": 17, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق منصور- {ومن قبله كتاب موسى}، قال: ومِن قبله جاء بالكتاب إلى موسى."}, "36119": {"num": 36119, "aya": 82, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- قال: لَمّا أصبحوا نزل جبريل عليه السلام، فاقتلع الأرض مِن سبع أرَضِين، فحملها حتى بلغ السماء الدنيا، ثم أهوى بها جبريل إلى الأرض."}, "35296": {"num": 35296, "aya": 17, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- قال: قال رسول الله صلى الله عليه وسلم: «ما مِن أحد يسمع بي مِن هذه الأمة، ولا يهوديٌّ ولا نصرانيٌّ، ولا يؤمن بي؛ إلا دخل النار». فجعلتُ أقول: أين تصديقُها في كتاب الله؟ وقلَّما سمعت حديثًا عن النبي صلى الله عليه وسلم إلا وجدت تصديقه في القرآن، حتى وجدت هذه الآية: {ومن يكفر به من الأحزاب فالنار موعده}. قال: الأحزاب: الملَل كلها."}, "35298": {"num": 35298, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {ومن يكفر به من الأحزاب}، قال: الكُفّار أحزابٌ، كلُّهم على الكفر."}, "35299": {"num": 35299, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة، {ومن يكفر به من الأحزاب}، قال: مِن اليهود، والنصارى."}, "35300": {"num": 35300, "aya": 17, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ومن الأحزاب من ينكر بعضه} [الرعد: 36]، أي: يكفر ببعضه، وهم اليهود، والنصارى. قال: بلغنا: أنّ نبي الله صلى الله عليه وسلم كان يقول: «لا يسمع بي أحد مِن هذه الأُمَّةِ ولا يهوديٌّ ولا نصرانيٌّ، ثم يموت قبل أن يؤمن بي؛ إلا دخل النار»."}, "36121": {"num": 36121, "aya": 82, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق السدي- في قوله: {حجارة من سجيل}، قال: هي بالفارسية: سَنك وكِل؛ حجر وطين."}}, "n_athar": {"0": 13, "1": 14, "2": 2, "3": 21, "4": 3, "5": 35, "6": 38, "7": 33, "8": 15, "9": 3, "10": 2, "11": 6, "12": 11, "13": 10, "14": 5, "15": 27, "16": 9, "17": 50, "18": 17, "19": 8, "20": 8, "21": 4, "22": 2, "23": 8, "24": 7, "25": 3, "26": 1, "27": 11, "28": 11, "29": 7, "30": 1, "31": 6, "32": 4, "33": 2, "34": 3, "35": 4, "36": 10, "37": 19, "38": 23, "39": 7, "40": 82, "41": 16, "42": 9, "43": 12, "44": 56, "45": 3, "46": 59, "47": 1, "48": 20, "49": 7, "50": 3, "51": 5, "52": 11, "53": 2, "54": 11, "56": 7, "57": 6, "58": 3, "59": 5, "60": 4, "61": 11, "62": 2, "63": 4, "64": 1, "65": 11, "66": 4, "67": 10, "68": 7, "69": 38, "70": 9, "71": 29, "72": 12, "73": 9, "74": 21, "75": 24, "76": 3, "77": 22, "78": 40, "79": 6, "80": 19, "81": 33, "82": 44, "83": 31, "84": 14, "85": 14, "86": 12, "87": 20, "88": 15, "89": 12, "90": 6, "91": 21, "92": 19, "93": 7, "94": 5, "95": 3, "96": 2, "97": 1, "98": 8, "99": 9, "100": 16, "101": 14, "102": 6, "103": 11, "104": 3, "105": 9, "106": 9, "107": 37, "108": 26, "109": 8, "110": 4, "111": 1, "112": 14, "113": 12, "114": 87, "115": 3, "116": 14, "117": 3, "118": 20, "119": 21, "120": 18, "121": 3, "122": 3, "123": 10}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});